-- i18n: en/es translations of every "biologia" question
-- (322 questions x 2 locales = 644 rows). Only writes
-- question_translations; questions (the pt-BR original, including
-- correct_index) is never touched.
--
-- options keep exactly the original order: correct_index is positional and
-- is always read from the original row. The join below also refuses any row
-- whose option count differs from the original, so a bad line can never
-- turn into a question with the wrong answer marked.
--
-- Keyed by the real questions.id read from the live database. Idempotent
-- (on conflict do update). Check afterwards with i18n_questions_checkup.sql.

insert into question_translations (question_id, locale, prompt, options, explanation)
select v.id::uuid, v.locale, v.prompt, v.options, v.explanation
from (values
  ('77bf8716-acfb-4e0a-a152-8a9812d92a3d', 'en',
   'Photosynthesis, a fundamental process carried out by plants, takes place mainly:',
   array['In the chloroplasts of plant cells, using sunlight, water and carbon dioxide', 'In the mitochondria, with no involvement of sunlight', 'Exclusively in the roots of plants', 'Only at night, in the absence of light'],
   'Photosynthesis converts light energy into chemical energy (glucose) and takes place in the chloroplasts.'),
  ('77bf8716-acfb-4e0a-a152-8a9812d92a3d', 'es',
   'La fotosíntesis, proceso fundamental que realizan las plantas, ocurre principalmente:',
   array['En los cloroplastos de las células vegetales, usando luz solar, agua y dióxido de carbono', 'En las mitocondrias, sin ninguna participación de la luz solar', 'Exclusivamente en las raíces de las plantas', 'Solo durante la noche, en ausencia de luz'],
   'La fotosíntesis convierte la energía luminosa en energía química (glucosa) y ocurre en los cloroplastos.'),
  ('c26a4487-1132-4ead-a639-695ec6e53936', 'en',
   'The main functions of plant roots are:',
   array['Anchoring the plant in the soil and absorbing water and mineral salts', 'Carrying out photosynthesis directly', 'Producing flowers and fruits', 'Carrying out the plant''s sexual reproduction'],
   'Roots anchor the plant to the substrate and absorb water and mineral nutrients from the soil.'),
  ('c26a4487-1132-4ead-a639-695ec6e53936', 'es',
   'Las principales funciones de las raíces de las plantas son:',
   array['Fijar la planta al suelo y absorber agua y sales minerales', 'Realizar directamente la fotosíntesis', 'Producir flores y frutos', 'Realizar la reproducción sexual de la planta'],
   'Las raíces anclan la planta al sustrato y absorben agua y nutrientes minerales del suelo.'),
  ('64c56faa-d91c-44e9-b0ea-1a97743bf99d', 'en',
   'Xylem, a conducting tissue found in vascular plants, is mainly responsible for transporting:',
   array['Water and mineral salts, from the roots to the rest of the plant', 'Phloem sap (rich in sugars), from the leaves to the rest of the plant', 'Only gases, such as oxygen and carbon dioxide', 'Pollen between different flowers'],
   'Xylem carries raw sap (water and minerals) from the roots to the leaves and other organs of the plant.'),
  ('64c56faa-d91c-44e9-b0ea-1a97743bf99d', 'es',
   'El xilema, tejido conductor presente en las plantas vasculares, se encarga principalmente de transportar:',
   array['Agua y sales minerales, desde las raíces hasta las demás partes de la planta', 'Savia elaborada (rica en azúcares), desde las hojas al resto de la planta', 'Exclusivamente gases, como oxígeno y dióxido de carbono', 'Polen entre diferentes flores'],
   'El xilema conduce la savia bruta (agua y minerales) desde las raíces hasta las hojas y los demás órganos de la planta.'),
  ('8ff9e1c5-e6ce-478a-87e6-5c1d53227cd1', 'en',
   'Phloem, another plant conducting tissue, is responsible for transporting:',
   array['Elaborated sap, rich in sugars produced in photosynthesis, to the various parts of the plant', 'Only pure water, with no dissolved nutrients', 'Only atmospheric oxygen', 'Pollen between different flowers'],
   'Phloem distributes the products of photosynthesis from the leaves to the other parts of the plant.'),
  ('8ff9e1c5-e6ce-478a-87e6-5c1d53227cd1', 'es',
   'El floema, otro tejido conductor vegetal, se encarga de transportar:',
   array['La savia elaborada, rica en azúcares producidos en la fotosíntesis, a las diversas partes de la planta', 'Exclusivamente agua pura, sin ningún nutriente disuelto', 'Solo oxígeno atmosférico', 'Polen entre flores diferentes'],
   'El floema distribuye los productos de la fotosíntesis desde las hojas a las demás partes de la planta.'),
  ('c211a560-b7bc-4e22-91f2-a4c965fc5263', 'en',
   'Pollination, an essential process in the reproduction of most flowering plants, is:',
   array['The transfer of pollen from the male parts to the female parts of the flower', 'The absorption of water by the roots', 'The production of chlorophyll in the leaves', 'The formation of new roots only'],
   'Pollination is essential for fertilization and the formation of seeds and fruits.'),
  ('c211a560-b7bc-4e22-91f2-a4c965fc5263', 'es',
   'La polinización, proceso esencial en la reproducción de la mayoría de las plantas con flores, corresponde a:',
   array['La transferencia del polen de las partes masculinas a las partes femeninas de la flor', 'La absorción de agua por las raíces', 'La producción de clorofila en las hojas', 'La formación exclusiva de raíces nuevas'],
   'La polinización es esencial para la fecundación y la formación de semillas y frutos.'),
  ('d1da1571-365f-4e66-b7f5-a96c4b8ece45', 'en',
   'Bryophytes, such as mosses, are considered relatively simple plants because they:',
   array['Lack well-developed vascular tissues (xylem and phloem)', 'Are the most complex and evolved plants today', 'Produce flowers and fruits, like angiosperms', 'Are exclusively aquatic, with no adaptation to land'],
   'Bryophytes are nonvascular plants that depend heavily on environmental moisture to survive.'),
  ('d1da1571-365f-4e66-b7f5-a96c4b8ece45', 'es',
   'Las briófitas, como los musgos, se consideran plantas relativamente simples por:',
   array['No tener tejidos vasculares (xilema y floema) bien desarrollados', 'Ser las plantas más complejas y evolucionadas actualmente', 'Producir flores y frutos, como las angiospermas', 'Ser exclusivamente acuáticas, sin ninguna adaptación terrestre'],
   'Las briófitas son plantas avasculares que dependen fuertemente de la humedad ambiental para sobrevivir.'),
  ('3c53927c-1253-439d-a26a-0b6860668285', 'en',
   'Angiosperms, the most diverse plant group today, are mainly characterized by:',
   array['Producing flowers and fruits, which enclose and protect their seeds', 'Not producing seeds at all', 'Being exclusively aquatic plants', 'Not carrying out photosynthesis'],
   'Flowers and fruits, which protect the seeds and help disperse them, characterize the angiosperms.'),
  ('3c53927c-1253-439d-a26a-0b6860668285', 'es',
   'Las angiospermas, el grupo vegetal más diverso en la actualidad, se caracterizan principalmente por:',
   array['Producir flores y frutos, que envuelven y protegen sus semillas', 'No producir semillas de ninguna forma', 'Ser exclusivamente plantas acuáticas', 'No realizar la fotosíntesis'],
   'La presencia de flores y frutos, que protegen las semillas y ayudan a dispersarlas, caracteriza a las angiospermas.'),
  ('09e384a5-b7f2-4681-a268-b0717be785e7', 'en',
   'The germination of a seed usually depends on suitable conditions of:',
   array['Water, temperature and oxygen', 'Only direct sunlight, exclusively', 'A complete absence of water', 'Extremely low temperatures, exclusively'],
   'Germination depends on favorable environmental factors, such as water, suitable temperature and oxygen.'),
  ('09e384a5-b7f2-4681-a268-b0717be785e7', 'es',
   'El proceso de germinación de una semilla depende generalmente de condiciones adecuadas de:',
   array['Agua, temperatura y oxígeno', 'Solo luz solar directa, exclusivamente', 'La ausencia total de agua', 'Temperaturas extremadamente bajas, exclusivamente'],
   'La germinación depende de factores ambientales favorables, como agua, temperatura adecuada y oxígeno.'),
  ('af8d6409-d6ee-4915-a596-67b5d9de7634', 'en',
   'The cell cycle is divided into two main phases:',
   array['Interphase and cell division (mitosis or meiosis)', 'Only mitosis and meiosis, with no other phase', 'Only DNA replication, with no cell division', 'A phase of absolute rest, with no activity at all'],
   'The cell cycle alternates between interphase (growth and DNA duplication) and the cell division phase.'),
  ('af8d6409-d6ee-4915-a596-67b5d9de7634', 'es',
   'El ciclo celular se divide en dos grandes fases principales:',
   array['Interfase y división celular (mitosis o meiosis)', 'Solo mitosis y meiosis, sin ninguna otra fase', 'Solo la replicación del ADN, sin división celular', 'Una fase de reposo absoluto, sin ninguna actividad'],
   'El ciclo celular alterna entre la interfase (crecimiento y duplicación del ADN) y la fase de división celular.'),
  ('58a33f90-3fc5-4691-b00a-cf562feed77d', 'en',
   'Mitosis is a type of cell division that results in:',
   array['Two daughter cells genetically identical to the parent cell', 'Four daughter cells with half the genetic material', 'A single cell, with no division at all', 'Daughter cells that are genetically different from each other'],
   'In mitosis, a cell divides into two daughter cells with the same genetic material as the original.'),
  ('58a33f90-3fc5-4691-b00a-cf562feed77d', 'es',
   'La mitosis es un tipo de división celular que da como resultado:',
   array['Dos células hijas genéticamente idénticas a la célula madre', 'Cuatro células hijas con la mitad del material genético', 'Una única célula, sin ninguna división', 'Células hijas genéticamente distintas entre sí'],
   'En la mitosis, una célula se divide en dos células hijas con el mismo material genético que la original.'),
  ('2b090954-72da-446f-985d-1fd193cd165f', 'en',
   'Unlike mitosis, meiosis results in the formation of:',
   array['Four daughter cells with half the number of chromosomes of the original cell', 'Two daughter cells identical to the parent cell', 'A single cell with twice the chromosomes', 'Cells with no genetic material at all'],
   'Meiosis halves the number of chromosomes and is essential for forming gametes.'),
  ('2b090954-72da-446f-985d-1fd193cd165f', 'es',
   'A diferencia de la mitosis, la meiosis da como resultado la formación de:',
   array['Cuatro células hijas con la mitad del número de cromosomas de la célula original', 'Dos células hijas idénticas a la célula madre', 'Una única célula con el doble de cromosomas', 'Células sin ningún material genético'],
   'La meiosis reduce a la mitad el número de cromosomas y es esencial para la formación de gametos.'),
  ('0d523a95-88a5-4558-8aad-d3ebb04624b2', 'en',
   'Mitosis is the type of cell division mainly responsible for:',
   array['The growth of the organism and the replacement of cells', 'Forming gametes exclusively', 'Reducing the number of chromosomes', 'Destroying damaged cells, exclusively'],
   'Mitosis allows multicellular organisms to grow and replace worn-out cells.'),
  ('0d523a95-88a5-4558-8aad-d3ebb04624b2', 'es',
   'La mitosis es el tipo de división celular responsable, principalmente, de:',
   array['El crecimiento del organismo y la reposición de células', 'La formación exclusiva de gametos', 'La reducción del número de cromosomas', 'La destrucción de células dañadas, exclusivamente'],
   'La mitosis permite el crecimiento de los organismos multicelulares y la sustitución de las células desgastadas.'),
  ('7b7b7c51-f08b-45b3-9793-6c2d9555cfde', 'en',
   'Meiosis is essential for sexual reproduction because:',
   array['It ensures that, when gametes join, they restore the species'' normal number of chromosomes', 'It produces genetically identical cells for reproduction', 'It prevents any genetic variability among offspring', 'It has nothing to do with gamete formation'],
   'Since it halves the number of chromosomes in the gametes, meiosis allows fertilization to restore the species'' chromosome number.'),
  ('7b7b7c51-f08b-45b3-9793-6c2d9555cfde', 'es',
   'La meiosis es esencial para la reproducción sexual porque:',
   array['Garantiza que, al unirse, los gametos restablezcan el número normal de cromosomas de la especie', 'Produce células genéticamente idénticas para la reproducción', 'Impide cualquier variabilidad genética entre los descendientes', 'No tiene ninguna relación con la formación de gametos'],
   'Como reduce a la mitad el número de cromosomas en los gametos, la meiosis permite que la fecundación restablezca el número cromosómico de la especie.'),
  ('5886faf6-9934-45cc-99a0-a2764e6c1dd6', 'en',
   'Simple diffusion is a type of transport across the cell membrane characterized by:',
   array['Movement of substances down the concentration gradient, with no energy expenditure', 'Movement of substances against the concentration gradient, with energy expenditure', 'A mandatory need for carrier proteins', 'The passage of water only across the membrane'],
   'In simple diffusion, small and/or lipid-soluble molecules cross the membrane spontaneously, with no energy consumption.'),
  ('5886faf6-9934-45cc-99a0-a2764e6c1dd6', 'es',
   'La difusión simple es un tipo de transporte a través de la membrana celular caracterizado por:',
   array['El movimiento de sustancias a favor del gradiente de concentración, sin gasto de energía', 'El movimiento de sustancias en contra del gradiente de concentración, con gasto de energía', 'La necesidad obligatoria de proteínas transportadoras', 'El paso exclusivo de agua a través de la membrana'],
   'En la difusión simple, moléculas pequeñas y/o liposolubles atraviesan la membrana espontáneamente, sin consumo de energía.'),
  ('b52aeb89-005e-4c37-9ad1-5713bae7ade3', 'en',
   'Oxygen and carbon dioxide cross the plasma membrane mainly by:',
   array['Simple diffusion, because of their small size and nonpolar nature', 'Active transport, using ATP', 'Endocytosis', 'Exocytosis'],
   'Gases such as O₂ and CO₂ are small and nonpolar and cross the lipid bilayer freely by simple diffusion.'),
  ('b52aeb89-005e-4c37-9ad1-5713bae7ade3', 'es',
   'El oxígeno y el dióxido de carbono atraviesan la membrana plasmática principalmente por:',
   array['Difusión simple, debido a su pequeño tamaño y a su carácter apolar', 'Transporte activo, con gasto de ATP', 'Endocitosis', 'Exocitosis'],
   'Los gases como el O₂ y el CO₂ son pequeños y apolares, y atraviesan libremente la bicapa lipídica por difusión simple.'),
  ('7470a912-157f-442f-ba24-86f151204661', 'en',
   'Facilitated diffusion differs from simple diffusion in that it:',
   array['Uses membrane proteins (channels or carriers) to help substances pass through', 'Occurs against the concentration gradient', 'Requires direct energy expenditure (ATP)', 'Is exclusive to macromolecules'],
   'In facilitated diffusion, membrane proteins help substances pass through, still down the gradient.'),
  ('7470a912-157f-442f-ba24-86f151204661', 'es',
   'La difusión facilitada se diferencia de la difusión simple porque:',
   array['Utiliza proteínas de membrana (canales o transportadoras) para ayudar al paso de las sustancias', 'Ocurre en contra del gradiente de concentración', 'Exige un gasto directo de energía (ATP)', 'Es exclusiva de las macromoléculas'],
   'En la difusión facilitada, las proteínas de membrana ayudan al paso de las sustancias, todavía a favor del gradiente.'),
  ('aec79482-6013-498c-aae7-b14601179f88', 'en',
   'The rate at which a substance diffuses across the membrane is influenced, among other factors, by:',
   array['The difference in concentration between the two sides of the membrane (the gradient)', 'Only the color of the substance', 'The complete absence of cellular energy', 'The size of the cell nucleus'],
   'The greater the concentration gradient, the faster diffusion tends to be, until equilibrium is reached.'),
  ('aec79482-6013-498c-aae7-b14601179f88', 'es',
   'La velocidad de difusión de una sustancia a través de la membrana depende, entre otros factores, de:',
   array['La diferencia de concentración entre los dos lados de la membrana (gradiente)', 'Exclusivamente el color de la sustancia', 'La ausencia total de energía celular', 'El tamaño del núcleo celular'],
   'Cuanto mayor es el gradiente de concentración, más rápida tiende a ser la difusión, hasta alcanzar el equilibrio.'),
  ('bb80561b-2f3d-4236-a922-e4e1f9c21523', 'en',
   'Glucose, despite being a relatively large, polar molecule, usually enters cells by:',
   array['Facilitated diffusion, with the help of specific transport proteins', 'Simple diffusion, with no help', 'Exclusively by phagocytosis', 'It cannot cross the cell membrane'],
   'Being polar and relatively large, glucose depends on specific transport proteins (such as GLUT).'),
  ('bb80561b-2f3d-4236-a922-e4e1f9c21523', 'es',
   'La glucosa, aunque es una molécula relativamente grande y polar, generalmente entra en las células por:',
   array['Difusión facilitada, con ayuda de proteínas transportadoras específicas', 'Difusión simple, sin ninguna ayuda', 'Exclusivamente por fagocitosis', 'No puede atravesar la membrana celular'],
   'Por ser polar y relativamente grande, la glucosa depende de proteínas transportadoras específicas (como las GLUT).'),
  ('b7a63066-bae5-4d60-9d59-2f90492dbccb', 'en',
   'Endocytosis is the process by which the cell:',
   array['Engulfs substances from the external environment, forming a vesicle from the plasma membrane', 'Expels substances into the external environment', 'Carries out cell division', 'Synthesizes new proteins'],
   'In endocytosis, the plasma membrane folds inward, forming a vesicle that is taken into the cell.'),
  ('b7a63066-bae5-4d60-9d59-2f90492dbccb', 'es',
   'La endocitosis es el proceso por el cual la célula:',
   array['Engloba sustancias del medio externo, formando una vesícula a partir de la membrana plasmática', 'Expulsa sustancias al medio externo', 'Realiza la división celular', 'Sintetiza nuevas proteínas'],
   'En la endocitosis, la membrana plasmática se invagina y forma una vesícula que la célula internaliza.'),
  ('e38321d1-2e76-4cb5-bce5-751726702578', 'en',
   'Phagocytosis, a type of endocytosis, is characterized by the capture of:',
   array['Relatively large solid particles, such as bacteria or cell debris', 'Only liquids and dissolved solutes', 'Only water molecules', 'No external material of any kind'],
   'In phagocytosis, the cell engulfs larger solid particles, as white blood cells do when fighting pathogens.'),
  ('e38321d1-2e76-4cb5-bce5-751726702578', 'es',
   'La fagocitosis, un tipo de endocitosis, se caracteriza por la captura de:',
   array['Partículas sólidas relativamente grandes, como bacterias o restos celulares', 'Solo líquidos y solutos disueltos', 'Solo moléculas de agua', 'Ningún tipo de material externo'],
   'En la fagocitosis, la célula engloba partículas sólidas más grandes, como hacen los leucocitos al combatir patógenos.'),
  ('258978bd-0861-4492-85f8-3b9b417a0ae7', 'en',
   'Pinocytosis, another type of endocytosis, is characterized by the capture of:',
   array['Liquids and substances dissolved in the extracellular environment', 'Only large solid particles', 'Exclusively bacteria', 'No substance of any kind'],
   'In pinocytosis, the cell "drinks" small amounts of extracellular fluid, enclosing it in vesicles.'),
  ('258978bd-0861-4492-85f8-3b9b417a0ae7', 'es',
   'La pinocitosis, otro tipo de endocitosis, se caracteriza por la captura de:',
   array['Líquidos y sustancias disueltas en el medio extracelular', 'Solo partículas sólidas grandes', 'Exclusivamente bacterias', 'Ningún tipo de sustancia'],
   'En la pinocitosis, la célula "bebe" pequeñas cantidades de líquido extracelular y lo envuelve en vesículas.'),
  ('a75ca55f-c300-4f66-940b-6793b9c8b8aa', 'en',
   'Leukocytes (white blood cells) use phagocytosis mainly to:',
   array['Fight invading microorganisms, such as bacteria', 'Produce hormones', 'Carry out photosynthesis', 'Store energy as fat'],
   'Phagocytosis is a fundamental defense mechanism in which leukocytes engulf and destroy pathogens.'),
  ('a75ca55f-c300-4f66-940b-6793b9c8b8aa', 'es',
   'Los leucocitos (glóbulos blancos) usan la fagocitosis principalmente para:',
   array['Combatir microorganismos invasores, como las bacterias', 'Producir hormonas', 'Realizar la fotosíntesis', 'Almacenar energía en forma de grasa'],
   'La fagocitosis es un mecanismo de defensa fundamental, en el que los leucocitos engloban y destruyen patógenos.'),
  ('1b109436-8f82-4045-8c5e-0a7403bf5c56', 'en',
   'Receptor-mediated endocytosis is characterized by:',
   array['Involving specific receptor proteins on the membrane that recognize certain molecules before internalization', 'Occurring completely at random, with no specificity', 'Not involving the formation of vesicles', 'Being identical to exocytosis'],
   'Specific receptors on the membrane bind to certain molecules, increasing the selectivity of internalization.'),
  ('1b109436-8f82-4045-8c5e-0a7403bf5c56', 'es',
   'La endocitosis mediada por receptor se caracteriza por:',
   array['Involucrar proteínas receptoras específicas de la membrana, que reconocen determinadas moléculas antes de internalizarlas', 'Ocurrir de forma completamente aleatoria, sin ninguna especificidad', 'No implicar la formación de vesículas', 'Ser idéntica a la exocitosis'],
   'Los receptores específicos de la membrana se unen a determinadas moléculas y aumentan la selectividad de la internalización.'),
  ('994be9b2-1304-4264-9c95-522f86632836', 'en',
   'Exocytosis is the process by which the cell:',
   array['Expels substances into the external environment through the fusion of vesicles with the plasma membrane', 'Engulfs substances from the external environment', 'Carries out cell division', 'Absorbs water by osmosis'],
   'In exocytosis, vesicles containing substances fuse with the plasma membrane, releasing their contents outside.'),
  ('994be9b2-1304-4264-9c95-522f86632836', 'es',
   'La exocitosis es el proceso por el cual la célula:',
   array['Expulsa sustancias al medio externo mediante la fusión de vesículas con la membrana plasmática', 'Engloba sustancias del medio externo', 'Realiza la división celular', 'Absorbe agua por ósmosis'],
   'En la exocitosis, las vesículas con sustancias se fusionan con la membrana plasmática y liberan su contenido al exterior.'),
  ('aa7be49d-d1ad-41dc-aa1a-b2946926c0f7', 'en',
   'Exocytosis is the mechanism responsible, for example, for the release of:',
   array['Neurotransmitters at nerve synapses', 'Oxygen directly from the cell nucleus', 'DNA out of the nucleus continuously', 'No substance relevant to the organism'],
   'At synapses, neurotransmitters stored in vesicles are released into the synaptic cleft by exocytosis.'),
  ('aa7be49d-d1ad-41dc-aa1a-b2946926c0f7', 'es',
   'La exocitosis es el mecanismo responsable, por ejemplo, de la liberación de:',
   array['Neurotransmisores en las sinapsis nerviosas', 'Oxígeno directamente desde el núcleo celular', 'ADN fuera del núcleo de forma continua', 'Ninguna sustancia relevante para el organismo'],
   'En las sinapsis, los neurotransmisores almacenados en vesículas se liberan en el espacio sináptico por exocitosis.'),
  ('f1b6b5ed-b039-49d9-897e-62a61dd31fa3', 'en',
   'Besides neurotransmitters, exocytosis is also responsible for the secretion of:',
   array['Hormones and digestive enzymes produced by various glands', 'Only toxic metabolic waste', 'Exclusively respiratory gases', 'No substance useful to the organism'],
   'Many glands use exocytosis to secrete hormones, enzymes and other important substances.'),
  ('f1b6b5ed-b039-49d9-897e-62a61dd31fa3', 'es',
   'Además de los neurotransmisores, la exocitosis también es responsable de la secreción de:',
   array['Hormonas y enzimas digestivas producidas por diversas glándulas', 'Solo residuos metabólicos tóxicos', 'Exclusivamente gases respiratorios', 'Ninguna sustancia útil para el organismo'],
   'Muchas glándulas usan la exocitosis para secretar hormonas, enzimas y otras sustancias importantes.'),
  ('dc1ab59d-78a2-46fb-805d-905aec7b980d', 'en',
   'Together, exocytosis and endocytosis contribute to:',
   array['The renewal and balance of the plasma membrane, as well as the transport of substances', 'The permanent destruction of the plasma membrane', 'The complete elimination of the cell''s cytoplasm', 'The complete halt of cell metabolism'],
   'By adding and removing portions of membrane, these processes help keep the plasma membrane in balance.'),
  ('dc1ab59d-78a2-46fb-805d-905aec7b980d', 'es',
   'En conjunto, la exocitosis y la endocitosis contribuyen a:',
   array['La renovación y el equilibrio de la membrana plasmática, además del transporte de sustancias', 'La destrucción definitiva de la membrana plasmática', 'La eliminación completa del citoplasma celular', 'La detención total del metabolismo celular'],
   'Al añadir y retirar porciones de membrana, estos procesos ayudan a mantener el equilibrio de la membrana plasmática.'),
  ('fe0fdaad-9210-45fd-8767-5f4f9e5ea146', 'en',
   'The Golgi apparatus is directly related to exocytosis because it:',
   array['Packages substances into vesicles that the cell will later secrete', 'Produces energy in the form of ATP', 'Duplicates the genetic material', 'Has nothing to do with cell secretion'],
   'The Golgi apparatus processes and packages molecules into vesicles bound for exocytosis.'),
  ('fe0fdaad-9210-45fd-8767-5f4f9e5ea146', 'es',
   'El aparato de Golgi está directamente relacionado con la exocitosis porque:',
   array['Empaqueta sustancias en vesículas que la célula secretará después', 'Produce energía en forma de ATP', 'Realiza la duplicación del material genético', 'No tiene ninguna relación con la secreción celular'],
   'El aparato de Golgi procesa y empaqueta moléculas en vesículas destinadas a la exocitosis.'),
  ('45faaf79-dcde-487e-89cf-4a748e0a3ffa', 'en',
   'Osmosis is defined as the passage of:',
   array['Water across a semipermeable membrane, from the less concentrated to the more concentrated side in solute', 'Solutes across a membrane, from the more concentrated to the less concentrated side', 'Ions through protein channels, with energy expenditure', 'Macromolecules by means of vesicles'],
   'In osmosis, water moves across the membrane in the direction that evens out the solute concentrations on both sides.'),
  ('45faaf79-dcde-487e-89cf-4a748e0a3ffa', 'es',
   'La ósmosis se define como el paso de:',
   array['Agua a través de una membrana semipermeable, del medio menos concentrado al más concentrado en soluto', 'Solutos a través de una membrana, del medio más concentrado al menos concentrado', 'Iones a través de canales proteicos, con gasto de energía', 'Macromoléculas por medio de vesículas'],
   'En la ósmosis, el agua se mueve a través de la membrana en el sentido que equilibra las concentraciones de soluto entre los dos medios.'),
  ('2a5d4c21-c919-4f9a-8fa7-d04bd2d7ee3c', 'en',
   'A cell placed in a hypertonic solution (more concentrated than its interior) tends to:',
   array['Lose water to the external environment and may shrink (crenation or plasmolysis)', 'Gain water from the external environment and may swell and burst', 'Undergo no change in volume', 'Gain solutes directly, with no movement of water'],
   'In a hypertonic environment, water leaves the cell by osmosis, which can dehydrate it.'),
  ('2a5d4c21-c919-4f9a-8fa7-d04bd2d7ee3c', 'es',
   'Una célula colocada en una solución hipertónica (más concentrada que su interior) tiende a:',
   array['Perder agua hacia el medio externo y puede arrugarse (crenación o plasmólisis)', 'Ganar agua del medio externo y puede hincharse y estallar', 'No sufrir ningún cambio de volumen', 'Ganar solutos directamente, sin ningún movimiento de agua'],
   'En un medio hipertónico, el agua sale de la célula por ósmosis, lo que puede deshidratarla.'),
  ('5e6f98cb-556e-414f-87c7-83dd2f2eb674', 'en',
   'A red blood cell placed in pure water (a hypotonic environment) tends to:',
   array['Gain water and undergo hemolysis (rupture of the membrane)', 'Lose water and shrink', 'Remain completely unchanged', 'Lose solutes immediately'],
   'In a hypotonic environment, water enters the cell by osmosis, which can cause hemolysis, since the red blood cell has no cell wall.'),
  ('5e6f98cb-556e-414f-87c7-83dd2f2eb674', 'es',
   'Un glóbulo rojo colocado en agua pura (medio hipotónico) tiende a:',
   array['Ganar agua y sufrir hemólisis (ruptura de la membrana)', 'Perder agua y arrugarse', 'Permanecer completamente igual', 'Perder solutos de inmediato'],
   'En un medio hipotónico, el agua entra en la célula por ósmosis, lo que puede causar hemólisis, ya que el glóbulo rojo no tiene pared celular.'),
  ('c43e5580-dde3-4515-8073-3c30afbab9c3', 'en',
   'In plant cells, the presence of the cell wall prevents the cell from:',
   array['Bursting when it absorbs too much water, producing only turgor pressure', 'Losing water by osmosis in any situation', 'Carrying out photosynthesis normally', 'Undergoing any kind of osmosis'],
   'The rigid cell wall resists the pressure created by incoming water, producing turgidity without rupturing the cell.'),
  ('c43e5580-dde3-4515-8073-3c30afbab9c3', 'es',
   'En las células vegetales, la presencia de la pared celular impide que la célula:',
   array['Estalle al absorber agua en exceso, generando solo la presión de turgencia', 'Pierda agua por ósmosis en cualquier situación', 'Realice la fotosíntesis con normalidad', 'Sufra cualquier tipo de ósmosis'],
   'La pared celular rígida resiste la presión generada por la entrada de agua y produce turgencia sin romper la célula.'),
  ('902819ee-446c-4e2e-83fb-6ad16d3d1d5c', 'en',
   'The process of osmosis is fundamental to explaining, for example, why:',
   array['Fruits and vegetables wilt when exposed to very concentrated salt or sugar solutions', 'Plants never lose water to the environment', 'Water never moves across cell membranes', 'Osmosis has nothing to do with solute concentration'],
   'When exposed to hypertonic environments, cells lose water by osmosis, causing wilting.'),
  ('902819ee-446c-4e2e-83fb-6ad16d3d1d5c', 'es',
   'El proceso de ósmosis es fundamental para explicar, por ejemplo, por qué:',
   array['Las frutas y verduras se marchitan cuando se exponen a soluciones muy concentradas de sal o azúcar', 'Las plantas nunca pierden agua hacia el ambiente', 'El agua nunca se mueve a través de las membranas celulares', 'La ósmosis no tiene relación con la concentración de solutos'],
   'Al exponerse a medios hipertónicos, las células pierden agua por ósmosis, lo que causa el marchitamiento.'),
  ('cf11e436-3729-4ebf-9c60-92363f380de7', 'en',
   'Active transport is characterized by:',
   array['Moving substances against the concentration gradient, with energy expenditure (ATP)', 'Moving substances down the concentration gradient, with no energy expenditure', 'Occurring exclusively with water molecules', 'Not involving membrane proteins'],
   'Unlike diffusion, active transport moves substances against the gradient and requires ATP.'),
  ('cf11e436-3729-4ebf-9c60-92363f380de7', 'es',
   'El transporte activo se caracteriza por:',
   array['Mover sustancias en contra del gradiente de concentración, con gasto de energía (ATP)', 'Mover sustancias a favor del gradiente de concentración, sin gasto de energía', 'Ocurrir exclusivamente con moléculas de agua', 'No involucrar proteínas de membrana'],
   'A diferencia de la difusión, el transporte activo mueve sustancias en contra del gradiente y exige ATP.'),
  ('d5e6f1f3-ff41-461b-93c9-6d2d7efc3f2e', 'en',
   'The sodium-potassium pump (Na⁺/K⁺-ATPase) is a classic example of:',
   array['Active transport, which maintains the cells'' ion gradient', 'Simple diffusion', 'Osmosis', 'Phagocytosis'],
   'This pump uses ATP to move sodium out of the cell and potassium in, against their gradients.'),
  ('d5e6f1f3-ff41-461b-93c9-6d2d7efc3f2e', 'es',
   'La bomba de sodio y potasio (Na⁺/K⁺-ATPasa) es un ejemplo clásico de:',
   array['Transporte activo, que mantiene el gradiente iónico de las células', 'Difusión simple', 'Ósmosis', 'Fagocitosis'],
   'Esta bomba usa ATP para transportar sodio hacia fuera y potasio hacia dentro de la célula, en contra de sus gradientes.'),
  ('69d4126d-baa4-4a27-beb6-cda3e1a0759b', 'en',
   'In each cycle, the sodium-potassium pump typically transports:',
   array['3 sodium ions out of the cell and 2 potassium ions in', '2 sodium ions out and 3 potassium ions in', 'Only water, with no ions', 'Glucose exclusively'],
   'The classic ratio is 3 Na⁺ out and 2 K⁺ in for each ATP molecule consumed.'),
  ('69d4126d-baa4-4a27-beb6-cda3e1a0759b', 'es',
   'En cada ciclo, la bomba de sodio y potasio transporta típicamente:',
   array['3 iones de sodio hacia fuera y 2 iones de potasio hacia dentro de la célula', '2 iones de sodio hacia fuera y 3 iones de potasio hacia dentro', 'Solo agua, sin ningún ion', 'Glucosa exclusivamente'],
   'La proporción clásica es de 3 Na⁺ hacia fuera y 2 K⁺ hacia dentro por cada molécula de ATP consumida.'),
  ('3837d992-75b7-4076-b42a-8451736c1d3a', 'en',
   'Active transport is essential for cell functions such as:',
   array['Maintaining the membrane potential in nerve and muscle cells', 'Completely eliminating the need for cellular energy', 'Preventing any exchange with the external environment', 'Directly producing proteins'],
   'The ion gradient maintained by active transport is essential for nerve impulses and muscle contractions.'),
  ('3837d992-75b7-4076-b42a-8451736c1d3a', 'es',
   'El transporte activo es esencial para funciones celulares como:',
   array['El mantenimiento del potencial de membrana en las células nerviosas y musculares', 'La eliminación total de la necesidad de energía celular', 'El impedimento de cualquier intercambio con el medio externo', 'La producción directa de proteínas'],
   'El gradiente iónico que mantiene el transporte activo es esencial para los impulsos nerviosos y las contracciones musculares.'),
  ('f551e16c-528d-43a2-9d0b-d28e6f92d7ba', 'en',
   'Without a continuous supply of energy (ATP), active transport in a cell would:',
   array['Stop, compromising the cell''s ion balance', 'Continue normally, with no harm', 'Become even more efficient', 'Have nothing to do with ATP'],
   'Since it depends directly on energy, a lack of ATP brings active transport to a halt.'),
  ('f551e16c-528d-43a2-9d0b-d28e6f92d7ba', 'es',
   'Sin un suministro continuo de energía (ATP), el transporte activo de una célula:',
   array['Se interrumpiría y comprometería el equilibrio iónico celular', 'Continuaría con normalidad, sin ningún perjuicio', 'Se volvería aún más eficiente', 'No tiene ninguna relación con el ATP'],
   'Como depende directamente de la energía, la falta de ATP paraliza el transporte activo.'),
  ('64bddf0c-3c75-424a-b637-68c94b1ee732', 'en',
   'Centrioles are cell structures directly related to:',
   array['Organizing the mitotic spindle during cell division', 'Producing cellular energy', 'Synthesizing proteins', 'Intracellular digestion'],
   'During cell division, centrioles help organize the microtubules of the mitotic spindle.'),
  ('64bddf0c-3c75-424a-b637-68c94b1ee732', 'es',
   'Los centriolos son estructuras celulares directamente relacionadas con:',
   array['La organización del huso mitótico durante la división celular', 'La producción de energía celular', 'La síntesis de proteínas', 'La digestión intracelular'],
   'Durante la división celular, los centriolos ayudan a organizar los microtúbulos del huso mitótico.'),
  ('8b7a9fc5-5a6a-41a5-b7bb-42619a75e522', 'en',
   'Structurally, centrioles are made of:',
   array['Microtubules arranged in a cylindrical structure', 'A double membrane, like mitochondria', 'Their own genetic material, similar to nuclear DNA', 'Concentrated digestive enzymes'],
   'Each centriole is made of nine sets of microtubules arranged in the shape of a cylinder.'),
  ('8b7a9fc5-5a6a-41a5-b7bb-42619a75e522', 'es',
   'Estructuralmente, los centriolos están formados por:',
   array['Microtúbulos organizados en una estructura cilíndrica', 'Una doble membrana, como las mitocondrias', 'Material genético propio, semejante al ADN nuclear', 'Enzimas digestivas concentradas'],
   'Cada centriolo está compuesto por nueve conjuntos de microtúbulos organizados en forma de cilindro.'),
  ('7cdfcb00-2dae-4a66-b6f4-3da121d4e049', 'en',
   'Besides their role in cell division, centrioles are also involved in forming:',
   array['Cilia and flagella in certain cells', 'New mitochondria', 'New genetic material', 'Digestive enzymes'],
   'Centrioles act as basal bodies in forming cilia and flagella, structures used for cell movement.'),
  ('7cdfcb00-2dae-4a66-b6f4-3da121d4e049', 'es',
   'Además de su función en la división celular, los centriolos también están relacionados con la formación de:',
   array['Cilios y flagelos en determinadas células', 'Nuevas mitocondrias', 'Nuevo material genético', 'Enzimas digestivas'],
   'Los centriolos actúan como cuerpos basales en la formación de cilios y flagelos, estructuras de movimiento celular.'),
  ('540ec43f-99b2-4eec-8027-af76c5ad34b9', 'en',
   'Unlike animal cells, many plant cells are characterized by:',
   array['Not having centrioles, even though they divide normally', 'Having centrioles identical to those of animal cells', 'Never dividing', 'Having twice as many centrioles as animal cells'],
   'Most plant cells divide without centrioles, organizing the mitotic spindle by other mechanisms.'),
  ('540ec43f-99b2-4eec-8027-af76c5ad34b9', 'es',
   'A diferencia de las células animales, muchas células vegetales se caracterizan por:',
   array['No tener centriolos, aunque se dividen con normalidad', 'Tener centriolos idénticos a los de las células animales', 'No dividirse nunca', 'Tener el doble de centriolos que las células animales'],
   'La mayoría de las células vegetales se divide sin centriolos y organiza el huso mitótico mediante otros mecanismos.'),
  ('c3c6accf-0a59-46f0-8e10-ca5fbab13b03', 'en',
   'A pair of centrioles, usually arranged perpendicular to each other, forms a structure called the:',
   array['Centrosome', 'Nucleolus', 'Peroxisome', 'Vacuole'],
   'The centrosome, formed by a pair of centrioles, is the main microtubule-organizing center of the animal cell.'),
  ('c3c6accf-0a59-46f0-8e10-ca5fbab13b03', 'es',
   'Un par de centriolos, generalmente dispuestos de forma perpendicular entre sí, forma una estructura llamada:',
   array['Centrosoma', 'Nucléolo', 'Peroxisoma', 'Vacuola'],
   'El centrosoma, formado por un par de centriolos, es el principal centro organizador de microtúbulos de la célula animal.'),
  ('d68765a6-71bb-4d69-831a-59494c36af5c', 'en',
   'The main function of chloroplasts, found in plant cells and some algae, is:',
   array['To carry out photosynthesis, converting sunlight into chemical energy', 'To produce energy exclusively through cellular respiration', 'To digest intracellular macromolecules', 'To store the cell''s main genetic material'],
   'Chloroplasts capture light energy and convert it into chemical energy (glucose) during photosynthesis.'),
  ('d68765a6-71bb-4d69-831a-59494c36af5c', 'es',
   'La principal función de los cloroplastos, presentes en las células vegetales y en algunas algas, es:',
   array['Realizar la fotosíntesis, convirtiendo la luz solar en energía química', 'Producir energía exclusivamente por respiración celular', 'Digerir macromoléculas intracelulares', 'Almacenar el material genético principal de la célula'],
   'Los cloroplastos captan la energía luminosa y la convierten en energía química (glucosa) durante la fotosíntesis.'),
  ('e137a050-36cd-4706-8a5d-4ef9a8f221d6', 'en',
   'The characteristic green color of chloroplasts is due mainly to the presence of the pigment:',
   array['Chlorophyll', 'Hemoglobin', 'Melanin', 'Carotene, exclusively'],
   'Chlorophyll, a fundamental pigment in photosynthesis, gives chloroplasts their characteristic green color.'),
  ('e137a050-36cd-4706-8a5d-4ef9a8f221d6', 'es',
   'El color verde característico de los cloroplastos se debe principalmente a la presencia del pigmento:',
   array['Clorofila', 'Hemoglobina', 'Melanina', 'Caroteno, exclusivamente'],
   'La clorofila, pigmento fundamental en la fotosíntesis, da a los cloroplastos su característico color verde.'),
  ('416efd60-7950-42ce-990e-931fd55846c5', 'en',
   'Like mitochondria, chloroplasts have:',
   array['Their own DNA and ribosomes, which also supports the endosymbiotic theory', 'No genetic material of their own', 'Only a single simple membrane', 'A structure identical to lysosomes'],
   'Chloroplasts have their own circular DNA and ribosomes, reinforcing their endosymbiotic origin.'),
  ('416efd60-7950-42ce-990e-931fd55846c5', 'es',
   'Al igual que las mitocondrias, los cloroplastos tienen:',
   array['ADN y ribosomas propios, lo que también sostiene la teoría endosimbiótica', 'Ningún material genético propio', 'Solo una única membrana simple', 'Una estructura idéntica a la de los lisosomas'],
   'Los cloroplastos tienen ADN circular y ribosomas propios, lo que refuerza su origen endosimbiótico.'),
  ('902f0eb1-8288-4734-9673-2dcf16afbe85', 'en',
   'Internally, chloroplasts are structurally organized into stacks of membranes called:',
   array['Grana (made of thylakoids)', 'Cristae', 'Golgi cisternae', 'Ribosomes'],
   'Inside chloroplasts, the thylakoids are organized into stacks called grana, where the light reactions take place.'),
  ('902f0eb1-8288-4734-9673-2dcf16afbe85', 'es',
   'En su interior, los cloroplastos están organizados estructuralmente en pilas de membranas llamadas:',
   array['Grana (formadas por tilacoides)', 'Crestas', 'Cisternas del Golgi', 'Ribosomas'],
   'En el interior de los cloroplastos, los tilacoides se organizan en pilas llamadas grana, donde ocurren las reacciones fotoquímicas.'),
  ('2f00d69f-8adc-4654-a6e6-6649ac3c19e5', 'en',
   'Unlike plant cells, animal cells:',
   array['Have no chloroplasts and obtain energy mainly through feeding', 'Have chloroplasts identical to those of plants', 'Carry out photosynthesis normally', 'Do not carry out cellular respiration'],
   'Since they have no chloroplasts, animal cells depend on feeding (heterotrophy) to obtain energy.'),
  ('2f00d69f-8adc-4654-a6e6-6649ac3c19e5', 'es',
   'A diferencia de las células vegetales, las células animales:',
   array['No tienen cloroplastos y obtienen energía principalmente a través de la alimentación', 'Tienen cloroplastos idénticos a los vegetales', 'Realizan la fotosíntesis con normalidad', 'No realizan la respiración celular'],
   'Al no tener cloroplastos, las células animales dependen de la alimentación (heterotrofia) para obtener energía.'),
  ('5c3893af-3b7e-41fb-95c1-01878faa22e2', 'en',
   'The main function of the Golgi complex (or Golgi apparatus) is:',
   array['To modify, package and distribute proteins and other macromolecules produced in the cell', 'To produce energy in the form of ATP', 'To store the genetic material directly', 'To carry out photosynthesis'],
   'The Golgi complex processes molecules received from the endoplasmic reticulum, packaging them into vesicles.'),
  ('5c3893af-3b7e-41fb-95c1-01878faa22e2', 'es',
   'La principal función del complejo de Golgi (o aparato de Golgi) es:',
   array['Modificar, empaquetar y distribuir proteínas y otras macromoléculas producidas en la célula', 'Producir energía en forma de ATP', 'Almacenar directamente el material genético', 'Realizar la fotosíntesis'],
   'El complejo de Golgi procesa moléculas recibidas del retículo endoplasmático y las empaqueta en vesículas.'),
  ('8d9d4f86-5084-41ae-a7ce-f6f20ce490f9', 'en',
   'Structurally, the Golgi complex is made of:',
   array['A series of flattened, stacked membranous sacs (cisternae)', 'A single large spherical vesicle', 'Protein filaments with no membrane at all', 'A structure identical to the cell nucleus'],
   'The Golgi complex consists of stacked membranous cisternae, with receiving and shipping faces.'),
  ('8d9d4f86-5084-41ae-a7ce-f6f20ce490f9', 'es',
   'Estructuralmente, el complejo de Golgi está formado por:',
   array['Una serie de sacos membranosos aplanados y apilados (cisternas)', 'Una única vesícula esférica grande', 'Filamentos proteicos sin ninguna membrana', 'Una estructura idéntica al núcleo celular'],
   'El complejo de Golgi está compuesto por cisternas membranosas apiladas, con caras de recepción y de salida.'),
  ('d11fa6c7-ef5d-4c6a-9655-841d8c343587', 'en',
   'The Golgi complex receives substances produced mainly:',
   array['In the endoplasmic reticulum', 'Directly in the cell nucleus', 'In the mitochondria', 'Outside the cell, in the extracellular environment'],
   'Proteins synthesized in the rough endoplasmic reticulum are transported to the Golgi complex.'),
  ('d11fa6c7-ef5d-4c6a-9655-841d8c343587', 'es',
   'El complejo de Golgi recibe sustancias producidas principalmente:',
   array['En el retículo endoplasmático', 'Directamente en el núcleo celular', 'En las mitocondrias', 'Fuera de la célula, en el medio extracelular'],
   'Las proteínas sintetizadas en el retículo endoplasmático rugoso se transportan hasta el complejo de Golgi.'),
  ('15a8d534-93ba-4605-89e8-3d74b2d1384f', 'en',
   'Among the substances processed and released by the Golgi complex are:',
   array['Digestive enzymes that will form lysosomes', 'Only DNA molecules', 'Exclusively water molecules', 'No substance relevant to the cell'],
   'One of the main products of the Golgi complex is digestive enzymes, packaged into lysosomes.'),
  ('15a8d534-93ba-4605-89e8-3d74b2d1384f', 'es',
   'Entre las sustancias procesadas y liberadas por el complejo de Golgi se incluyen:',
   array['Enzimas digestivas que formarán los lisosomas', 'Solo moléculas de ADN', 'Exclusivamente moléculas de agua', 'Ninguna sustancia relevante para la célula'],
   'Uno de los principales productos del complejo de Golgi son las enzimas digestivas, empaquetadas en los lisosomas.'),
  ('232a1d6e-2005-4b69-a5c3-95e9f0c6753b', 'en',
   'In secretory cells, such as gland cells, the Golgi complex is usually:',
   array['Especially well developed, because of the intense processing and secretion activity', 'Practically absent', 'Identical to the one found in cells that do not secrete substances', 'Completely replaced by lysosomes'],
   'Cells with high secretory activity have a well-developed Golgi complex.'),
  ('232a1d6e-2005-4b69-a5c3-95e9f0c6753b', 'es',
   'En las células secretoras, como las glandulares, el complejo de Golgi suele estar:',
   array['Especialmente desarrollado, debido a la intensa actividad de procesamiento y secreción', 'Prácticamente ausente', 'Igual que en las células que no secretan sustancias', 'Sustituido por completo por los lisosomas'],
   'Las células con alta actividad secretora tienen un complejo de Golgi bien desarrollado.'),
  ('6fa5a13e-8c7d-4199-a1e9-ca704c281974', 'en',
   'Lysosomes are organelles mainly responsible for:',
   array['Intracellular digestion of macromolecules and cell structures', 'Producing energy in the form of ATP', 'Synthesizing proteins', 'Storing the genetic material'],
   'Lysosomes contain digestive enzymes capable of breaking down proteins, lipids, carbohydrates and nucleic acids.'),
  ('6fa5a13e-8c7d-4199-a1e9-ca704c281974', 'es',
   'Los lisosomas son orgánulos responsables principalmente de:',
   array['Realizar la digestión intracelular de macromoléculas y estructuras celulares', 'Producir energía en forma de ATP', 'Sintetizar proteínas', 'Almacenar el material genético'],
   'Los lisosomas contienen enzimas digestivas capaces de degradar proteínas, lípidos, carbohidratos y ácidos nucleicos.'),
  ('96d98dc3-d48d-43b4-8e7b-7e589dc06c89', 'en',
   'Lysosomes are formed from vesicles that originate mainly from:',
   array['The Golgi complex', 'The cell nucleus', 'The mitochondria', 'The plasma membrane, exclusively'],
   'The Golgi complex processes and packages the digestive enzymes, forming lysosomes.'),
  ('96d98dc3-d48d-43b4-8e7b-7e589dc06c89', 'es',
   'Los lisosomas se forman a partir de vesículas originadas principalmente en:',
   array['El complejo de Golgi', 'El núcleo celular', 'Las mitocondrias', 'La membrana plasmática, exclusivamente'],
   'El complejo de Golgi procesa y empaqueta las enzimas digestivas y forma los lisosomas.'),
  ('466218ed-b047-421e-a9ab-c11ef65336b0', 'en',
   'During phagocytosis, lysosomes act by:',
   array['Digesting the material engulfed by the cell, contained in phagosomes', 'Preventing any digestion of the captured material', 'Producing extra energy for the cell', 'Carrying out cell division'],
   'After the phagosome forms, lysosomes fuse with it, releasing enzymes that digest its contents.'),
  ('466218ed-b047-421e-a9ab-c11ef65336b0', 'es',
   'Durante la fagocitosis, los lisosomas actúan:',
   array['Digiriendo el material englobado por la célula, presente en los fagosomas', 'Impidiendo cualquier digestión del material capturado', 'Produciendo energía adicional para la célula', 'Realizando la división celular'],
   'Tras formarse el fagosoma, los lisosomas se fusionan con él y liberan enzimas que digieren su contenido.'),
  ('ae89f3fc-f687-415d-b9f3-efc43744c25a', 'en',
   '"Autophagy", the process in which the cell itself breaks down damaged organelles or components, directly involves the action of:',
   array['Lysosomes', 'Ribosomes', 'Chloroplasts', 'Centrioles'],
   'In autophagy, lysosomes digest worn-out cell components, contributing to cell renewal.'),
  ('ae89f3fc-f687-415d-b9f3-efc43744c25a', 'es',
   'La "autofagia", proceso en el que la propia célula degrada orgánulos o componentes dañados, implica directamente la acción de:',
   array['Los lisosomas', 'Los ribosomas', 'Los cloroplastos', 'Los centriolos'],
   'En la autofagia, los lisosomas digieren componentes celulares desgastados y contribuyen a la renovación celular.'),
  ('014685b1-5740-4f4d-98f3-2aeda54559cc', 'en',
   'Improper functioning of lysosomes, with a deficiency in their digestive enzymes, may be associated with:',
   array['Lysosomal storage diseases, caused by the buildup of undigested substances', 'An immediate increase in cellular energy production', 'No relevant consequence for the cell', 'Greater resistance of the cell to infections'],
   'A deficiency of specific lysosomal enzymes can cause serious genetic storage diseases.'),
  ('014685b1-5740-4f4d-98f3-2aeda54559cc', 'es',
   'Un funcionamiento inadecuado de los lisosomas, con deficiencia de sus enzimas digestivas, puede estar asociado a:',
   array['Enfermedades de depósito lisosómico, causadas por la acumulación de sustancias no digeridas', 'Un aumento inmediato de la producción de energía celular', 'Ninguna consecuencia relevante para la célula', 'Una mayor resistencia de la célula a las infecciones'],
   'La deficiencia de enzimas lisosómicas específicas puede causar enfermedades genéticas graves de depósito.'),
  ('40547d9d-7b7c-4fe6-bec0-f5b936c76be7', 'en',
   'The main function of mitochondria is:',
   array['To produce energy (ATP) through cellular respiration', 'To store the cell''s main genetic material', 'To carry out photosynthesis', 'To digest intracellular macromolecules'],
   'Mitochondria are responsible for aerobic cellular respiration, producing much of the cell''s ATP.'),
  ('40547d9d-7b7c-4fe6-bec0-f5b936c76be7', 'es',
   'La principal función de las mitocondrias es:',
   array['Producir energía (ATP) mediante la respiración celular', 'Almacenar el material genético principal de la célula', 'Realizar la fotosíntesis', 'Digerir macromoléculas intracelulares'],
   'Las mitocondrias son responsables de la respiración celular aeróbica y producen gran parte del ATP celular.'),
  ('ded4b53c-2d3e-406e-9e7e-29fbd5a1a5da', 'en',
   'Mitochondria are structures characterized by having:',
   array['A double membrane, with the inner one folded into cristae', 'Only a single simple membrane', 'No membrane, being completely open structures', 'A membrane made exclusively of proteins'],
   'The inner membrane, folded into cristae, increases the surface area for the reactions of cellular respiration.'),
  ('ded4b53c-2d3e-406e-9e7e-29fbd5a1a5da', 'es',
   'Las mitocondrias son estructuras caracterizadas por tener:',
   array['Una doble membrana, con la interna plegada en crestas', 'Solo una única membrana simple', 'Ninguna membrana, por ser estructuras completamente abiertas', 'Una membrana compuesta exclusivamente por proteínas'],
   'La membrana interna, plegada en crestas, aumenta la superficie para las reacciones de la respiración celular.'),
  ('3d09d858-2d36-468f-bf12-70c5d8675a6a', 'en',
   'According to the endosymbiotic theory, mitochondria would have originated from:',
   array['Ancestral bacteria engulfed by larger cells billions of years ago', 'Fragments of the cell nucleus', 'Viruses that infected eukaryotic cells', 'Remnants of plasma membrane'],
   'The endosymbiotic theory suggests that mitochondria descend from bacteria engulfed by larger cells.'),
  ('3d09d858-2d36-468f-bf12-70c5d8675a6a', 'es',
   'Según la teoría endosimbiótica, las mitocondrias se habrían originado a partir de:',
   array['Bacterias ancestrales incorporadas por células más grandes hace miles de millones de años', 'Fragmentos del núcleo celular', 'Virus que infectaron células eucariotas', 'Restos de membrana plasmática'],
   'La teoría endosimbiótica sugiere que las mitocondrias descienden de bacterias incorporadas por células más grandes.'),
  ('53743f0b-9f8e-444f-be8b-e2e26e1895b7', 'en',
   'One piece of evidence supporting the endosymbiotic theory of mitochondria is the fact that they have:',
   array['Their own DNA and ribosomes, similar to those of bacteria', 'No genetic material of their own', 'Only a single simple membrane, like bacteria', 'No internal structure at all'],
   'Mitochondria have their own circular DNA and ribosomes, reinforcing the endosymbiotic theory.'),
  ('53743f0b-9f8e-444f-be8b-e2e26e1895b7', 'es',
   'Un indicio que sostiene la teoría endosimbiótica de las mitocondrias es que tienen:',
   array['ADN y ribosomas propios, semejantes a los de las bacterias', 'Ningún material genético propio', 'Solo una membrana simple, como las bacterias', 'Ninguna estructura interna'],
   'Las mitocondrias tienen ADN circular y ribosomas propios, lo que refuerza la teoría endosimbiótica.'),
  ('b39fb1b6-8cd1-4676-a61c-f134d2747f5c', 'en',
   'Cells with high energy demand, such as muscle cells, tend to have:',
   array['More mitochondria', 'No mitochondria at all', 'Fewer mitochondria than other cells', 'No relationship between mitochondria and energy demand'],
   'Cells that need more energy, such as muscle and heart cells, have large numbers of mitochondria.'),
  ('b39fb1b6-8cd1-4676-a61c-f134d2747f5c', 'es',
   'Las células con alta demanda energética, como las musculares, tienden a tener:',
   array['Mayor cantidad de mitocondrias', 'Ausencia total de mitocondrias', 'Menor cantidad de mitocondrias que otras células', 'Ninguna relación entre las mitocondrias y la demanda energética'],
   'Las células que necesitan más energía, como las musculares y las cardíacas, tienen gran cantidad de mitocondrias.'),
  ('88f4d234-5504-48a1-9979-16efae3daadc', 'en',
   'The main function of the cell nucleus, found in eukaryotic cells, is:',
   array['To store and protect the cell''s genetic material (DNA)', 'To produce energy in the form of ATP', 'To carry out intracellular digestion', 'To synthesize proteins directly, with no intermediary'],
   'The nucleus houses the DNA, controlling cell activities and the transmission of genetic information.'),
  ('88f4d234-5504-48a1-9979-16efae3daadc', 'es',
   'La principal función del núcleo celular, presente en las células eucariotas, es:',
   array['Almacenar y proteger el material genético (ADN) de la célula', 'Producir energía en forma de ATP', 'Realizar la digestión intracelular', 'Sintetizar directamente proteínas, sin ningún intermediario'],
   'El núcleo alberga el ADN y controla las actividades celulares y la transmisión de la información genética.'),
  ('912c95af-306a-4b81-878a-3b48f541d273', 'en',
   'The nuclear envelope, which separates the nucleus from the cytoplasm, is characterized by having:',
   array['Nuclear pores, which allow a controlled exchange of substances', 'A completely impermeable structure, with no openings', 'No membrane at all', 'A single lipid layer instead of two'],
   'Nuclear pores regulate the passage of molecules, such as RNA and proteins, between the nucleus and the cytoplasm.'),
  ('912c95af-306a-4b81-878a-3b48f541d273', 'es',
   'La envoltura nuclear, que separa el núcleo del citoplasma, se caracteriza por tener:',
   array['Poros nucleares, que permiten el intercambio controlado de sustancias', 'Una estructura totalmente impermeable, sin ninguna abertura', 'La ausencia total de membrana', 'Una única capa lipídica, en lugar de dos'],
   'Los poros nucleares regulan el paso de moléculas, como el ARN y las proteínas, entre el núcleo y el citoplasma.'),
  ('3e5388de-c976-4cb0-a27d-5fa73a7211bd', 'en',
   'The nucleolus, a structure inside the nucleus, is mainly responsible for:',
   array['Producing ribosomes', 'Producing cellular energy', 'Digesting macromolecules', 'Synthesizing membrane lipids'],
   'The nucleolus is where ribosomes are synthesized and assembled, which are essential for producing proteins.'),
  ('3e5388de-c976-4cb0-a27d-5fa73a7211bd', 'es',
   'El nucléolo, estructura presente dentro del núcleo, es responsable principalmente de:',
   array['La producción de ribosomas', 'La producción de energía celular', 'La digestión de macromoléculas', 'La síntesis de lípidos de membrana'],
   'El nucléolo es el lugar de síntesis y ensamblaje de los ribosomas, esenciales para la producción de proteínas.'),
  ('2fa1c375-3643-408a-bfa4-4ebdcfb18385', 'en',
   'Chromatin, found inside the nucleus, corresponds to:',
   array['DNA associated with proteins, in its uncondensed form (outside cell division)', 'A structure made exclusively of proteins, with no DNA', 'The nuclear envelope', 'A cytoplasmic organelle independent of the nucleus'],
   'Chromatin is genetic material associated with histone proteins, in uncondensed form.'),
  ('2fa1c375-3643-408a-bfa4-4ebdcfb18385', 'es',
   'La cromatina, presente en el interior del núcleo, corresponde a:',
   array['El ADN asociado a proteínas, en su forma descondensada (fuera de la división celular)', 'Una estructura formada exclusivamente por proteínas, sin ADN', 'La envoltura nuclear', 'Un orgánulo citoplasmático independiente del núcleo'],
   'La cromatina es el material genético asociado a proteínas histonas, en forma descondensada.'),
  ('5327484e-9f50-48ae-9af3-5783c3082f00', 'en',
   'During cell division, chromatin condenses, forming structures visible under the microscope called:',
   array['Chromosomes', 'Ribosomes', 'Mitochondria', 'Lysosomes'],
   'Before cell division, chromatin condenses into chromosomes, making it easier to distribute the genetic material.'),
  ('5327484e-9f50-48ae-9af3-5783c3082f00', 'es',
   'Durante la división celular, la cromatina se condensa y forma estructuras visibles al microscopio llamadas:',
   array['Cromosomas', 'Ribosomas', 'Mitocondrias', 'Lisosomas'],
   'Antes de la división celular, la cromatina se condensa en cromosomas, lo que facilita la distribución del material genético.'),
  ('abe556f1-0a37-4f4e-91e6-6ebb5a5892a4', 'en',
   'The rough endoplasmic reticulum differs from the smooth one mainly by:',
   array['Having ribosomes attached to its surface', 'Having no membrane at all', 'Being found only in plant cells', 'Directly producing cellular energy'],
   'The presence of ribosomes on its outer surface characterizes the rough reticulum, which is linked to protein synthesis.'),
  ('abe556f1-0a37-4f4e-91e6-6ebb5a5892a4', 'es',
   'El retículo endoplasmático rugoso se diferencia del liso principalmente por:',
   array['Tener ribosomas adheridos a su superficie', 'No tener ninguna membrana', 'Encontrarse solo en las células vegetales', 'Producir directamente energía celular'],
   'La presencia de ribosomas en su superficie externa caracteriza al retículo rugoso, vinculado a la síntesis de proteínas.'),
  ('3aa44f7e-5242-47ef-8c57-e609d3410533', 'en',
   'The rough endoplasmic reticulum is directly involved in:',
   array['Synthesizing proteins destined for secretion or for other organelles', 'Producing energy in the form of ATP', 'Digesting macromolecules', 'Duplicating the genetic material'],
   'Proteins synthesized by the ribosomes attached to the rough reticulum are processed before moving on to the Golgi.'),
  ('3aa44f7e-5242-47ef-8c57-e609d3410533', 'es',
   'El retículo endoplasmático rugoso participa directamente en:',
   array['La síntesis de proteínas destinadas a la secreción o a otros orgánulos', 'La producción de energía en forma de ATP', 'La digestión de macromoléculas', 'La duplicación del material genético'],
   'Las proteínas sintetizadas por los ribosomas adheridos al retículo rugoso se procesan antes de pasar al Golgi.'),
  ('5981f07c-e0d9-42be-ac34-9671981845a6', 'en',
   'The smooth endoplasmic reticulum, with no ribosomes on its surface, is mainly related to:',
   array['Lipid synthesis and cell detoxification', 'Direct protein synthesis', 'Digesting cell debris', 'Producing genetic material'],
   'The smooth reticulum takes part in lipid synthesis and detoxification processes, as in the liver.'),
  ('5981f07c-e0d9-42be-ac34-9671981845a6', 'es',
   'El retículo endoplasmático liso, sin ribosomas en su superficie, está relacionado principalmente con:',
   array['La síntesis de lípidos y la desintoxicación celular', 'La síntesis directa de proteínas', 'La digestión de restos celulares', 'La producción del material genético'],
   'El retículo liso participa en la síntesis de lípidos y en procesos de desintoxicación, como en el hígado.'),
  ('4c061911-d407-40f8-b09a-c4486cd7c8ab', 'en',
   'In muscle cells, a specialized variant of the smooth endoplasmic reticulum, called the sarcoplasmic reticulum, plays a key role in:',
   array['Storing and releasing calcium ions, essential for muscle contraction', 'Directly producing muscle energy', 'Forming new cell nuclei', 'Digesting muscle proteins'],
   'The sarcoplasmic reticulum regulates calcium levels in the cytoplasm of muscle cells, which is essential for contraction.'),
  ('4c061911-d407-40f8-b09a-c4486cd7c8ab', 'es',
   'En las células musculares, una variante especializada del retículo endoplasmático liso, llamada retículo sarcoplásmico, tiene un papel fundamental en:',
   array['El almacenamiento y la liberación de iones de calcio, esenciales para la contracción muscular', 'La producción directa de energía muscular', 'La formación de nuevos núcleos celulares', 'La digestión de proteínas musculares'],
   'El retículo sarcoplásmico regula los niveles de calcio en el citoplasma de las células musculares, algo esencial para la contracción.'),
  ('0b4ada86-67e4-4159-92da-766cd58a0f2f', 'en',
   'Structurally, the endoplasmic reticulum, both rough and smooth, is made of:',
   array['A network of interconnected membranes, forming channels and sacs', 'A single isolated spherical vesicle', 'Protein filaments with no membrane at all', 'Structures identical to mitochondria'],
   'The endoplasmic reticulum forms an extensive network of interconnected membranes within the cytoplasm.'),
  ('0b4ada86-67e4-4159-92da-766cd58a0f2f', 'es',
   'Estructuralmente, el retículo endoplasmático, tanto rugoso como liso, está formado por:',
   array['Una red de membranas interconectadas que forman canales y sacos', 'Una única vesícula esférica aislada', 'Filamentos proteicos sin ninguna membrana', 'Estructuras idénticas a las mitocondrias'],
   'El retículo endoplasmático forma una extensa red de membranas interconectadas dentro del citoplasma.'),
  ('dcb5b7f5-12ab-4cb8-aa2d-4b16353a018b', 'en',
   'The main function of ribosomes, found in all living cells, is:',
   array['To carry out protein synthesis', 'To produce energy in the form of ATP', 'To store the genetic material', 'To carry out intracellular digestion'],
   'Ribosomes translate messenger RNA into chains of amino acids, forming proteins.'),
  ('dcb5b7f5-12ab-4cb8-aa2d-4b16353a018b', 'es',
   'La principal función de los ribosomas, presentes en todas las células vivas, es:',
   array['Realizar la síntesis de proteínas', 'Producir energía en forma de ATP', 'Almacenar el material genético', 'Realizar la digestión intracelular'],
   'Los ribosomas traducen el ARN mensajero en cadenas de aminoácidos y forman proteínas.'),
  ('c00c5e51-9f69-44be-aeb4-28a03437fcd1', 'en',
   'Ribosomes can be found in the cell:',
   array['Free in the cytoplasm or attached to the rough endoplasmic reticulum', 'Only inside the cell nucleus', 'Exclusively inside mitochondria', 'Only outside the cell'],
   'Free ribosomes synthesize proteins for the cytoplasm; those attached to the rough reticulum produce proteins for secretion or specific organelles.'),
  ('c00c5e51-9f69-44be-aeb4-28a03437fcd1', 'es',
   'Los ribosomas pueden encontrarse en la célula:',
   array['Libres en el citoplasma o adheridos al retículo endoplasmático rugoso', 'Solo dentro del núcleo celular', 'Exclusivamente dentro de las mitocondrias', 'Solo fuera de la célula'],
   'Los ribosomas libres sintetizan proteínas para el citoplasma; los adheridos al retículo rugoso producen proteínas para secreción o para orgánulos específicos.'),
  ('785d4120-06ba-445a-b7cb-910331f20165', 'en',
   'Unlike other organelles, ribosomes are characterized by:',
   array['Having no membrane around their structure', 'Having a double membrane', 'Being exclusive to plant cells', 'Being visible to the naked eye'],
   'Ribosomes are non-membranous structures made of ribosomal RNA and proteins.'),
  ('785d4120-06ba-445a-b7cb-910331f20165', 'es',
   'A diferencia de otros orgánulos, los ribosomas se caracterizan por:',
   array['No tener membrana que envuelva su estructura', 'Tener una doble membrana', 'Ser exclusivos de las células vegetales', 'Ser visibles a simple vista'],
   'Los ribosomas son estructuras no membranosas, formadas por ARN ribosómico y proteínas.'),
  ('b81824e4-e13e-416f-803a-14ebf57b524a', 'en',
   'Ribosomes are present in both prokaryotic and eukaryotic cells, which shows:',
   array['The universal importance of protein synthesis for all living beings', 'That only eukaryotic cells produce proteins', 'That ribosomes are not essential for cell life', 'That only bacteria have ribosomes'],
   'The presence of ribosomes in every cell type reflects the universal need for protein synthesis.'),
  ('b81824e4-e13e-416f-803a-14ebf57b524a', 'es',
   'Los ribosomas están presentes tanto en células procariotas como eucariotas, lo que evidencia:',
   array['La importancia universal de la síntesis de proteínas para todos los seres vivos', 'Que solo las células eucariotas producen proteínas', 'Que los ribosomas no son esenciales para la vida celular', 'Que solo las bacterias tienen ribosomas'],
   'La presencia de ribosomas en todos los tipos celulares refleja la necesidad universal de síntesis proteica.'),
  ('affc223d-13bd-45c7-81f9-d62e0ea2d37b', 'en',
   'The process by which ribosomes "read" messenger RNA to produce a protein is called:',
   array['Translation', 'Transcription', 'Replication', 'Fermentation'],
   'Translation is the step in which ribosomes decode the sequence of messenger RNA, forming the protein.'),
  ('affc223d-13bd-45c7-81f9-d62e0ea2d37b', 'es',
   'El proceso por el cual los ribosomas "leen" el ARN mensajero para producir una proteína se llama:',
   array['Traducción', 'Transcripción', 'Replicación', 'Fermentación'],
   'La traducción es la etapa en la que los ribosomas decodifican la secuencia del ARN mensajero y forman la proteína.'),
  ('816b3280-61e9-4935-a84e-7d35522d3153', 'en',
   'Arteries are blood vessels responsible for:',
   array['Carrying blood from the heart to the other organs and tissues of the body', 'Carrying blood from the tissues back to the heart', 'Exchanging gases directly with the external environment', 'Producing new blood cells'],
   'Arteries carry the blood leaving the heart toward the body''s tissues.'),
  ('816b3280-61e9-4935-a84e-7d35522d3153', 'es',
   'Las arterias son vasos sanguíneos responsables de:',
   array['Conducir la sangre desde el corazón hacia los demás órganos y tejidos del cuerpo', 'Conducir la sangre desde los tejidos de vuelta al corazón', 'Realizar el intercambio directo de gases con el medio externo', 'Producir nuevas células sanguíneas'],
   'Las arterias transportan la sangre que sale del corazón hacia los tejidos del cuerpo.'),
  ('90a2a654-8c94-4ebb-abeb-9f6301c1587e', 'en',
   'Compared with veins, arteries have walls that are:',
   array['Thicker and more muscular, to withstand the high pressure of blood pumped by the heart', 'Thinner and less muscular', 'Identical to those of veins, with no structural difference', 'Made exclusively of bone tissue'],
   'The need to withstand the high pressure of the heart''s pumping makes arterial walls thicker.'),
  ('90a2a654-8c94-4ebb-abeb-9f6301c1587e', 'es',
   'En comparación con las venas, las arterias tienen paredes:',
   array['Más gruesas y musculosas, para soportar la alta presión de la sangre bombeada por el corazón', 'Más delgadas y menos musculosas', 'Idénticas a las de las venas, sin ninguna diferencia estructural', 'Compuestas exclusivamente por tejido óseo'],
   'La necesidad de soportar la alta presión del bombeo cardíaco hace que las paredes arteriales sean más gruesas.'),
  ('308aca73-967d-4984-be8a-b94eb1d01cd4', 'en',
   'The aorta, the largest artery in the human body, originates directly from:',
   array['The left ventricle of the heart', 'The right atrium of the heart', 'The lungs', 'The right ventricle of the heart'],
   'The aorta leaves the left ventricle, distributing oxygenated blood to practically the whole body.'),
  ('308aca73-967d-4984-be8a-b94eb1d01cd4', 'es',
   'La aorta, la arteria más grande del cuerpo humano, se origina directamente en:',
   array['El ventrículo izquierdo del corazón', 'La aurícula derecha del corazón', 'Los pulmones', 'El ventrículo derecho del corazón'],
   'La aorta sale del ventrículo izquierdo y distribuye sangre oxigenada a prácticamente todo el cuerpo.'),
  ('3dc0bcc8-a41a-4a60-bcda-2449b7d18473', 'en',
   'The best-known exception regarding the type of blood carried by arteries occurs in the:',
   array['Pulmonary artery, which carries oxygen-poor blood to the lungs', 'Aorta, which would carry oxygen-poor blood', 'Coronary artery, which would carry venous blood', 'There is no exception among the body''s arteries'],
   'Unlike most arteries, the pulmonary artery carries oxygen-poor blood to the lungs.'),
  ('3dc0bcc8-a41a-4a60-bcda-2449b7d18473', 'es',
   'La excepción más conocida en cuanto al tipo de sangre que transportan las arterias ocurre en la:',
   array['Arteria pulmonar, que transporta sangre pobre en oxígeno hasta los pulmones', 'Aorta, que transportaría sangre pobre en oxígeno', 'Arteria coronaria, que transportaría sangre venosa', 'No existe ninguna excepción entre las arterias del cuerpo'],
   'A diferencia de la mayoría de las arterias, la arteria pulmonar transporta sangre pobre en oxígeno hasta los pulmones.'),
  ('88fae0f3-7136-455a-8164-32e8ad03a421', 'en',
   'The buildup of fatty plaques in the arterial walls, a condition known as atherosclerosis, can cause:',
   array['Narrowing and hardening of the arteries, increasing the risk of heart attacks and strokes', 'An immediate increase in arterial elasticity', 'No relevant impact on cardiovascular health', 'Permanent, healthy dilation of the arteries'],
   'Atherosclerosis narrows the arteries and reduces their elasticity, increasing cardiovascular risk.'),
  ('88fae0f3-7136-455a-8164-32e8ad03a421', 'es',
   'La acumulación de placas de grasa en las paredes arteriales, afección conocida como aterosclerosis, puede causar:',
   array['Estrechamiento y endurecimiento de las arterias, lo que aumenta el riesgo de infartos y derrames cerebrales', 'Un aumento inmediato de la elasticidad arterial', 'Ningún impacto relevante en la salud cardiovascular', 'La dilatación permanente y saludable de las arterias'],
   'La aterosclerosis reduce el calibre de las arterias y compromete su elasticidad, lo que aumenta el riesgo cardiovascular.'),
  ('f9648190-7c3d-4c7a-a591-54a7bf58f4d5', 'en',
   'Blood capillaries are characterized by being:',
   array['Extremely thin vessels, with walls only one cell thick', 'The largest blood vessels in the body', 'Purely muscular structures, with no exchange function', 'Identical to arteries in structure and function'],
   'Capillaries have very thin walls, made of a single layer of cells, which makes exchanges easier.'),
  ('f9648190-7c3d-4c7a-a591-54a7bf58f4d5', 'es',
   'Los capilares sanguíneos se caracterizan por ser:',
   array['Vasos extremadamente finos, con paredes de una sola célula de espesor', 'Los vasos sanguíneos más grandes del cuerpo', 'Estructuras exclusivamente musculares, sin ninguna función de intercambio', 'Idénticos a las arterias en estructura y función'],
   'Los capilares tienen paredes muy finas, formadas por una sola capa de células, lo que facilita los intercambios.'),
  ('7a919439-ca6c-45ea-ada1-42d882403af8', 'en',
   'The main function of capillaries is:',
   array['To allow the exchange of gases, nutrients and waste between the blood and the cells of the tissues', 'To actively pump blood at high pressure', 'To store large amounts of blood', 'To produce hormones directly'],
   'It is in the capillaries that the essential exchanges between the blood and the cells take place.'),
  ('7a919439-ca6c-45ea-ada1-42d882403af8', 'es',
   'La principal función de los capilares es:',
   array['Permitir el intercambio de gases, nutrientes y desechos entre la sangre y las células de los tejidos', 'Bombear activamente la sangre a alta presión', 'Almacenar grandes cantidades de sangre', 'Producir hormonas directamente'],
   'Es en los capilares donde ocurren los intercambios esenciales entre la sangre y las células.'),
  ('cfae6893-f71a-4c2d-bca4-316995e58383', 'en',
   'Within the circulatory system, capillaries connect the following types of vessels:',
   array['Arterioles and venules', 'Only large arteries', 'Only large veins', 'The heart directly to the lungs, with no intermediate vessel'],
   'Capillaries form the bridge between the arterial system (arterioles) and the venous system (venules).'),
  ('cfae6893-f71a-4c2d-bca4-316995e58383', 'es',
   'Dentro del sistema circulatorio, los capilares conectan los siguientes tipos de vasos:',
   array['Arteriolas y vénulas', 'Solo arterias de gran calibre', 'Solo venas de gran calibre', 'El corazón directamente con los pulmones, sin ningún vaso intermedio'],
   'Los capilares forman el puente entre el sistema arterial (arteriolas) y el sistema venoso (vénulas).'),
  ('7ce8c20f-8042-4077-8964-078b8b126edb', 'en',
   'The large number of capillaries in the body''s tissues is related mainly to:',
   array['Maximizing the surface area available for exchanges between blood and tissues', 'Increasing blood pressure exclusively', 'Reducing the tissues'' need for oxygen', 'Completely replacing the function of the heart'],
   'The extensive capillary network increases the contact area between blood and cells, optimizing exchanges.'),
  ('7ce8c20f-8042-4077-8964-078b8b126edb', 'es',
   'La gran cantidad de capilares presentes en los tejidos del cuerpo está relacionada, principalmente, con:',
   array['Maximizar la superficie disponible para los intercambios entre la sangre y los tejidos', 'Aumentar exclusivamente la presión arterial', 'Reducir la necesidad de oxígeno de los tejidos', 'Sustituir por completo la función del corazón'],
   'La extensa red de capilares amplía la superficie de contacto entre la sangre y las células y optimiza los intercambios.'),
  ('561cfd10-fec7-4e52-8ec9-bb68bce02890', 'en',
   'Compared with arteries, the speed of blood flow in the capillaries is generally:',
   array['Slower, which allows the time needed for exchanges with the tissues', 'Much faster', 'Exactly the same as in the arteries', 'Zero, with no blood flow at all'],
   'The slower flow in the capillaries allows enough time for the essential exchanges with the cells.'),
  ('561cfd10-fec7-4e52-8ec9-bb68bce02890', 'es',
   'En comparación con las arterias, la velocidad del flujo sanguíneo en los capilares es generalmente:',
   array['Más lenta, lo que favorece el tiempo necesario para los intercambios con los tejidos', 'Mucho más rápida', 'Exactamente igual a la de las arterias', 'Nula, sin ningún flujo sanguíneo'],
   'El flujo más lento en los capilares da tiempo suficiente para los intercambios esenciales con las células.'),
  ('78a1da2d-30e1-47b3-ba63-55b3c35702bb', 'en',
   'Pulmonary circulation is the path of blood between:',
   array['The heart and the lungs, responsible for oxygenating the blood', 'The heart and every other organ of the body, except the lungs', 'Only the lungs and the brain', 'The digestive system and the heart'],
   'In pulmonary circulation, blood leaves the heart toward the lungs, where it is oxygenated.'),
  ('78a1da2d-30e1-47b3-ba63-55b3c35702bb', 'es',
   'La circulación pulmonar es el recorrido de la sangre entre:',
   array['El corazón y los pulmones, responsable de la oxigenación de la sangre', 'El corazón y todos los demás órganos del cuerpo, excepto los pulmones', 'Solo los pulmones y el cerebro', 'El sistema digestivo y el corazón'],
   'En la circulación pulmonar, la sangre sale del corazón hacia los pulmones, donde se oxigena.'),
  ('e98b9847-58a3-440b-877e-47b03d82fd6c', 'en',
   'In pulmonary circulation, blood leaves the heart through the:',
   array['Right ventricle, via the pulmonary artery', 'Left ventricle, via the aorta', 'Right atrium, directly', 'Left atrium, directly'],
   'The right ventricle pumps oxygen-poor blood to the lungs through the pulmonary artery.'),
  ('e98b9847-58a3-440b-877e-47b03d82fd6c', 'es',
   'En la circulación pulmonar, la sangre sale del corazón por el:',
   array['Ventrículo derecho, a través de la arteria pulmonar', 'Ventrículo izquierdo, a través de la aorta', 'La aurícula derecha, directamente', 'La aurícula izquierda, directamente'],
   'El ventrículo derecho bombea la sangre pobre en oxígeno hacia los pulmones a través de la arteria pulmonar.'),
  ('5b6ef0d0-5544-49c6-9616-127eee2e095d', 'en',
   'After being oxygenated in the lungs, blood returns to the heart through:',
   array['The pulmonary veins, arriving at the left atrium', 'The vena cava, arriving at the right atrium', 'The aorta, arriving at the left ventricle', 'The pulmonary artery, arriving at the right ventricle'],
   'Oxygenated blood returns from the lungs through the pulmonary veins, entering the heart at the left atrium.'),
  ('5b6ef0d0-5544-49c6-9616-127eee2e095d', 'es',
   'Después de oxigenarse en los pulmones, la sangre vuelve al corazón a través de:',
   array['Las venas pulmonares, llegando a la aurícula izquierda', 'La vena cava, llegando a la aurícula derecha', 'La aorta, llegando al ventrículo izquierdo', 'La arteria pulmonar, llegando al ventrículo derecho'],
   'La sangre oxigenada vuelve de los pulmones por las venas pulmonares y entra al corazón por la aurícula izquierda.'),
  ('07a9d7e7-007f-4fca-a534-b02955eaa7c2', 'en',
   'Pulmonary circulation is also called "lesser circulation" because:',
   array['It follows a shorter path, only between the heart and the lungs', 'It involves a smaller amount of blood than systemic circulation', 'It only occurs in babies, not in adults', 'It involves no blood vessels at all'],
   'Because it is limited to the path between the heart and the lungs, it is called "lesser circulation".'),
  ('07a9d7e7-007f-4fca-a534-b02955eaa7c2', 'es',
   'La circulación pulmonar también se llama "circulación menor" porque:',
   array['Recorre un trayecto más corto, solo entre el corazón y los pulmones', 'Implica una cantidad menor de sangre que la circulación sistémica', 'Ocurre solo en bebés, y no en adultos', 'No implica ningún vaso sanguíneo'],
   'Por limitarse al trayecto entre el corazón y los pulmones, se llama "circulación menor".'),
  ('52223730-4c0e-4e04-84b2-38c2a5b7e4c4', 'en',
   'During pulmonary circulation, the blood is oxygenated specifically:',
   array['In the pulmonary alveoli, through gas exchange with the inhaled air', 'In the heart itself, with no involvement of the lungs', 'In the kidneys, during blood filtration', 'In the liver, during the metabolism of nutrients'],
   'It is in the pulmonary alveoli that gas exchange between the blood and the inhaled air takes place.'),
  ('52223730-4c0e-4e04-84b2-38c2a5b7e4c4', 'es',
   'Durante la circulación pulmonar, la oxigenación de la sangre ocurre específicamente:',
   array['En los alvéolos pulmonares, mediante el intercambio gaseoso con el aire inspirado', 'En el propio corazón, sin ninguna participación de los pulmones', 'En los riñones, durante la filtración sanguínea', 'En el hígado, durante el metabolismo de los nutrientes'],
   'Es en los alvéolos pulmonares donde ocurre el intercambio gaseoso entre la sangre y el aire inspirado.'),
  ('df86c060-b2cf-401e-9f76-6ecbf24b543b', 'en',
   'Systemic circulation is the path of blood between:',
   array['The heart and every other organ and tissue of the body (except the lungs)', 'Exclusively the heart and the lungs', 'Only the brain and the heart', 'The digestive system and the kidneys'],
   'Systemic circulation carries oxygenated blood from the heart to the whole body and brings back oxygen-poor blood.'),
  ('df86c060-b2cf-401e-9f76-6ecbf24b543b', 'es',
   'La circulación sistémica es el recorrido de la sangre entre:',
   array['El corazón y todos los demás órganos y tejidos del cuerpo (excepto los pulmones)', 'Exclusivamente el corazón y los pulmones', 'Solo el cerebro y el corazón', 'El sistema digestivo y los riñones'],
   'La circulación sistémica lleva sangre oxigenada del corazón a todo el cuerpo y trae de vuelta la sangre pobre en oxígeno.'),
  ('4a3f6aaf-c1a8-453c-9de7-93b8397c5cb6', 'en',
   'In systemic circulation, oxygenated blood leaves the heart through the:',
   array['Left ventricle, via the aorta', 'Right ventricle, via the pulmonary artery', 'Left atrium, directly', 'Right atrium, directly'],
   'The left ventricle pumps oxygen-rich blood to the body through the aorta.'),
  ('4a3f6aaf-c1a8-453c-9de7-93b8397c5cb6', 'es',
   'En la circulación sistémica, la sangre oxigenada sale del corazón por el:',
   array['Ventrículo izquierdo, a través de la aorta', 'Ventrículo derecho, a través de la arteria pulmonar', 'La aurícula izquierda, directamente', 'La aurícula derecha, directamente'],
   'El ventrículo izquierdo bombea sangre rica en oxígeno hacia el cuerpo a través de la aorta.'),
  ('15af0498-e456-4a46-8be7-e83dbb2c77b1', 'en',
   'After passing through the body''s tissues, oxygen-poor blood returns to the heart through the:',
   array['Venae cavae, arriving at the right atrium', 'Pulmonary veins, arriving at the left atrium', 'Pulmonary artery, arriving at the right ventricle', 'Aorta, arriving at the left ventricle'],
   'Venous blood from the whole body returns to the heart through the venae cavae, arriving at the right atrium.'),
  ('15af0498-e456-4a46-8be7-e83dbb2c77b1', 'es',
   'Después de recorrer los tejidos del cuerpo, la sangre pobre en oxígeno vuelve al corazón por:',
   array['Las venas cavas, llegando a la aurícula derecha', 'Las venas pulmonares, llegando a la aurícula izquierda', 'La arteria pulmonar, llegando al ventrículo derecho', 'La aorta, llegando al ventrículo izquierdo'],
   'La sangre venosa de todo el cuerpo vuelve al corazón a través de las venas cavas y llega a la aurícula derecha.'),
  ('6dc9e7f2-1414-4384-8faa-07865a733c1e', 'en',
   'Systemic circulation is also called "greater circulation" because:',
   array['It follows a much longer path, reaching every organ and tissue of the body', 'It involves a smaller amount of blood than pulmonary circulation', 'It only occurs in the lungs', 'It involves no blood vessels at all'],
   'Because it covers the whole body, systemic circulation is called "greater circulation".'),
  ('6dc9e7f2-1414-4384-8faa-07865a733c1e', 'es',
   'La circulación sistémica también se llama "circulación mayor" porque:',
   array['Recorre un trayecto mucho más largo y llega a todos los órganos y tejidos del cuerpo', 'Implica una cantidad menor de sangre que la circulación pulmonar', 'Ocurre solo en los pulmones', 'No implica ningún vaso sanguíneo'],
   'Por abarcar todo el cuerpo, la circulación sistémica se llama "circulación mayor".'),
  ('0382bc1b-8fb5-4f1f-b9b2-d239a0b5ba80', 'en',
   'During systemic circulation, the capillaries in the tissues carry out essential exchanges, such as:',
   array['Delivering oxygen and nutrients to the cells and picking up carbon dioxide and metabolic waste', 'Oxygenating the blood directly, as happens in the lungs', 'Producing new blood cells', 'No relevant exchange takes place along this path'],
   'It is in the systemic capillaries that the fundamental exchanges between the blood and the tissue cells take place.'),
  ('0382bc1b-8fb5-4f1f-b9b2-d239a0b5ba80', 'es',
   'Durante la circulación sistémica, los capilares de los tejidos realizan intercambios esenciales, como:',
   array['La entrega de oxígeno y nutrientes a las células y la captación de dióxido de carbono y desechos metabólicos', 'La oxigenación directa de la sangre, como ocurre en los pulmones', 'La producción de nuevas células sanguíneas', 'En este trayecto no ocurre ningún intercambio relevante'],
   'Es en los capilares sistémicos donde ocurren los intercambios fundamentales entre la sangre y las células de los tejidos.'),
  ('9c9c5c74-043e-497f-ae9d-948014c89a56', 'en',
   'The human heart is a muscular organ divided internally into:',
   array['Four chambers: two atria and two ventricles', 'Only two chambers', 'Six chambers', 'A single continuous chamber'],
   'The human heart has four chambers: right atrium, left atrium, right ventricle and left ventricle.'),
  ('9c9c5c74-043e-497f-ae9d-948014c89a56', 'es',
   'El corazón humano es un órgano muscular dividido internamente en:',
   array['Cuatro cavidades: dos aurículas y dos ventrículos', 'Solo dos cavidades', 'Seis cavidades', 'Una única cavidad continua'],
   'El corazón humano tiene cuatro cámaras: aurícula derecha, aurícula izquierda, ventrículo derecho y ventrículo izquierdo.'),
  ('af8eba40-f908-433d-85f5-2199451beae3', 'en',
   'The main function of the atria, the upper chambers of the heart, is:',
   array['To receive blood coming from the veins before pumping it into the ventricles', 'To pump blood directly into the body''s arteries', 'To produce blood cells', 'To filter the blood before it circulates'],
   'The atria receive venous blood and pass it on to the ventricles, which are responsible for the stronger pumping.'),
  ('af8eba40-f908-433d-85f5-2199451beae3', 'es',
   'La principal función de las aurículas, cámaras superiores del corazón, es:',
   array['Recibir la sangre que llega de las venas antes de bombearla a los ventrículos', 'Bombear la sangre directamente a las arterias del cuerpo', 'Producir células sanguíneas', 'Filtrar la sangre antes de que circule'],
   'Las aurículas reciben la sangre venosa y la transfieren a los ventrículos, responsables del bombeo más vigoroso.'),
  ('0f7ab9ea-4a87-4120-95a5-786938c6fb92', 'en',
   'The left ventricle, usually the chamber of the heart with the thickest muscular walls, is responsible for pumping blood to:',
   array['The whole body, through systemic circulation', 'Only the lungs, through pulmonary circulation', 'The right atrium directly', 'No part of the body, only storing blood'],
   'Because it drives blood through the whole body, the left ventricle has the most developed musculature.'),
  ('0f7ab9ea-4a87-4120-95a5-786938c6fb92', 'es',
   'El ventrículo izquierdo, generalmente la cámara del corazón con las paredes musculares más gruesas, es responsable de bombear sangre hacia:',
   array['Todo el cuerpo, a través de la circulación sistémica', 'Solo los pulmones, a través de la circulación pulmonar', 'La aurícula derecha directamente', 'Ninguna parte del cuerpo, solo almacenar sangre'],
   'Por impulsar la sangre a todo el cuerpo, el ventrículo izquierdo tiene la musculatura más desarrollada.'),
  ('bbd7b356-228c-4627-8409-98030ef6a81a', 'en',
   'The sinoatrial node, the structure responsible for starting the heartbeat, is often called the:',
   array['Heart''s natural pacemaker', 'Main heart valve', 'Coronary artery', 'Vena cava'],
   'The sinoatrial node generates the electrical impulses that set the rhythm of the heartbeat.'),
  ('bbd7b356-228c-4627-8409-98030ef6a81a', 'es',
   'El nódulo sinoauricular, la estructura responsable de iniciar los latidos del corazón, suele llamarse:',
   array['Marcapasos natural del corazón', 'Válvula cardíaca principal', 'Arteria coronaria', 'Vena cava'],
   'El nódulo sinoauricular genera los impulsos eléctricos que determinan el ritmo de los latidos cardíacos.'),
  ('876133d3-aaef-45c4-93f4-1127a9bf856b', 'en',
   'The specific function of the coronary arteries is:',
   array['To supply the heart muscle itself with oxygenated blood', 'To carry blood from the heart to the lungs', 'To collect venous blood from the whole body', 'To completely replace the function of the ventricles'],
   'The coronary arteries supply oxygen and nutrients directly to the heart muscle (myocardium).'),
  ('876133d3-aaef-45c4-93f4-1127a9bf856b', 'es',
   'La función específica de las arterias coronarias es:',
   array['Irrigar el propio músculo cardíaco con sangre oxigenada', 'Llevar sangre del corazón a los pulmones', 'Recoger la sangre venosa de todo el cuerpo', 'Sustituir por completo la función de los ventrículos'],
   'Las coronarias suministran oxígeno y nutrientes directamente al músculo cardíaco (miocardio).'),
  ('7c4ccc58-ec4b-40d7-91fa-fe52d61d4ed4', 'en',
   'Veins are blood vessels responsible for:',
   array['Carrying blood from the tissues back to the heart', 'Carrying blood from the heart to the tissues', 'Actively pumping blood at high pressure', 'Producing red and white blood cells'],
   'Veins carry blood back to the heart, usually oxygen-poor (except the pulmonary veins).'),
  ('7c4ccc58-ec4b-40d7-91fa-fe52d61d4ed4', 'es',
   'Las venas son vasos sanguíneos responsables de:',
   array['Conducir la sangre desde los tejidos de vuelta al corazón', 'Conducir la sangre desde el corazón hacia los tejidos', 'Bombear activamente la sangre a alta presión', 'Producir glóbulos rojos y leucocitos'],
   'Las venas transportan la sangre de vuelta al corazón, generalmente pobre en oxígeno (excepto las venas pulmonares).'),
  ('e81e6e10-9d28-46b4-bfc9-6ed3dd2aa309', 'en',
   'Many veins, especially in the legs, have internal structures called:',
   array['Venous valves, which prevent the backflow of blood', 'Sinoatrial nodes', 'Alveoli', 'Mitochondrial cristae'],
   'Venous valves help prevent blood from flowing back due to gravity, aiding the flow toward the heart.'),
  ('e81e6e10-9d28-46b4-bfc9-6ed3dd2aa309', 'es',
   'Muchas venas, especialmente en las piernas, tienen estructuras internas llamadas:',
   array['Válvulas venosas, que impiden el reflujo de la sangre', 'Nódulos sinoauriculares', 'Alvéolos', 'Crestas mitocondriales'],
   'Las válvulas venosas ayudan a impedir que la sangre retroceda por la gravedad y favorecen el flujo hacia el corazón.'),
  ('46273220-ac4b-439f-a64f-4dce0dc51114', 'en',
   'The vena cava, one of the body''s main venous vessels, is responsible for carrying blood directly to:',
   array['The right atrium of the heart', 'The left ventricle of the heart', 'The lungs directly', 'The aorta'],
   'The superior and inferior venae cavae empty into the right atrium, bringing venous blood back from the whole body.'),
  ('46273220-ac4b-439f-a64f-4dce0dc51114', 'es',
   'La vena cava, uno de los principales vasos venosos del cuerpo, se encarga de conducir la sangre directamente a:',
   array['La aurícula derecha del corazón', 'El ventrículo izquierdo del corazón', 'Los pulmones directamente', 'La aorta'],
   'Las venas cavas superior e inferior desembocan en la aurícula derecha y traen de vuelta la sangre venosa de todo el cuerpo.'),
  ('42528ba2-e638-41a0-a742-0af0962ebe03', 'en',
   'Unlike most veins in the body, the pulmonary veins carry blood that is:',
   array['Rich in oxygen, from the lungs to the left atrium of the heart', 'Poor in oxygen, from the heart to the lungs', 'Identical to that carried by the vena cava', 'Exclusively for the kidneys'],
   'The pulmonary veins are an exception, carrying oxygenated blood from the lungs back to the heart.'),
  ('42528ba2-e638-41a0-a742-0af0962ebe03', 'es',
   'A diferencia de la mayoría de las venas del cuerpo, las venas pulmonares transportan sangre:',
   array['Rica en oxígeno, desde los pulmones hasta la aurícula izquierda del corazón', 'Pobre en oxígeno, desde el corazón hacia los pulmones', 'Idéntica a la que transporta la vena cava', 'Exclusivamente hacia los riñones'],
   'Las venas pulmonares son una excepción: transportan sangre oxigenada desde los pulmones de vuelta al corazón.'),
  ('9ce573dd-8e21-4e91-9746-902961dae822', 'en',
   'The contraction of skeletal muscles, especially in the legs, helps venous blood return to the heart because it:',
   array['Squeezes the veins, helping push the blood against gravity', 'Completely blocks blood flow in the veins', 'Has nothing to do with venous circulation', 'Permanently lowers blood pressure'],
   'Muscle movement squeezes the nearby veins, helping blood return to the heart.'),
  ('9ce573dd-8e21-4e91-9746-902961dae822', 'es',
   'La contracción de los músculos esqueléticos, sobre todo en las piernas, ayuda al retorno de la sangre venosa al corazón porque:',
   array['Comprime las venas y ayuda a impulsar la sangre contra la gravedad', 'Bloquea por completo el flujo sanguíneo en las venas', 'No tiene ninguna relación con la circulación venosa', 'Reduce la presión arterial de forma permanente'],
   'El movimiento muscular comprime las venas cercanas y ayuda al retorno de la sangre al corazón.'),
  ('043184ef-0330-4c8f-8fb6-08d51492f257', 'en',
   'The main function of the heart valves is:',
   array['To ensure that blood flows in one direction only, preventing backflow', 'To actively pump blood through the body', 'To produce the heart''s electrical impulses', 'To filter impurities from the blood'],
   'Heart valves open and close according to pressure differences, ensuring one-way blood flow.'),
  ('043184ef-0330-4c8f-8fb6-08d51492f257', 'es',
   'La principal función de las válvulas cardíacas es:',
   array['Garantizar que la sangre fluya en una sola dirección, impidiendo el reflujo', 'Bombear activamente la sangre por el cuerpo', 'Producir los impulsos eléctricos del corazón', 'Filtrar las impurezas de la sangre'],
   'Las válvulas cardíacas se abren y se cierran según las diferencias de presión y garantizan el flujo unidireccional de la sangre.'),
  ('89da672c-370e-497e-ab6c-3f5148adb73c', 'en',
   'The mitral (or bicuspid) valve is located between:',
   array['The left atrium and the left ventricle', 'The right atrium and the right ventricle', 'The left ventricle and the aorta', 'The right ventricle and the pulmonary artery'],
   'The mitral valve controls the passage of blood from the left atrium to the left ventricle.'),
  ('89da672c-370e-497e-ab6c-3f5148adb73c', 'es',
   'La válvula mitral (o bicúspide) está ubicada entre:',
   array['La aurícula izquierda y el ventrículo izquierdo', 'La aurícula derecha y el ventrículo derecho', 'El ventrículo izquierdo y la aorta', 'El ventrículo derecho y la arteria pulmonar'],
   'La válvula mitral controla el paso de la sangre de la aurícula izquierda al ventrículo izquierdo.'),
  ('941f0008-aea0-4861-97cf-bb1728bae747', 'en',
   'The tricuspid valve is located between:',
   array['The right atrium and the right ventricle', 'The left atrium and the left ventricle', 'The left ventricle and the aorta', 'The right atrium and the vena cava'],
   'The tricuspid valve controls the passage of blood from the right atrium to the right ventricle.'),
  ('941f0008-aea0-4861-97cf-bb1728bae747', 'es',
   'La válvula tricúspide está ubicada entre:',
   array['La aurícula derecha y el ventrículo derecho', 'La aurícula izquierda y el ventrículo izquierdo', 'El ventrículo izquierdo y la aorta', 'La aurícula derecha y la vena cava'],
   'La válvula tricúspide controla el paso de la sangre de la aurícula derecha al ventrículo derecho.'),
  ('8d9949fc-6f29-4d38-9048-b4b84e08183a', 'en',
   'The improper functioning of a heart valve, allowing blood to flow backward, is a medical condition known as:',
   array['Valve insufficiency (regurgitation)', 'Arrhythmia, exclusively', 'Anemia', 'High blood pressure, exclusively'],
   'When a valve does not close properly, blood flows backward, a condition called valve insufficiency.'),
  ('8d9949fc-6f29-4d38-9048-b4b84e08183a', 'es',
   'El funcionamiento inadecuado de una válvula cardíaca, que permite el reflujo de sangre, es una afección médica conocida como:',
   array['Insuficiencia valvular', 'Arritmia, exclusivamente', 'Anemia', 'Hipertensión arterial, exclusivamente'],
   'Cuando una válvula no cierra bien, se produce reflujo de sangre, afección llamada insuficiencia valvular.'),
  ('7dae3824-dc2e-4536-a84f-7a685ea71ab3', 'en',
   'The characteristic sound of the heartbeat, heard with a stethoscope, is caused mainly by:',
   array['The closing of the heart valves', 'The opening of the heart valves', 'The contraction of the leg muscles', 'Air passing through the lungs'],
   'The characteristic heart sounds are produced mainly by the sequential closing of the heart valves.'),
  ('7dae3824-dc2e-4536-a84f-7a685ea71ab3', 'es',
   'El sonido característico de los latidos cardíacos, que se oye con un estetoscopio, se debe principalmente a:',
   array['El cierre de las válvulas cardíacas', 'La apertura de las válvulas cardíacas', 'La contracción de los músculos de las piernas', 'El paso de aire por los pulmones'],
   'Los ruidos cardíacos característicos se producen principalmente por el cierre secuencial de las válvulas cardíacas.'),
  ('93e842b4-7165-4339-bac2-bc7e8669c5de', 'en',
   'The main function of the digestive system is:',
   array['To process food, turning it into nutrients that the body can absorb', 'To produce hormones exclusively', 'To carry out the body''s gas exchange', 'To filter the blood, eliminating metabolic waste'],
   'The digestive system breaks food down into smaller molecules that the body can absorb.'),
  ('93e842b4-7165-4339-bac2-bc7e8669c5de', 'es',
   'La función principal del sistema digestivo es:',
   array['Procesar los alimentos y transformarlos en nutrientes que el organismo pueda absorber', 'Producir hormonas exclusivamente', 'Realizar el intercambio gaseoso del cuerpo', 'Filtrar la sangre y eliminar los desechos metabólicos'],
   'El sistema digestivo descompone los alimentos en moléculas más pequeñas que el organismo puede absorber.'),
  ('af5be53c-120d-404b-a35f-81c5d876e00f', 'en',
   'Digestion begins in the mouth, mainly through:',
   array['Chewing and the action of enzymes in saliva, such as salivary amylase', 'Exclusively the action of gastric juice', 'The direct absorption of nutrients by the tongue', 'Processes that occur only in the intestine'],
   'Chewing breaks up the food, while salivary amylase already starts breaking down carbohydrates.'),
  ('af5be53c-120d-404b-a35f-81c5d876e00f', 'es',
   'La digestión de los alimentos comienza ya en la boca, principalmente mediante:',
   array['La masticación y la acción de enzimas de la saliva, como la amilasa salival', 'Exclusivamente la acción del jugo gástrico', 'La absorción directa de nutrientes por la lengua', 'Procesos que ocurren solo en el intestino'],
   'La masticación fragmenta el alimento, mientras que la amilasa salival ya inicia la descomposición de los carbohidratos.'),
  ('d8058663-9eb2-4b0c-96cb-ad0af453a6b1', 'en',
   'The stomach, a key organ of the digestive system, is responsible, among other functions, for:',
   array['Producing gastric juice, rich in hydrochloric acid and digestive enzymes', 'Absorbing most of the nutrients from food', 'Producing insulin directly', 'Filtering the blood'],
   'The stomach secretes gastric juice, which helps digest proteins and eliminate microorganisms.'),
  ('d8058663-9eb2-4b0c-96cb-ad0af453a6b1', 'es',
   'El estómago, órgano fundamental del sistema digestivo, es responsable, entre otras funciones, de:',
   array['Producir jugo gástrico, rico en ácido clorhídrico y enzimas digestivas', 'Absorber la mayor parte de los nutrientes de los alimentos', 'Producir insulina directamente', 'Filtrar la sangre'],
   'El estómago secreta jugo gástrico, que ayuda a digerir las proteínas y a eliminar microorganismos.'),
  ('6ff657bc-61fa-42fc-8e56-963a8f665b51', 'en',
   'Most of the absorption of nutrients from food takes place mainly in:',
   array['The small intestine', 'The stomach', 'The large intestine', 'The esophagus'],
   'The small intestine, with its large absorptive surface, is the main site of nutrient absorption.'),
  ('6ff657bc-61fa-42fc-8e56-963a8f665b51', 'es',
   'La mayor parte de la absorción de los nutrientes de los alimentos ocurre principalmente en:',
   array['El intestino delgado', 'El estómago', 'El intestino grueso', 'El esófago'],
   'El intestino delgado, con su gran superficie de absorción, es el principal lugar de absorción de nutrientes.'),
  ('a2511293-fd21-4a60-85f3-dee714e66bc7', 'en',
   'Although they are not directly part of the "digestive tube", the liver and the pancreas contribute to digestion by producing, respectively:',
   array['Bile (which helps digest fats) and digestive enzymes', 'Only sex hormones', 'Exclusively blood cells', 'No substance relevant to digestion'],
   'The liver produces bile, essential for emulsifying fats; the pancreas secretes important digestive enzymes.'),
  ('a2511293-fd21-4a60-85f3-dee714e66bc7', 'es',
   'Aunque no forman parte directamente del "tubo digestivo", el hígado y el páncreas contribuyen a la digestión al producir, respectivamente:',
   array['Bilis (que ayuda a digerir las grasas) y enzimas digestivas', 'Solo hormonas sexuales', 'Exclusivamente células sanguíneas', 'Ninguna sustancia relevante para la digestión'],
   'El hígado produce bilis, esencial para emulsionar las grasas; el páncreas secreta enzimas digestivas importantes.'),
  ('44807e1e-1865-4038-8a07-168a2f9ed163', 'en',
   'The endocrine system is mainly responsible for:',
   array['Producing and secreting hormones, which regulate many of the body''s functions', 'Conducting nerve impulses quickly through the body', 'Digesting food', 'Filtering impurities from the blood'],
   'The endocrine system works through hormones released into the bloodstream, regulating physiological processes.'),
  ('44807e1e-1865-4038-8a07-168a2f9ed163', 'es',
   'El sistema endocrino es responsable principalmente de:',
   array['Producir y secretar hormonas, que regulan diversas funciones del organismo', 'Conducir impulsos nerviosos rápidamente por el cuerpo', 'Digerir los alimentos', 'Filtrar las impurezas de la sangre'],
   'El sistema endocrino actúa mediante hormonas liberadas al torrente sanguíneo, que regulan procesos fisiológicos.'),
  ('0d78f170-cb19-4de5-aee5-4696c594c566', 'en',
   'Unlike the nervous system, which acts through fast electrical impulses, the endocrine system usually produces responses that are:',
   array['Slower, but often longer-lasting', 'Instantaneous, with no delay at all', 'Identical in speed to those of the nervous system', 'Never significant for the body'],
   'Hormonal action is usually slower than nervous action, but its effects tend to last longer.'),
  ('0d78f170-cb19-4de5-aee5-4696c594c566', 'es',
   'A diferencia del sistema nervioso, que actúa mediante impulsos eléctricos rápidos, el sistema endocrino generalmente produce respuestas:',
   array['Más lentas, pero a menudo más duraderas', 'Instantáneas, sin ningún retraso', 'Idénticas en velocidad a las del sistema nervioso', 'Que nunca afectan al cuerpo de forma significativa'],
   'La acción hormonal suele ser más lenta que la nerviosa, pero sus efectos tienden a ser más prolongados.'),
  ('fed27107-319e-4026-a7e4-815cb9118439', 'en',
   'The main function of insulin, a hormone produced by the pancreas, is:',
   array['To regulate blood glucose levels, helping glucose enter the cells', 'To control blood pressure exclusively', 'To produce blood cells', 'To regulate body temperature'],
   'Insulin allows the glucose in the blood to be taken up by the cells, lowering blood sugar.'),
  ('fed27107-319e-4026-a7e4-815cb9118439', 'es',
   'La principal función de la insulina, hormona producida por el páncreas, es:',
   array['Regular los niveles de glucosa en la sangre, facilitando su entrada en las células', 'Controlar exclusivamente la presión arterial', 'Producir células sanguíneas', 'Regular la temperatura corporal'],
   'La insulina permite que las células absorban la glucosa de la sangre, lo que reduce la glucemia.'),
  ('ebf80787-9764-44fd-ac1b-ed98ccac45bb', 'en',
   'The thyroid gland, an important part of the endocrine system, produces hormones that mainly regulate:',
   array['The body''s overall metabolism', 'Only fat digestion', 'The production of nerve cells', 'Kidney filtration'],
   'Thyroid hormones directly influence the body''s basal metabolic rate.'),
  ('ebf80787-9764-44fd-ac1b-ed98ccac45bb', 'es',
   'La glándula tiroides, componente importante del sistema endocrino, produce hormonas que regulan principalmente:',
   array['El metabolismo general del cuerpo', 'Exclusivamente la digestión de las grasas', 'La producción de células nerviosas', 'La filtración renal'],
   'Las hormonas tiroideas influyen directamente en la tasa metabólica basal del organismo.'),
  ('3c9126dd-b65f-432c-b374-03aa31846299', 'en',
   'Disorders in the functioning of the endocrine glands, such as producing too much or too little of a hormone, can cause:',
   array['Various diseases and physiological imbalances in the body', 'No relevant impact on health', 'An automatic improvement in bodily functions', 'Only cosmetic changes, with no internal effect'],
   'Hormonal imbalance can significantly affect many bodily functions, causing diseases such as diabetes.'),
  ('3c9126dd-b65f-432c-b374-03aa31846299', 'es',
   'Los trastornos en el funcionamiento de las glándulas endocrinas, como la producción excesiva o insuficiente de una hormona, pueden causar:',
   array['Diversas enfermedades y desequilibrios fisiológicos en el organismo', 'Ningún impacto relevante en la salud', 'Una mejora automática del funcionamiento corporal', 'Solo cambios estéticos, sin ningún efecto interno'],
   'El desequilibrio hormonal puede afectar significativamente diversas funciones corporales y causar enfermedades como la diabetes.'),
  ('57902bdb-ae71-4fb6-9b25-692cb343ec1c', 'en',
   'The main function of the immune system is:',
   array['To defend the body against invaders, such as bacteria, viruses and other pathogens', 'To digest food', 'To produce sex hormones', 'To conduct nerve impulses'],
   'The immune system identifies and fights microorganisms and potentially harmful substances.'),
  ('57902bdb-ae71-4fb6-9b25-692cb343ec1c', 'es',
   'La principal función del sistema inmunitario es:',
   array['Defender el organismo contra agentes invasores, como bacterias, virus y otros patógenos', 'Digerir los alimentos', 'Producir hormonas sexuales', 'Conducir impulsos nerviosos'],
   'El sistema inmunitario identifica y combate microorganismos y sustancias potencialmente nocivas.'),
  ('d1fdc9f4-e5cd-4aa2-a5d1-72dc94a2623d', 'en',
   'White blood cells (leukocytes) play a key role in the immune system by:',
   array['Identifying and directly fighting pathogens in the body', 'Carrying oxygen in the blood', 'Producing blood clotting, exclusively', 'Absorbing nutrients from the intestine'],
   'Different types of leukocytes defend the body, engulfing pathogens or producing antibodies.'),
  ('d1fdc9f4-e5cd-4aa2-a5d1-72dc94a2623d', 'es',
   'Los glóbulos blancos (leucocitos) cumplen un papel fundamental en el sistema inmunitario al:',
   array['Identificar y combatir directamente a los agentes patógenos en el organismo', 'Transportar oxígeno por la sangre', 'Producir la coagulación sanguínea, exclusivamente', 'Absorber nutrientes del intestino'],
   'Distintos tipos de leucocitos actúan en la defensa del organismo, fagocitando patógenos o produciendo anticuerpos.'),
  ('612c39e4-f8d6-444f-8ab9-d25ed9f7b84c', 'en',
   'The main function of antibodies, produced by certain cells of the immune system (B lymphocytes), is:',
   array['To specifically recognize and neutralize antigens, such as those found on viruses and bacteria', 'To produce energy for the cells', 'To completely replace the function of red blood cells', 'To digest macromolecules inside the body'],
   'Antibodies bind specifically to antigens, marking them for destruction or neutralizing their action.'),
  ('612c39e4-f8d6-444f-8ab9-d25ed9f7b84c', 'es',
   'La principal función de los anticuerpos, producidos por ciertas células del sistema inmunitario (linfocitos B), es:',
   array['Reconocer y neutralizar de forma específica los antígenos, como los presentes en virus y bacterias', 'Producir energía para las células', 'Sustituir por completo la función de los glóbulos rojos', 'Digerir macromoléculas dentro del organismo'],
   'Los anticuerpos se unen específicamente a los antígenos, los marcan para su destrucción o neutralizan su acción.'),
  ('e5eb81ef-8e0a-4425-a60e-1aabdd335591', 'en',
   'Vaccination works by stimulating the immune system through:',
   array['Introducing a weakened or inactivated pathogen, or part of one, stimulating the production of immune memory', 'Completely eliminating the need for an immune response', 'Directly introducing ready-made, permanent antibodies, with no stimulus to the body', 'Permanently weakening the immune system'],
   'Vaccines train the immune system to recognize a pathogen, creating memory for faster future responses.'),
  ('e5eb81ef-8e0a-4425-a60e-1aabdd335591', 'es',
   'La vacunación actúa estimulando el sistema inmunitario al:',
   array['Introducir una versión debilitada o inactivada de un patógeno, o parte de él, lo que estimula la memoria inmunitaria', 'Eliminar por completo la necesidad de respuesta inmunitaria', 'Introducir directamente anticuerpos listos y permanentes, sin ningún estímulo al organismo', 'Debilitar permanentemente el sistema inmunitario'],
   'Las vacunas entrenan al sistema inmunitario para reconocer un patógeno y generan memoria para respuestas futuras más rápidas.'),
  ('25ca609d-c008-458f-9cec-5330492d2a55', 'en',
   'Autoimmune diseases occur when the immune system:',
   array['Mistakenly attacks the body''s own cells and tissues', 'Stops working completely, with no activity at all', 'Acts exclusively against external agents, with no possible error', 'Produces only healthy blood cells'],
   'In autoimmune diseases, the immune system mistakenly attacks the body''s own healthy tissues.'),
  ('25ca609d-c008-458f-9cec-5330492d2a55', 'es',
   'Las enfermedades autoinmunes ocurren cuando el sistema inmunitario:',
   array['Ataca por error las células y los tejidos del propio organismo', 'Deja de funcionar por completo, sin ninguna actividad', 'Actúa exclusivamente contra agentes externos, sin ningún error posible', 'Produce exclusivamente células sanguíneas sanas'],
   'En las enfermedades autoinmunes, el sistema inmunitario ataca por error tejidos sanos del propio cuerpo.'),
  ('b2c69a17-afbf-46de-bcc2-2708adf453f1', 'en',
   'The reflex arc is defined as:',
   array['The neural pathway followed by a nerve impulse during a reflex response, usually fast and involuntary', 'A type of exclusively chemical synapse', 'The structure responsible for producing hormones', 'An organelle found in neurons'],
   'The reflex arc is the path followed by the nerve impulse in an automatic response, without conscious processing by the brain.'),
  ('b2c69a17-afbf-46de-bcc2-2708adf453f1', 'es',
   'El arco reflejo se define como:',
   array['El camino neural que recorre un impulso nervioso durante una respuesta refleja, generalmente rápida e involuntaria', 'Un tipo de sinapsis exclusivamente química', 'La estructura responsable de producir hormonas', 'Un orgánulo presente en las neuronas'],
   'El arco reflejo es el trayecto que recorre el impulso nervioso en una respuesta automática, sin procesamiento cerebral consciente.'),
  ('fc13a4ec-b711-4d9e-9b2d-c7920f3908cd', 'en',
   'A classic example of a reflex arc is quickly pulling your hand away after touching something very hot, a response that takes place mainly through:',
   array['The spinal cord, with no need for immediate processing by the brain', 'Exclusively the brain, with full conscious processing', 'The digestive system', 'The lungs'],
   'In many reflexes, the motor response is coordinated directly by the spinal cord, which makes the reaction faster.'),
  ('fc13a4ec-b711-4d9e-9b2d-c7920f3908cd', 'es',
   'Un ejemplo clásico de arco reflejo es retirar rápidamente la mano al tocar algo muy caliente, respuesta que ocurre principalmente a través de:',
   array['La médula espinal, sin necesidad de procesamiento cerebral inmediato', 'Exclusivamente el cerebro, con procesamiento consciente completo', 'El sistema digestivo', 'Los pulmones'],
   'En muchos reflejos, la respuesta motora es coordinada directamente por la médula espinal, lo que hace la reacción más rápida.'),
  ('3ab67b91-4bd6-4482-927a-cbda53283728', 'en',
   'The main components of a reflex arc include, in sequence:',
   array['Sensory receptor, sensory neuron, integration center (usually the spinal cord), motor neuron and effector', 'Only the brain and the muscles, with no other structure', 'Exclusively organs of the digestive system', 'Only blood vessels'],
   'The reflex arc follows this structural sequence, ensuring a fast, automatic response to certain stimuli.'),
  ('3ab67b91-4bd6-4482-927a-cbda53283728', 'es',
   'Los principales componentes de un arco reflejo incluyen, en secuencia:',
   array['Receptor sensorial, neurona sensitiva, centro de integración (generalmente la médula), neurona motora y efector', 'Solo el cerebro y los músculos, sin ninguna otra estructura', 'Exclusivamente órganos del sistema digestivo', 'Solo vasos sanguíneos'],
   'El arco reflejo sigue esta secuencia estructural, que garantiza una respuesta rápida y automática a ciertos estímulos.'),
  ('6580a5a5-5f94-4fc4-9196-80ee9f2261a6', 'en',
   'The main evolutionary advantage of reflexes, mediated by the reflex arc, is:',
   array['Allowing very fast responses to potentially dangerous stimuli, without depending on slower processing by the brain', 'Making all of the body''s responses slower', 'Completely eliminating the need for the nervous system', 'Preventing any kind of voluntary movement'],
   'Fast reflexes increase the body''s chances of protecting itself from harmful stimuli.'),
  ('6580a5a5-5f94-4fc4-9196-80ee9f2261a6', 'es',
   'La principal ventaja evolutiva de los reflejos, mediados por el arco reflejo, es:',
   array['Permitir respuestas muy rápidas a estímulos potencialmente peligrosos, sin depender del procesamiento cerebral más lento', 'Hacer más lentas todas las respuestas del cuerpo', 'Eliminar por completo la necesidad del sistema nervioso', 'Impedir cualquier tipo de movimiento voluntario'],
   'Los reflejos rápidos aumentan las posibilidades de protección del organismo ante estímulos nocivos.'),
  ('7b212e73-9bde-4cb5-8128-cd044d31ae7f', 'en',
   'Although many reflexes are processed in the spinal cord, the brain usually:',
   array['Also receives the sensory information, allowing conscious perception of the stimulus, even after the reflex response', 'Never receives any information about reflexes', 'Completely prevents the reflex from happening', 'Is the only structure capable of processing any kind of reflex'],
   'Although the motor response happens via the spinal cord, the brain also receives the information, allowing conscious perception.'),
  ('7b212e73-9bde-4cb5-8128-cd044d31ae7f', 'es',
   'Aunque muchos reflejos se procesan en la médula espinal, el cerebro generalmente:',
   array['También recibe la información sensorial, lo que permite la percepción consciente del estímulo, incluso después de la respuesta refleja', 'Nunca recibe información sobre los reflejos', 'Impide por completo que ocurra el reflejo', 'Es la única estructura capaz de procesar cualquier tipo de reflejo'],
   'Aunque la respuesta motora ocurre a través de la médula, el cerebro también recibe la información, lo que permite la percepción consciente.'),
  ('015e8718-8885-49f8-9745-710c6d9a7066', 'en',
   'The neuron is the fundamental cell of the nervous system, specialized in:',
   array['Receiving, processing and transmitting nerve impulses', 'Producing hormones exclusively', 'Digesting nutrients', 'Contracting to generate muscle movement'],
   'Neurons conduct electrical and chemical signals that allow communication between parts of the body.'),
  ('015e8718-8885-49f8-9745-710c6d9a7066', 'es',
   'La neurona es la célula fundamental del sistema nervioso, especializada en:',
   array['Recibir, procesar y transmitir impulsos nerviosos', 'Producir hormonas exclusivamente', 'Digerir nutrientes', 'Contraerse para generar movimiento muscular'],
   'Las neuronas conducen señales eléctricas y químicas que permiten la comunicación entre las partes del organismo.'),
  ('d7c7d70d-e71a-4c3d-9496-20afa977f773', 'en',
   'The main structural parts of a neuron include:',
   array['The cell body (soma), dendrites and axon', 'Only nucleus and cytoplasm, with no additional structure', 'Exclusively mitochondria and ribosomes', 'Only the plasma membrane, with no internal organelles'],
   'The cell body contains the nucleus and organelles; dendrites receive stimuli; the axon conducts the nerve impulse.'),
  ('d7c7d70d-e71a-4c3d-9496-20afa977f773', 'es',
   'Las principales partes estructurales de una neurona incluyen:',
   array['El cuerpo celular (soma), las dendritas y el axón', 'Solo núcleo y citoplasma, sin ninguna estructura adicional', 'Exclusivamente mitocondrias y ribosomas', 'Solo la membrana plasmática, sin orgánulos internos'],
   'El cuerpo celular contiene el núcleo y los orgánulos; las dendritas reciben estímulos; el axón conduce el impulso nervioso.'),
  ('35ea58fc-b6a5-4af4-b5a1-3c0f517ff9d2', 'en',
   'The main function of the myelin sheath, found around many axons, is:',
   array['To speed up the conduction of the nerve impulse along the axon', 'To completely block the conduction of any nerve impulse', 'To produce neurotransmitters', 'To replace the function of the cell body'],
   'Myelin insulates the axon, allowing faster conduction through saltatory conduction.'),
  ('35ea58fc-b6a5-4af4-b5a1-3c0f517ff9d2', 'es',
   'La principal función de la vaina de mielina, presente alrededor de muchos axones, es:',
   array['Acelerar la conducción del impulso nervioso a lo largo del axón', 'Impedir por completo la conducción de cualquier impulso nervioso', 'Producir neurotransmisores', 'Sustituir la función del cuerpo celular'],
   'La mielina aísla el axón y permite una conducción más rápida, mediante la conducción saltatoria.'),
  ('70a926f1-37d4-419a-bc53-574f4ebb4685', 'en',
   'The main function of dendrites, branched structures found in neurons, is:',
   array['To receive stimuli from other neurons or from the environment', 'To conduct the nerve impulse over long distances', 'To produce cellular energy', 'To store the neuron''s genetic material'],
   'Dendrites pick up signals from other neurons or sensory receptors and pass them on to the cell body.'),
  ('70a926f1-37d4-419a-bc53-574f4ebb4685', 'es',
   'La principal función de las dendritas, estructuras ramificadas presentes en las neuronas, es:',
   array['Recibir estímulos de otras neuronas o del ambiente', 'Conducir el impulso nervioso a largas distancias', 'Producir energía celular', 'Almacenar el material genético de la neurona'],
   'Las dendritas captan señales de otras neuronas o de receptores sensoriales y las transmiten al cuerpo celular.'),
  ('e12cdd1e-ab20-44f3-b2e4-b9886f02ffcd', 'en',
   'Neurons communicate with each other, or with other cells (such as muscle cells), mainly through:',
   array['Synapses, involving the release of neurotransmitters', 'Direct physical contact between their nuclei', 'Complete fusion of their cell membranes', 'Direct exchanges of genetic material'],
   'Neural communication happens mainly at synapses, through the release of neurotransmitters.'),
  ('e12cdd1e-ab20-44f3-b2e4-b9886f02ffcd', 'es',
   'Las neuronas se comunican entre sí, o con otras células (como las musculares), principalmente mediante:',
   array['Sinapsis, que implican la liberación de neurotransmisores', 'Contacto físico directo entre sus núcleos', 'La fusión completa de sus membranas celulares', 'Intercambios directos de material genético'],
   'La comunicación neuronal ocurre principalmente en las sinapsis, con liberación de neurotransmisores.'),
  ('0798045e-6889-45ec-a171-2d651532b3b2', 'en',
   'The synapse is defined as:',
   array['The region of communication between a neuron and another cell (a neuron, muscle or gland)', 'The nucleus of the neuron', 'The myelin sheath around the axon', 'A cytoplasmic organelle found in the neuron'],
   'The synapse is the functional contact point where the nerve impulse is transmitted between cells.'),
  ('0798045e-6889-45ec-a171-2d651532b3b2', 'es',
   'La sinapsis se define como:',
   array['La región de comunicación entre una neurona y otra célula (neurona, músculo o glándula)', 'El núcleo de la neurona', 'La vaina de mielina que envuelve el axón', 'Un orgánulo citoplasmático presente en la neurona'],
   'La sinapsis es el punto de contacto funcional donde ocurre la transmisión del impulso nervioso entre células.'),
  ('65ad9f8b-e546-426e-b20e-a758cfb00bc4', 'en',
   'At chemical synapses, communication between neurons takes place mainly through the release of:',
   array['Neurotransmitters, chemical substances that cross the synaptic cleft', 'Direct electrical impulses, with no chemical substance', 'Hormones produced exclusively by the liver', 'Digestive enzymes'],
   'The presynaptic neuron releases neurotransmitters into the synaptic cleft, which bind to receptors on the next cell.'),
  ('65ad9f8b-e546-426e-b20e-a758cfb00bc4', 'es',
   'En las sinapsis químicas, la comunicación entre las neuronas ocurre principalmente mediante la liberación de:',
   array['Neurotransmisores, sustancias químicas que atraviesan la hendidura sináptica', 'Impulsos eléctricos directos, sin ninguna sustancia química', 'Hormonas producidas exclusivamente por el hígado', 'Enzimas digestivas'],
   'La neurona presináptica libera neurotransmisores en la hendidura sináptica, que se unen a receptores de la célula siguiente.'),
  ('e4434db3-6c92-4a8a-be82-c5a696cca23b', 'en',
   'The synaptic cleft is:',
   array['The small space between the membrane of the presynaptic neuron and that of the postsynaptic neuron', 'The nucleus of the neuron', 'The tip of the axon, with no separation between cells', 'A region inside the neuron''s own cell body'],
   'The synaptic cleft is the space where neurotransmitters are released and bind to receptors.'),
  ('e4434db3-6c92-4a8a-be82-c5a696cca23b', 'es',
   'La hendidura sináptica corresponde a:',
   array['El pequeño espacio entre la membrana de la neurona presináptica y la de la neurona postsináptica', 'El núcleo de la neurona', 'El extremo del axón, sin ninguna separación entre células', 'Una región dentro del propio cuerpo celular de la neurona'],
   'La hendidura sináptica es el espacio donde se liberan los neurotransmisores, que se unen a los receptores.'),
  ('70415fc9-3069-40bf-8326-bff8b5daecf1', 'en',
   'Acetylcholine is a well-known example of a:',
   array['Neurotransmitter, involved, among other functions, in muscle contraction', 'Hormone produced by the pancreas', 'Digestive enzyme', 'Structural protein of the cell membrane'],
   'Acetylcholine is an essential neurotransmitter at neuromuscular synapses, involved in muscle contraction.'),
  ('70415fc9-3069-40bf-8326-bff8b5daecf1', 'es',
   'La acetilcolina es un ejemplo muy conocido de:',
   array['Neurotransmisor, que participa, entre otras funciones, en la contracción muscular', 'Hormona producida por el páncreas', 'Enzima digestiva', 'Proteína estructural de la membrana celular'],
   'La acetilcolina es un neurotransmisor esencial en las sinapsis neuromusculares, que participa en la contracción muscular.'),
  ('21e8f36f-a41e-4413-99a9-bac6cc364191', 'en',
   'After acting on the postsynaptic cell, neurotransmitters are usually:',
   array['Removed from the synaptic cleft, by reuptake or enzymatic breakdown', 'Permanently accumulated in the synaptic cleft, with no removal', 'Turned directly into new nerve cells', 'Ignored by the postsynaptic cell, with no effect'],
   'Removing the neurotransmitters ends the signal and allows new transmissions afterward.'),
  ('21e8f36f-a41e-4413-99a9-bac6cc364191', 'es',
   'Después de actuar sobre la célula postsináptica, los neurotransmisores generalmente:',
   array['Se retiran de la hendidura sináptica, por recaptación o degradación enzimática', 'Se acumulan permanentemente en la hendidura sináptica, sin ninguna retirada', 'Se transforman directamente en nuevas células nerviosas', 'Son ignorados por la célula postsináptica, sin ningún efecto'],
   'La retirada de los neurotransmisores termina la señal y permite nuevas transmisiones posteriores.'),
  ('80ddfbec-6221-4f21-861d-c929b6512252', 'en',
   'The Central Nervous System (CNS) is made up of:',
   array['The brain and the spinal cord', 'Only the peripheral nerves', 'Exclusively the sense organs', 'Only the heart and the lungs'],
   'The CNS, made up of the brain (encephalon) and the spinal cord, is the processing center of the nervous system.'),
  ('80ddfbec-6221-4f21-861d-c929b6512252', 'es',
   'El Sistema Nervioso Central (SNC) está formado por:',
   array['El encéfalo y la médula espinal', 'Solo los nervios periféricos', 'Exclusivamente los órganos de los sentidos', 'Solo el corazón y los pulmones'],
   'El SNC, compuesto por el encéfalo y la médula espinal, es el centro de procesamiento del sistema nervioso.'),
  ('0e38b867-5d6b-4e46-80a6-77109e9b4df1', 'en',
   'The cerebrum, the main structure of the brain, is responsible, among other functions, for:',
   array['Complex cognitive processes, such as thinking, memory and language', 'Only producing blood cells', 'Digesting food', 'Filtering the blood, like the kidneys'],
   'The cerebrum coordinates higher functions, such as reasoning, memory, language and voluntary control of movement.'),
  ('0e38b867-5d6b-4e46-80a6-77109e9b4df1', 'es',
   'El cerebro, la principal estructura del encéfalo, es responsable, entre otras funciones, de:',
   array['Procesos cognitivos complejos, como el pensamiento, la memoria y el lenguaje', 'Solo la producción de células sanguíneas', 'La digestión de los alimentos', 'La filtración de la sangre, como los riñones'],
   'El cerebro coordina funciones superiores, como el razonamiento, la memoria, el lenguaje y el control voluntario de los movimientos.'),
  ('28cbc549-46ec-462e-a6a6-f79a70954d9c', 'en',
   'The main function of the cerebellum, another important structure of the brain, is:',
   array['To coordinate balance and the precision of body movements', 'To process only visual information', 'To produce sex hormones', 'To control the digestion of food directly'],
   'The cerebellum is essential for fine motor coordination, balance and posture.'),
  ('28cbc549-46ec-462e-a6a6-f79a70954d9c', 'es',
   'La principal función del cerebelo, otra estructura importante del encéfalo, es:',
   array['Coordinar el equilibrio y la precisión de los movimientos del cuerpo', 'Procesar exclusivamente información visual', 'Producir hormonas sexuales', 'Controlar directamente la digestión de los alimentos'],
   'El cerebelo es esencial para la coordinación motora fina, el equilibrio y la postura corporal.'),
  ('629f8fb7-114c-45e1-96a4-40aa961e790d', 'en',
   'The main functions of the spinal cord, protected by the spinal column, are:',
   array['Conducting nerve impulses between the brain and the rest of the body, as well as mediating simple reflexes', 'Producing only bone cells', 'Completely replacing the function of the brain', 'Digesting proteins'],
   'The spinal cord connects the brain to the body and directly coordinates certain reflexes.'),
  ('629f8fb7-114c-45e1-96a4-40aa961e790d', 'es',
   'Las principales funciones de la médula espinal, protegida por la columna vertebral, son:',
   array['Conducir impulsos nerviosos entre el encéfalo y el resto del cuerpo, además de mediar reflejos simples', 'Producir exclusivamente células óseas', 'Sustituir por completo la función del encéfalo', 'Digerir proteínas'],
   'La médula espinal conecta el encéfalo con el cuerpo y coordina directamente ciertos reflejos.'),
  ('c6adbd0b-106f-4fa0-be4d-540310e3d778', 'en',
   'The CNS is protected by specific bone structures, namely:',
   array['The skull (protecting the brain) and the spinal column (protecting the spinal cord)', 'Only the ribs', 'Exclusively the bones of the arms and legs', 'No bone structure protects the CNS'],
   'The skull and the spinal column form rigid bony protection for the structures of the CNS.'),
  ('c6adbd0b-106f-4fa0-be4d-540310e3d778', 'es',
   'El SNC está protegido por estructuras óseas específicas, que son:',
   array['El cráneo (que protege el encéfalo) y la columna vertebral (que protege la médula espinal)', 'Solo las costillas', 'Exclusivamente los huesos de los brazos y las piernas', 'Ninguna estructura ósea protege el SNC'],
   'El cráneo y la columna vertebral forman una protección ósea rígida para las estructuras del SNC.'),
  ('54210da4-116b-4515-b40b-c5b1fa126ab0', 'en',
   'The Peripheral Nervous System (PNS) is made up mainly of:',
   array['Nerves that connect the Central Nervous System to the other organs and tissues of the body', 'Only the brain', 'Exclusively the spinal cord', 'Only the sense organs, with no nerves'],
   'The PNS is made up of the cranial and spinal nerves, connecting the CNS to the rest of the body.'),
  ('54210da4-116b-4515-b40b-c5b1fa126ab0', 'es',
   'El Sistema Nervioso Periférico (SNP) está formado principalmente por:',
   array['Nervios que conectan el Sistema Nervioso Central con los demás órganos y tejidos del cuerpo', 'Solo el encéfalo', 'Exclusivamente la médula espinal', 'Solo los órganos de los sentidos, sin ningún nervio'],
   'El SNP está compuesto por los nervios craneales y espinales, que conectan el SNC con el resto del cuerpo.'),
  ('74a4675b-f846-4805-8ee4-a6954e6de693', 'en',
   'By function, the PNS can be divided into the somatic nervous system and the autonomic nervous system, with the somatic system mainly responsible for:',
   array['Controlling voluntary movements, related to the skeletal muscles', 'Controlling only involuntary functions, such as the heartbeat', 'Producing hormones', 'Digesting food'],
   'The somatic nervous system controls voluntary actions through the skeletal muscles.'),
  ('74a4675b-f846-4805-8ee4-a6954e6de693', 'es',
   'Según su función, el SNP puede dividirse en sistema nervioso somático y sistema nervioso autónomo; el somático es responsable principalmente de:',
   array['Controlar los movimientos voluntarios, relacionados con la musculatura esquelética', 'Controlar exclusivamente funciones involuntarias, como los latidos cardíacos', 'Producir hormonas', 'Digerir los alimentos'],
   'El sistema nervioso somático controla las acciones voluntarias a través de la musculatura esquelética.'),
  ('4899e949-e3a1-45ab-82d6-d6c127b9c46e', 'en',
   'The autonomic nervous system, in turn, is responsible for controlling:',
   array['Involuntary functions, such as the heartbeat, digestion and breathing', 'Exclusively voluntary movements', 'Only vision and hearing', 'No relevant function of the body'],
   'The autonomic nervous system regulates processes without conscious control, which are essential to homeostasis.'),
  ('4899e949-e3a1-45ab-82d6-d6c127b9c46e', 'es',
   'El sistema nervioso autónomo, por su parte, se encarga de controlar:',
   array['Funciones involuntarias, como los latidos cardíacos, la digestión y la respiración', 'Exclusivamente los movimientos voluntarios', 'Solo la visión y la audición', 'Ninguna función relevante del organismo'],
   'El sistema nervioso autónomo regula procesos sin control consciente, esenciales para la homeostasis.'),
  ('d5c5909a-d31e-4e55-96d5-d4b5dd5c505a', 'en',
   'The autonomic nervous system is subdivided into the sympathetic and parasympathetic systems, with the sympathetic system usually responsible for:',
   array['Preparing the body for stressful or emergency situations ("fight or flight")', 'Promoting only relaxation and digestion', 'Controlling only the voluntary movements of the arms', 'Producing sex hormones'],
   'The sympathetic system triggers alert responses, such as a faster heart rate, in stressful situations.'),
  ('d5c5909a-d31e-4e55-96d5-d4b5dd5c505a', 'es',
   'El sistema nervioso autónomo se subdivide en sistema simpático y parasimpático; el simpático suele ser responsable de:',
   array['Preparar el cuerpo para situaciones de estrés o emergencia ("lucha o huida")', 'Promover exclusivamente la relajación y la digestión', 'Controlar solo los movimientos voluntarios de los brazos', 'Producir hormonas sexuales'],
   'El sistema simpático activa respuestas de alerta, como el aumento de la frecuencia cardíaca, en situaciones de estrés.'),
  ('ecf2a203-af35-4ccf-b509-936d1492f871', 'en',
   'In contrast with the sympathetic system, the parasympathetic system is usually associated with:',
   array['Relaxation and energy conservation functions, such as digestion', 'Exclusively "fight or flight" responses', 'A constant increase in heart rate', 'No relevant function of the body'],
   'The parasympathetic system promotes states of rest and recovery, favoring digestion.'),
  ('ecf2a203-af35-4ccf-b509-936d1492f871', 'es',
   'A diferencia del simpático, el sistema parasimpático suele estar asociado a:',
   array['Funciones de relajación y conservación de energía, como la digestión', 'Respuestas exclusivas de "lucha o huida"', 'El aumento constante de la frecuencia cardíaca', 'Ninguna función relevante del organismo'],
   'El sistema parasimpático promueve estados de reposo y recuperación y favorece la digestión.'),
  ('59bff707-e6ce-4c00-8ce8-684db4cab6f5', 'en',
   'A food chain represents:',
   array['The linear sequence of energy transfer between organisms, from one trophic level to another', 'A complex network of multiple feeding interactions', 'Only the relationship between predators, with no producers', 'The geographic distribution of a species'],
   'A food chain shows, in a linear way, who eats whom, representing the flow of energy between organisms.'),
  ('59bff707-e6ce-4c00-8ce8-684db4cab6f5', 'es',
   'Una cadena alimentaria representa:',
   array['La secuencia lineal de transferencia de energía entre organismos, de un nivel trófico a otro', 'Una red compleja de múltiples interacciones alimentarias', 'Solo la relación entre depredadores, sin productores', 'La distribución geográfica de una especie'],
   'La cadena alimentaria muestra, de forma lineal, quién come a quién, y representa el flujo de energía entre los organismos.'),
  ('6cf47670-80b0-4c6e-be9c-94a9cdb9171f', 'en',
   'The first link in a food chain is usually occupied by:',
   array['Producers, such as plants and algae, which can carry out photosynthesis', 'Primary consumers, such as herbivores', 'Decomposers', 'Top predators'],
   'Producers, autotrophs that can capture solar energy, form the base of every food chain.'),
  ('6cf47670-80b0-4c6e-be9c-94a9cdb9171f', 'es',
   'El primer eslabón de una cadena alimentaria suele estar ocupado por:',
   array['Productores, como plantas y algas, capaces de realizar la fotosíntesis', 'Consumidores primarios, como los herbívoros', 'Descomponedores', 'Depredadores tope'],
   'Los productores, autótrofos capaces de captar energía solar, forman la base de toda cadena alimentaria.'),
  ('64dc97b3-c7f5-4b9d-997e-caf7e117bd5d', 'en',
   'In a food chain, primary consumers are usually represented by:',
   array['Herbivores, which feed directly on producers', 'Carnivores that feed on other carnivores', 'Decomposers', 'Photosynthetic organisms'],
   'Primary consumers occupy the second link of the chain, feeding directly on the producers.'),
  ('64dc97b3-c7f5-4b9d-997e-caf7e117bd5d', 'es',
   'En una cadena alimentaria, los consumidores primarios suelen estar representados por:',
   array['Herbívoros, que se alimentan directamente de los productores', 'Carnívoros que se alimentan de otros carnívoros', 'Descomponedores', 'Organismos fotosintéticos'],
   'Los consumidores primarios ocupan el segundo eslabón de la cadena y se alimentan directamente de los productores.'),
  ('480d0d31-aba1-46bc-a0e7-59aec7d6e30e', 'en',
   'In a food chain, energy generally flows:',
   array['From producers to consumers, with progressive energy loss at each level', 'From consumers to producers', 'In a cycle and with no loss, between all levels', 'Only between decomposers'],
   'Energy flows in one direction along the chain, with energy lost (as heat) at each transfer.'),
  ('480d0d31-aba1-46bc-a0e7-59aec7d6e30e', 'es',
   'En una cadena alimentaria, la energía fluye, en general:',
   array['De los productores a los consumidores, con pérdida progresiva de energía en cada nivel', 'De los consumidores a los productores', 'De forma cíclica y sin ninguna pérdida, entre todos los niveles', 'Solo entre descomponedores'],
   'La energía fluye en una sola dirección a lo largo de la cadena, con pérdida de energía (calor) en cada transferencia.'),
  ('0e91bf38-d9c5-4f80-86eb-a2e3fbd7c236', 'en',
   'Decomposers, found at the end of a food chain, play a key role by:',
   array['Breaking down dead organic matter, returning nutrients to the environment', 'Carrying out photosynthesis, producing energy', 'Always occupying the first link of the chain', 'Preventing nutrient recycling in the ecosystem'],
   'Decomposing fungi and bacteria break down organic remains, releasing nutrients that producers can reuse.'),
  ('0e91bf38-d9c5-4f80-86eb-a2e3fbd7c236', 'es',
   'Los descomponedores, presentes al final de una cadena alimentaria, cumplen un papel fundamental al:',
   array['Descomponer la materia orgánica muerta y devolver nutrientes al ambiente', 'Realizar la fotosíntesis y producir energía', 'Ocupar siempre el primer eslabón de la cadena', 'Impedir el reciclaje de nutrientes en el ecosistema'],
   'Los hongos y las bacterias descomponedoras degradan los restos orgánicos y liberan nutrientes que los productores reaprovechan.'),
  ('bc343445-cbf0-4656-b504-dec956fde145', 'en',
   'An organism''s trophic level indicates:',
   array['Its position in the food chain, according to its source of energy', 'Its geographic location', 'Its body size', 'Its reproductive capacity'],
   'The trophic level classifies organisms according to their position in the food chain.'),
  ('bc343445-cbf0-4656-b504-dec956fde145', 'es',
   'El nivel trófico de un organismo indica:',
   array['Su posición en la cadena alimentaria, según su fuente de energía', 'Su ubicación geográfica', 'Su tamaño corporal', 'Su capacidad reproductiva'],
   'El nivel trófico clasifica a los organismos según su posición en la cadena alimentaria.'),
  ('8f734c83-4138-4597-91b4-bdc0de4719e3', 'en',
   'Producers occupy the:',
   array['First trophic level of a food chain', 'Last trophic level', 'An intermediate level, between primary and secondary consumers', 'No specific trophic level'],
   'Because they capture energy directly from the Sun, producers form the base of the chain, at the first trophic level.'),
  ('8f734c83-4138-4597-91b4-bdc0de4719e3', 'es',
   'Los productores ocupan el:',
   array['Primer nivel trófico de una cadena alimentaria', 'Último nivel trófico', 'Nivel intermedio, entre los consumidores primarios y secundarios', 'Ningún nivel trófico específico'],
   'Como captan energía directamente del Sol, los productores forman la base de la cadena, en el primer nivel trófico.'),
  ('caeb548d-327f-4713-866a-f4f5a075d1aa', 'en',
   'In a food chain, secondary consumers usually feed on:',
   array['Primary consumers (herbivores)', 'Producers directly', 'Only other secondary consumers', 'Exclusively decomposers'],
   'Secondary consumers (usually carnivores) occupy the third trophic level, feeding on herbivores.'),
  ('caeb548d-327f-4713-866a-f4f5a075d1aa', 'es',
   'En una cadena alimentaria, los consumidores secundarios suelen alimentarse de:',
   array['Consumidores primarios (herbívoros)', 'Productores directamente', 'Solo otros consumidores secundarios', 'Exclusivamente descomponedores'],
   'Los consumidores secundarios (generalmente carnívoros) ocupan el tercer nivel trófico y se alimentan de los herbívoros.'),
  ('d4bc32b1-6494-4456-ae56-6acc25358f9d', 'en',
   'At each transition between trophic levels, approximately how much energy is usually lost as heat?',
   array['90% of the energy available at the previous level', 'None; all the energy is transferred in full', 'Only 1% of the energy', 'Exactly 50% of the energy, at any transition'],
   'By the 10% rule, only about 10% of the energy is passed on to the next level, and the rest is lost as heat.'),
  ('d4bc32b1-6494-4456-ae56-6acc25358f9d', 'es',
   'En cada transición entre niveles tróficos, ¿qué cantidad de energía se pierde aproximadamente en forma de calor?',
   array['El 90% de la energía disponible en el nivel anterior', 'Ninguna; toda la energía se transfiere íntegramente', 'Solo el 1% de la energía', 'Exactamente el 50% de la energía, en cualquier transición'],
   'Según la regla del 10%, solo alrededor del 10% de la energía se transfiere al nivel siguiente, y el resto se pierde como calor.'),
  ('fe22753b-61f3-4619-81a1-046c537842e2', 'en',
   'Because of the large energy loss between trophic levels, very long food chains, with many levels, tend to be:',
   array['Relatively rare, since the available energy falls drastically at each level', 'Extremely common, with no energy limitation', 'Always more stable than short chains', 'Impossible in nature'],
   'The progressive loss of energy limits the number of trophic levels a chain can support.'),
  ('fe22753b-61f3-4619-81a1-046c537842e2', 'es',
   'Debido a la gran pérdida de energía entre los niveles tróficos, las cadenas alimentarias muy largas, con muchos niveles, tienden a ser:',
   array['Relativamente raras, ya que la energía disponible disminuye drásticamente en cada nivel', 'Extremadamente comunes, sin ninguna limitación energética', 'Siempre más estables que las cadenas cortas', 'Imposibles en la naturaleza'],
   'La pérdida progresiva de energía limita el número de niveles tróficos que puede sostener una cadena.'),
  ('acaf64b2-47e8-4c55-a129-450b95921a74', 'en',
   'Ecological pyramids are graphic representations used to illustrate:',
   array['The distribution of energy, biomass or number of individuals among the trophic levels of an ecosystem', 'Only the geographic location of species', 'The genetic structure of a population', 'The life cycle of a single organism'],
   'Ecological pyramids show visually how energy, biomass or number of organisms is distributed among trophic levels.'),
  ('acaf64b2-47e8-4c55-a129-450b95921a74', 'es',
   'Las pirámides ecológicas son representaciones gráficas usadas para ilustrar:',
   array['La distribución de energía, biomasa o número de individuos entre los niveles tróficos de un ecosistema', 'Solo la ubicación geográfica de las especies', 'La estructura genética de una población', 'El ciclo de vida de un único organismo'],
   'Las pirámides ecológicas representan visualmente cómo se distribuyen la energía, la biomasa o el número de organismos entre los niveles tróficos.'),
  ('a5cfa677-3bd4-44db-98eb-c8db830d0b82', 'en',
   'In an energy pyramid, the base (producers) always has:',
   array['The largest amount of available energy, compared with the upper levels', 'The smallest amount of energy in the whole ecosystem', 'The same amount of energy as the other levels', 'No relationship with the amount of energy at the other levels'],
   'Since energy is lost at each transfer, the base of the energy pyramid always holds the largest amount.'),
  ('a5cfa677-3bd4-44db-98eb-c8db830d0b82', 'es',
   'En una pirámide de energía, la base (productores) siempre tiene:',
   array['La mayor cantidad de energía disponible, en comparación con los niveles superiores', 'La menor cantidad de energía de todo el ecosistema', 'La misma cantidad de energía que los demás niveles', 'Ninguna relación con la cantidad de energía de los otros niveles'],
   'Como hay pérdida de energía en cada transferencia, la base de la pirámide de energía siempre concentra la mayor cantidad.'),
  ('d5f78498-586f-421a-8100-385a6fe28c81', 'en',
   'Unlike the energy pyramid, the pyramid of numbers can, in certain ecosystems, be inverted, as happens when:',
   array['A single producer (such as a large tree) supports a large number of small primary consumers', 'The amount of available energy is always the same at every level', 'There are no producers in the ecosystem', 'All organisms are exactly the same size'],
   'In some cases, there can be more individuals among the consumers than among the producers, inverting the pyramid.'),
  ('d5f78498-586f-421a-8100-385a6fe28c81', 'es',
   'A diferencia de la pirámide de energía, la pirámide de números puede, en ciertos ecosistemas, estar invertida, como ocurre cuando:',
   array['Un único productor (como un árbol grande) sostiene a una gran cantidad de consumidores primarios pequeños', 'La cantidad de energía disponible es siempre igual en todos los niveles', 'No hay productores en el ecosistema', 'Todos los organismos tienen exactamente el mismo tamaño'],
   'En ciertos casos, el número de individuos puede ser mayor entre los consumidores que entre los productores, lo que invierte la pirámide.'),
  ('5ee8c956-8d98-4488-8104-effeae80d98b', 'en',
   'The biomass pyramid represents the total amount of:',
   array['Living organic matter at each trophic level', 'Light energy received from the Sun', 'Different species in the ecosystem', 'Water available in the environment'],
   'The biomass pyramid measures the total mass of living organisms at each trophic level of an ecosystem.'),
  ('5ee8c956-8d98-4488-8104-effeae80d98b', 'es',
   'La pirámide de biomasa representa la cantidad total de:',
   array['Materia orgánica viva presente en cada nivel trófico', 'Energía luminosa recibida del Sol', 'Especies diferentes presentes en el ecosistema', 'Agua disponible en el ambiente'],
   'La pirámide de biomasa mide la masa total de organismos vivos en cada nivel trófico de un ecosistema.'),
  ('b554b56a-a1aa-4f6d-a373-906898d47b2c', 'en',
   'Of the three main types of ecological pyramids (energy, biomass and numbers), the energy pyramid is considered the most reliable for representing how the ecosystem works because:',
   array['It is never inverted, faithfully reflecting the energy loss between levels', 'It is the only one that can be inverted, unlike the others', 'It does not depend on the number of organisms present', 'It measures only the number of species, not energy'],
   'Since it directly reflects the unavoidable loss of energy, the energy pyramid always keeps the standard pyramid shape.'),
  ('b554b56a-a1aa-4f6d-a373-906898d47b2c', 'es',
   'Entre los tres tipos principales de pirámides ecológicas (energía, biomasa y números), la pirámide de energía se considera la más fiable para representar el funcionamiento del ecosistema porque:',
   array['Nunca está invertida, lo que refleja fielmente la pérdida energética entre los niveles', 'Es la única que puede invertirse, a diferencia de las demás', 'No depende de la cantidad de organismos presentes', 'Mide exclusivamente el número de especies, y no la energía'],
   'Como refleja directamente la pérdida inevitable de energía, la pirámide de energía mantiene siempre la forma piramidal estándar.'),
  ('6a950e62-06b5-478d-bee1-2d4584ea8f9e', 'en',
   'A food web represents:',
   array['The interconnection of multiple food chains in an ecosystem, forming a complex network of relationships', 'A single isolated, linear sequence of organisms', 'Only the relationship between two organisms', 'The distribution of species across different continents'],
   'The food web reflects the real complexity of ecosystems, with multiple feeding relationships between species.'),
  ('6a950e62-06b5-478d-bee1-2d4584ea8f9e', 'es',
   'Una red trófica representa:',
   array['La interconexión de múltiples cadenas alimentarias en un ecosistema, que forma una red compleja de relaciones', 'Una única secuencia lineal y aislada de organismos', 'Solo la relación entre dos organismos', 'La distribución de las especies en diferentes continentes'],
   'La red trófica refleja la complejidad real de los ecosistemas, con múltiples relaciones alimentarias entre especies.'),
  ('f4d71da3-5032-4d1a-ab40-025169b87f23', 'en',
   'Compared with an isolated food chain, a food web represents more realistically:',
   array['The diversity and complexity of feeding relationships in an ecosystem', 'An exaggerated simplification of ecological relationships', 'Only relationships between plants', 'A complete absence of interactions between species'],
   'The food web better captures ecological reality, with organisms taking part in multiple relationships.'),
  ('f4d71da3-5032-4d1a-ab40-025169b87f23', 'es',
   'En comparación con una cadena alimentaria aislada, la red trófica representa de forma más realista:',
   array['La diversidad y la complejidad de las relaciones alimentarias en un ecosistema', 'Una simplificación exagerada de las relaciones ecológicas', 'Solo relaciones entre plantas', 'La ausencia total de interacciones entre especies'],
   'La red trófica capta mejor la realidad ecológica, con organismos que participan en múltiples relaciones.'),
  ('f95a7a83-10a3-42ee-95b1-79ecfb239d85', 'en',
   'Removing a keystone species from a food web can cause:',
   array['A significant imbalance in the whole ecosystem, affecting several other species', 'No relevant impact on the other species', 'An immediate strengthening of all the other populations', 'The automatic creation of new species to replace it'],
   'Keystone species play fundamental roles in the food web; removing them can destabilize the ecosystem.'),
  ('f95a7a83-10a3-42ee-95b1-79ecfb239d85', 'es',
   'La eliminación de una especie clave de una red trófica puede causar:',
   array['Un desequilibrio significativo en todo el ecosistema, que afecta a varias otras especies', 'Ningún impacto relevante en las demás especies', 'Un fortalecimiento inmediato de todas las demás poblaciones', 'La creación automática de nuevas especies para sustituirla'],
   'Las especies clave cumplen papeles fundamentales en la red trófica; su eliminación puede desestabilizar el ecosistema.'),
  ('53229dab-70cb-4c80-a98a-3c6800bf929e', 'en',
   'Greater complexity in a food web, with multiple connections between species, is usually associated with:',
   array['Greater ecosystem stability and resilience', 'Greater ecosystem fragility and instability', 'No relationship with ecological stability', 'A necessary reduction in biodiversity'],
   'Ecosystems with more complex webs tend to be more resilient, with alternative routes for energy flow.'),
  ('53229dab-70cb-4c80-a98a-3c6800bf929e', 'es',
   'Una mayor complejidad de la red trófica, con múltiples conexiones entre especies, suele estar asociada a:',
   array['Una mayor estabilidad y resiliencia del ecosistema', 'Una mayor fragilidad e inestabilidad del ecosistema', 'Ninguna relación con la estabilidad ecológica', 'Una reducción obligatoria de la biodiversidad'],
   'Los ecosistemas con redes más complejas tienden a ser más resilientes, con rutas alternativas de flujo de energía.'),
  ('73dce994-d8a9-4842-a37b-0425905a4aa1', 'en',
   'Within a food web, the same organism can occupy:',
   array['Different trophic levels, depending on its diet at different times or in different situations', 'Only a single fixed trophic level, with no exception', 'No defined trophic level', 'Always the producer level, regardless of what it eats'],
   'Omnivores, for example, can act as both primary and secondary consumers, changing their trophic level.'),
  ('73dce994-d8a9-4842-a37b-0425905a4aa1', 'es',
   'Dentro de una red trófica, un mismo organismo puede ocupar:',
   array['Diferentes niveles tróficos, según su dieta en distintos momentos o situaciones', 'Solo un único nivel trófico fijo, sin ninguna excepción', 'Ningún nivel trófico definido', 'Siempre el nivel de productor, independientemente de su alimentación'],
   'Los omnívoros, por ejemplo, pueden actuar como consumidores primarios y secundarios, variando su nivel trófico.'),
  ('d38a1c22-e7d6-4e42-931f-50f013926ce6', 'en',
   'Global warming is a phenomenon related mainly to the rising atmospheric concentration of:',
   array['Greenhouse gases, such as carbon dioxide (CO₂) and methane (CH₄)', 'Noble gases, such as helium and neon', 'Water vapor only, with no other gas', 'Pure molecular nitrogen (N₂)'],
   'The buildup of greenhouse gases traps more heat in the atmosphere, contributing to global warming.'),
  ('d38a1c22-e7d6-4e42-931f-50f013926ce6', 'es',
   'El calentamiento global es un fenómeno relacionado principalmente con el aumento de la concentración atmosférica de:',
   array['Gases de efecto invernadero, como el dióxido de carbono (CO₂) y el metano (CH₄)', 'Gases nobles, como el helio y el neón', 'Solo vapor de agua, sin ningún otro gas', 'Nitrógeno molecular (N₂) puro'],
   'La acumulación de gases de efecto invernadero retiene más calor en la atmósfera y contribuye al calentamiento global.'),
  ('1f33fa5d-76d3-4de9-bcca-9ac60c3612e6', 'en',
   'Among the main human activities associated with worsening global warming is:',
   array['Burning fossil fuels, such as oil and coal', 'Producing solar energy exclusively', 'Planting forests extensively', 'Reducing the use of motor vehicles'],
   'Burning fossil fuels releases large amounts of CO₂, one of the main human-caused factors.'),
  ('1f33fa5d-76d3-4de9-bcca-9ac60c3612e6', 'es',
   'Entre las principales actividades humanas asociadas al agravamiento del calentamiento global se destaca:',
   array['La quema de combustibles fósiles, como el petróleo y el carbón', 'La producción exclusiva de energía solar', 'La plantación extensiva de bosques', 'La reducción del uso de vehículos a motor'],
   'La quema de combustibles fósiles libera grandes cantidades de CO₂, una de las principales causas antrópicas.'),
  ('8cf48546-9219-4e14-afbe-33c4396ea39e', 'en',
   'Among the consequences associated with global warming are:',
   array['The melting of glaciers and rising sea levels', 'A constant decrease in the planet''s average temperature', 'A growing polar ice cap, with no change', 'The complete elimination of extreme weather events'],
   'The rise in average temperature contributes to the melting of glaciers, raising sea levels.'),
  ('8cf48546-9219-4e14-afbe-33c4396ea39e', 'es',
   'Entre las consecuencias asociadas al calentamiento global se encuentran:',
   array['El derretimiento de los glaciares y el aumento del nivel de los océanos', 'La disminución constante de la temperatura media del planeta', 'El aumento de la capa de hielo polar, sin ningún cambio', 'La eliminación completa de los eventos climáticos extremos'],
   'El aumento de la temperatura media contribuye al derretimiento de los glaciares, lo que eleva el nivel de los océanos.'),
  ('533dd74a-5b5d-4632-b123-15bf93a9f704', 'en',
   'Deforestation worsens global warming mainly because it:',
   array['Reduces the number of trees that can absorb CO₂ from the atmosphere through photosynthesis', 'Directly increases the production of atmospheric oxygen', 'Has nothing to do with the concentration of greenhouse gases', 'Lowers the planet''s average temperature'],
   'Trees absorb CO₂ during photosynthesis; removing them reduces this capture capacity, worsening the greenhouse effect.'),
  ('533dd74a-5b5d-4632-b123-15bf93a9f704', 'es',
   'La deforestación contribuye al agravamiento del calentamiento global principalmente porque:',
   array['Reduce la cantidad de árboles capaces de absorber CO₂ de la atmósfera mediante la fotosíntesis', 'Aumenta directamente la producción de oxígeno atmosférico', 'No tiene ninguna relación con la concentración de gases de efecto invernadero', 'Reduce la temperatura media del planeta'],
   'Los árboles absorben CO₂ durante la fotosíntesis; al eliminarlos se reduce esa capacidad de captura y se agrava el efecto invernadero.'),
  ('d4263b52-ca42-4116-b5e4-9aa879af1770', 'en',
   'The main goal of international agreements such as the Paris Agreement is:',
   array['To reduce global greenhouse gas emissions, limiting the rise in the planet''s average temperature', 'To freely increase the emission of air pollutants', 'To completely eliminate the use of any energy source', 'To encourage only controlled deforestation'],
   'Agreements such as the Paris Agreement seek to set emission reduction targets to curb global warming.'),
  ('d4263b52-ca42-4116-b5e4-9aa879af1770', 'es',
   'El principal objetivo de acuerdos internacionales como el Acuerdo de París es:',
   array['Reducir las emisiones globales de gases de efecto invernadero, limitando el aumento de la temperatura media del planeta', 'Aumentar libremente la emisión de contaminantes atmosféricos', 'Eliminar por completo el uso de cualquier fuente de energía', 'Incentivar exclusivamente la deforestación controlada'],
   'Acuerdos como el de París buscan establecer metas de reducción de emisiones para frenar el calentamiento global.'),
  ('65ffb381-91a1-4366-babb-4ca901b8e99d', 'en',
   'Acid rain is caused mainly by the atmospheric emission of:',
   array['Sulfur and nitrogen oxides, from burning fossil fuels', 'Pure water vapor', 'Excess oxygen gas', 'Noble gases emitted by industries'],
   'Sulfur and nitrogen oxides react with atmospheric water, forming acids that fall as acid rain.'),
  ('65ffb381-91a1-4366-babb-4ca901b8e99d', 'es',
   'La lluvia ácida es causada principalmente por la emisión a la atmósfera de:',
   array['Óxidos de azufre y nitrógeno, provenientes de la quema de combustibles fósiles', 'Vapor de agua puro', 'Gas oxígeno en exceso', 'Gases nobles emitidos por las industrias'],
   'Los óxidos de azufre y nitrógeno reaccionan con el agua atmosférica y forman ácidos que caen en forma de lluvia ácida.'),
  ('94a0caaf-ddb9-424e-8a3b-7de6fbc07162', 'en',
   'Acid rain can cause significant damage, among other effects, to:',
   array['Forests, bodies of water and buildings made of limestone or marble', 'Only deep-sea marine organisms', 'No structure or ecosystem at all', 'Exclusively desert regions with no vegetation'],
   'The acidification caused by acid rain can harm forests, acidify rivers and corrode certain buildings.'),
  ('94a0caaf-ddb9-424e-8a3b-7de6fbc07162', 'es',
   'La lluvia ácida puede causar daños significativos, entre otros efectos, a:',
   array['Bosques, cuerpos de agua y construcciones de piedra caliza o mármol', 'Solo a organismos marinos de aguas profundas', 'Ningún tipo de estructura o ecosistema', 'Exclusivamente a regiones desérticas, sin ninguna vegetación'],
   'La acidificación causada por la lluvia ácida puede perjudicar bosques, acidificar ríos y corroer ciertas construcciones.'),
  ('b6413827-b5f8-4dcd-b8e1-9e13a79c0a7d', 'en',
   'In lakes and rivers affected by acid rain, acidification of the water can cause:',
   array['The death of fish and other aquatic organisms sensitive to changes in pH', 'An immediate increase in aquatic biodiversity', 'No relevant impact on aquatic life', 'The automatic neutralization of any pollutant in the water'],
   'Many aquatic organisms are sensitive to changes in water pH and suffer serious consequences.'),
  ('b6413827-b5f8-4dcd-b8e1-9e13a79c0a7d', 'es',
   'En los lagos y ríos afectados por la lluvia ácida, la acidificación del agua puede causar:',
   array['La muerte de peces y otros organismos acuáticos sensibles a la variación del pH', 'Un aumento inmediato de la biodiversidad acuática', 'Ningún impacto relevante en la vida acuática', 'La neutralización automática de cualquier contaminante presente en el agua'],
   'Muchos organismos acuáticos son sensibles a las variaciones del pH del agua y sufren consecuencias graves.'),
  ('d1aa83cc-fc7f-4ffc-9bf3-ef1d11ef60e7', 'en',
   'Installing filters and emission control technologies in industries and vehicles is an important measure to:',
   array['Reduce the release of sulfur and nitrogen oxides into the atmosphere', 'Deliberately increase the formation of acid rain', 'Completely eliminate the need for energy', 'Prevent any form of water pollution'],
   'Emission control technologies reduce the amount of polluting oxides released into the atmosphere.'),
  ('d1aa83cc-fc7f-4ffc-9bf3-ef1d11ef60e7', 'es',
   'La instalación de filtros y tecnologías de control de emisiones en industrias y vehículos es una medida importante para:',
   array['Reducir la liberación de óxidos de azufre y nitrógeno a la atmósfera', 'Aumentar a propósito la formación de lluvia ácida', 'Eliminar por completo la necesidad de energía', 'Impedir cualquier forma de contaminación del agua'],
   'Las tecnologías de control de emisiones reducen la cantidad de óxidos contaminantes liberados a la atmósfera.'),
  ('a956987d-cde3-4c5e-9f75-7edd81434248', 'en',
   'Acid rain is a clear example of how air pollution can have effects that extend:',
   array['Beyond the original source of emission, affecting distant regions through atmospheric transport', 'Only to the exact place where the pollutant was emitted', 'Only to the aquatic environment, with no relation to the soil', 'Only at night, with no effect during the day'],
   'Pollutants emitted in one region can be carried by the wind, causing acid rain in distant areas.'),
  ('a956987d-cde3-4c5e-9f75-7edd81434248', 'es',
   'La lluvia ácida es un ejemplo claro de cómo la contaminación atmosférica puede tener efectos que se extienden:',
   array['Más allá de la fuente original de emisión, afectando regiones lejanas mediante el transporte atmosférico', 'Exclusivamente al lugar exacto donde se emitió el contaminante', 'Solo al ambiente acuático, sin ninguna relación con el suelo', 'Solo durante la noche, sin ningún efecto diurno'],
   'Los contaminantes emitidos en una región pueden ser transportados por el viento y causar lluvia ácida en zonas lejanas.'),
  ('5cf104ee-5080-4a65-98c9-93b6da8627f2', 'en',
   'Deforestation is defined as:',
   array['The total or partial removal of the forest cover of a given area', 'The intensive planting of new trees in a region', 'The legal protection of forest areas', 'The natural growth of forests over time'],
   'Deforestation involves removing forest vegetation, usually for farming, ranching or urban use.'),
  ('5cf104ee-5080-4a65-98c9-93b6da8627f2', 'es',
   'La deforestación se define como:',
   array['La eliminación total o parcial de la cobertura forestal de un área determinada', 'La plantación intensiva de nuevos árboles en una región', 'La protección legal de áreas forestales', 'El crecimiento natural de los bosques con el tiempo'],
   'La deforestación implica la eliminación de la vegetación forestal, generalmente para uso agrícola, ganadero o urbano.'),
  ('c9bb4234-085f-4d00-a780-3aace3903ed6', 'en',
   'Among the main causes of deforestation, especially in tropical regions such as the Amazon, are:',
   array['The expansion of farming and ranching, and illegal logging', 'The spontaneous, natural growth of forests', 'A complete absence of human activity in the region', 'The strict, effective protection of all forest areas'],
   'Converting forest areas into pastures and crops, as well as logging, cause deforestation.'),
  ('c9bb4234-085f-4d00-a780-3aace3903ed6', 'es',
   'Entre las principales causas de la deforestación, sobre todo en regiones tropicales como la Amazonia, se destacan:',
   array['La expansión agropecuaria y la tala ilegal', 'El crecimiento espontáneo y natural de los bosques', 'La ausencia total de actividades humanas en la región', 'La protección rigurosa y efectiva de todas las áreas forestales'],
   'La conversión de áreas forestales en pastizales y cultivos, además de la tala, causa la deforestación.'),
  ('90b066cd-8e3a-4106-b453-574bc140cc7a', 'en',
   'Deforestation can contribute directly to:',
   array['The loss of biodiversity and the extinction of species that depend on that habitat', 'An immediate increase in local biodiversity', 'An improvement in soil quality, with no negative effect', 'A reduction in the risk of soil erosion'],
   'Destroying the natural habitat of many species is one of the main threats to biodiversity.'),
  ('90b066cd-8e3a-4106-b453-574bc140cc7a', 'es',
   'La deforestación puede contribuir directamente a:',
   array['La pérdida de biodiversidad y la extinción de especies que dependen de ese hábitat', 'El aumento inmediato de la biodiversidad local', 'La mejora de la calidad del suelo, sin ningún efecto negativo', 'La reducción del riesgo de erosión del suelo'],
   'La destrucción del hábitat natural de diversas especies es una de las principales amenazas a la biodiversidad.'),
  ('4c48063d-fbb0-4361-a56f-04d555e01592', 'en',
   'Besides the loss of biodiversity, deforestation is also associated with:',
   array['Changes in rainfall patterns and the regional water cycle', 'An immediate, permanent increase in soil moisture', 'No change in the local or regional climate', 'The complete elimination of the risk of fires'],
   'Removing forest cover can change evaporation and precipitation patterns, affecting the water cycle.'),
  ('4c48063d-fbb0-4361-a56f-04d555e01592', 'es',
   'Además de la pérdida de biodiversidad, la deforestación también está asociada a:',
   array['Cambios en el régimen de lluvias y en el ciclo hidrológico regional', 'Un aumento inmediato y permanente de la humedad del suelo', 'Ningún cambio en el clima local o regional', 'La eliminación total del riesgo de incendios'],
   'La eliminación de la cobertura forestal puede alterar los patrones de evaporación y precipitación y afectar el ciclo hidrológico.'),
  ('8cadff25-adae-4afc-8792-6d92c61e7ead', 'en',
   'Sustainable forest management mainly seeks to:',
   array['Reconcile the economic use of forest resources with their long-term conservation', 'Maximize deforestation in the short term, with no planning', 'Completely eliminate any economic activity related to forests', 'Completely ignore the environmental impacts of forestry'],
   'Sustainable management aims to allow the use of forest resources while ensuring their conservation over time.'),
  ('8cadff25-adae-4afc-8792-6d92c61e7ead', 'es',
   'El manejo forestal sostenible busca principalmente:',
   array['Conciliar el uso económico de los recursos forestales con su conservación a largo plazo', 'Maximizar la deforestación a corto plazo, sin ninguna planificación', 'Eliminar por completo cualquier actividad económica relacionada con los bosques', 'Ignorar por completo los impactos ambientales de la explotación forestal'],
   'El manejo sostenible busca permitir el uso de los recursos forestales garantizando su conservación a lo largo del tiempo.'),
  ('5046cd2c-c997-4895-8ae0-21d8c202cf2e', 'en',
   'An invasive species is characterized by:',
   array['Being introduced (usually by humans) into an environment different from its original habitat, causing negative impacts', 'Always being native to the ecosystem where it is found', 'Never causing any impact on the local ecosystem', 'Being exclusively an extinct species'],
   'Invasive species are introduced into new environments, often by human activity, causing imbalances.'),
  ('5046cd2c-c997-4895-8ae0-21d8c202cf2e', 'es',
   'Una especie invasora se caracteriza por:',
   array['Ser introducida (generalmente por el ser humano) en un ambiente distinto de su hábitat original, causando impactos negativos', 'Ser siempre nativa del ecosistema en que se encuentra', 'No causar nunca ningún impacto en el ecosistema local', 'Ser exclusivamente una especie extinta'],
   'Las especies invasoras se introducen en nuevos ambientes, a menudo por la actividad humana, y causan desequilibrios.'),
  ('47135dc0-e2bb-4e30-836f-f6394e0f6520', 'en',
   'Invasive species can harm native ecosystems mainly by:',
   array['Competing with native species for resources, sometimes even driving them to local extinction', 'Always coexisting harmoniously with native species, with no competition', 'Never reproducing in the new environment', 'Automatically reducing their own population, with no impact'],
   'By competing for resources, invasive species can harm native populations, altering the ecological balance.'),
  ('47135dc0-e2bb-4e30-836f-f6394e0f6520', 'es',
   'Las especies invasoras pueden perjudicar a los ecosistemas nativos principalmente por:',
   array['Competir por recursos con las especies nativas, pudiendo incluso llevarlas a la extinción local', 'Convivir siempre en armonía con las especies nativas, sin ninguna competencia', 'No reproducirse nunca en el nuevo ambiente', 'Reducir automáticamente su propia población, sin ningún impacto'],
   'Al competir por recursos, las especies invasoras pueden perjudicar a las poblaciones nativas y alterar el equilibrio ecológico.'),
  ('6afe9526-e162-41bd-9001-70961459ae8f', 'en',
   'The wild boar, an invasive species in several regions of Brazil, causes significant impacts, among other things, on:',
   array['Agriculture and local biodiversity, by destroying crops and native habitats', 'Improving soil quality in every region where it is introduced', 'An immediate reduction in soil erosion', 'No environmental impact at all'],
   'The wild boar causes significant damage to agriculture and native ecosystems, competing with local wildlife.'),
  ('6afe9526-e162-41bd-9001-70961459ae8f', 'es',
   'El jabalí, una especie invasora en diversas regiones de Brasil, causa impactos significativos, entre otros aspectos, en:',
   array['La agricultura y la biodiversidad local, por la destrucción de cultivos y hábitats nativos', 'La mejora de la calidad del suelo en todas las regiones donde se introduce', 'La reducción inmediata de la erosión del suelo', 'Ningún impacto ambiental'],
   'El jabalí causa perjuicios significativos a la agricultura y a los ecosistemas nativos, compitiendo con la fauna local.'),
  ('ebf87f18-ec13-4441-a27e-82b180ef5e0b', 'en',
   'The absence of natural predators in a new environment is one of the factors that often favors:',
   array['The reproductive success and uncontrolled spread of invasive species', 'The rapid extinction of invasive species', 'An immediate reduction in the invasive species'' population', 'No advantage for the introduced species'],
   'With no natural predators to control their population, invasive species often spread quickly.'),
  ('ebf87f18-ec13-4441-a27e-82b180ef5e0b', 'es',
   'La ausencia de depredadores naturales en un nuevo ambiente es uno de los factores que a menudo favorece:',
   array['El éxito reproductivo y la expansión descontrolada de las especies invasoras', 'La rápida extinción de las especies invasoras', 'La reducción inmediata de la población de la especie invasora', 'Ninguna ventaja para la especie introducida'],
   'Sin depredadores naturales que controlen su población, las especies invasoras suelen expandirse rápidamente.'),
  ('51b72777-1901-4da2-bd27-13b64c9446ee', 'en',
   'Among the measures used to control invasive species are:',
   array['Monitoring programs, population control and, in some cases, eradication', 'Encouraging the introduction of even more exotic species', 'A complete absence of any control action', 'Unrestricted legal protection of the invasive species'],
   'Managing invasive species usually involves continuous monitoring and population control strategies.'),
  ('51b72777-1901-4da2-bd27-13b64c9446ee', 'es',
   'Entre las medidas usadas para controlar las especies invasoras se encuentran:',
   array['Programas de monitoreo, control poblacional y, en algunos casos, erradicación', 'El incentivo a la introducción de aún más especies exóticas', 'La ausencia total de cualquier acción de control', 'La protección legal irrestricta de la especie invasora'],
   'El manejo de especies invasoras suele implicar monitoreo continuo y estrategias de control poblacional.'),
  ('399fe9f5-b034-400c-bff4-365dea57ef05', 'en',
   'Environmental pollution can be defined as:',
   array['The introduction of substances or energy into the environment that can cause harmful effects to living beings', 'The natural process of nutrient cycling in an ecosystem', 'The complete absence of human activity in a region', 'The natural, balanced growth of a population'],
   'Pollution involves introducing agents that negatively change the natural conditions of the environment.'),
  ('399fe9f5-b034-400c-bff4-365dea57ef05', 'es',
   'La contaminación ambiental puede definirse como:',
   array['La introducción en el ambiente de sustancias o energía capaces de causar efectos perjudiciales a los seres vivos', 'El proceso natural de reciclaje de nutrientes en un ecosistema', 'La ausencia total de actividad humana en una región', 'El crecimiento natural y equilibrado de una población'],
   'La contaminación implica la introducción de agentes que alteran negativamente las condiciones naturales del ambiente.'),
  ('7a51ebd0-04da-4ac9-947f-a52bdf69f270', 'en',
   'Water pollution from untreated domestic sewage can cause, among other problems:',
   array['Eutrophication, with excessive algae growth and a drop in dissolved oxygen', 'An immediate improvement in water quality', 'An increase in aquatic biodiversity, with no harm', 'No relevant impact on aquatic organisms'],
   'The excess nutrients in sewage encourage algae growth, reducing the available oxygen.'),
  ('7a51ebd0-04da-4ac9-947f-a52bdf69f270', 'es',
   'La contaminación del agua por aguas residuales domésticas sin tratar puede causar, entre otros problemas:',
   array['La eutrofización, con proliferación excesiva de algas y reducción del oxígeno disuelto', 'Una mejora inmediata de la calidad del agua', 'El aumento de la biodiversidad acuática, sin ningún perjuicio', 'Ningún impacto relevante en los organismos acuáticos'],
   'El exceso de nutrientes de las aguas residuales favorece la proliferación de algas, lo que reduce el oxígeno disponible.'),
  ('f106b5a4-a5a6-42d3-b6c3-c89c488637fd', 'en',
   'Air pollution caused by motor vehicles and industries is directly related to problems such as:',
   array['Respiratory diseases and the formation of acid rain', 'Improved air quality in urban areas', 'A lower average temperature in cities', 'A thicker stratospheric ozone layer'],
   'The emission of air pollutants is associated with respiratory problems and the formation of acid rain.'),
  ('f106b5a4-a5a6-42d3-b6c3-c89c488637fd', 'es',
   'La contaminación atmosférica causada por vehículos a motor e industrias está directamente relacionada con problemas como:',
   array['Las enfermedades respiratorias y la formación de lluvia ácida', 'La mejora de la calidad del aire en las zonas urbanas', 'La reducción de la temperatura media de las ciudades', 'El aumento de la capa de ozono estratosférica'],
   'La emisión de contaminantes atmosféricos está asociada a problemas respiratorios y a la formación de lluvia ácida.'),
  ('2ed5b524-50a8-452d-96af-3c0214834813', 'en',
   'Soil pollution, caused by improper waste disposal and excessive use of pesticides, can result in:',
   array['Contamination of groundwater and harm to soil fertility', 'An immediate, permanent increase in soil fertility', 'No significant change in the soil''s properties', 'The complete elimination of any contaminant from the environment'],
   'Toxic substances disposed of improperly can seep into the soil and contaminate groundwater.'),
  ('2ed5b524-50a8-452d-96af-3c0214834813', 'es',
   'La contaminación del suelo, causada por la eliminación inadecuada de residuos y el uso excesivo de plaguicidas, puede provocar:',
   array['La contaminación de las aguas subterráneas y el deterioro de la fertilidad del suelo', 'Un aumento inmediato y permanente de la fertilidad del suelo', 'Ningún cambio significativo en las propiedades del suelo', 'La eliminación total de cualquier contaminante del ambiente'],
   'Las sustancias tóxicas desechadas de forma inadecuada pueden infiltrarse en el suelo y contaminar las aguas subterráneas.'),
  ('24f9a60f-d969-44fe-aadf-8c693f2f6db6', 'en',
   'Pollution control measures include, among other actions:',
   array['Properly treating effluents and waste before releasing them into the environment', 'Free, uncontrolled disposal of any kind of waste', 'The complete elimination of any environmental legislation', 'Encouraging the uncontrolled use of pesticides'],
   'Treating effluents and waste management policies are fundamental measures to reduce pollution.'),
  ('24f9a60f-d969-44fe-aadf-8c693f2f6db6', 'es',
   'Las medidas de control de la contaminación incluyen, entre otras acciones:',
   array['El tratamiento adecuado de efluentes y residuos antes de liberarlos al ambiente', 'La eliminación libre y sin control de cualquier tipo de residuo', 'La eliminación total de cualquier legislación ambiental', 'El incentivo al uso descontrolado de plaguicidas'],
   'El tratamiento de efluentes y las políticas de gestión de residuos son medidas fundamentales para reducir la contaminación.'),
  ('8c617d51-632e-47df-8f3c-0edc245b1a2c', 'en',
   'Amensalism is an ecological relationship characterized by:',
   array['Harm to one species, while the other is neither significantly helped nor harmed', 'Mutual benefit for both species involved', 'Mutual harm for both species', 'Benefit for one species and clear harm for the other, with both affected'],
   'In amensalism, one species is harmed while the other remains practically unaffected.'),
  ('8c617d51-632e-47df-8f3c-0edc245b1a2c', 'es',
   'El amensalismo es una relación ecológica caracterizada por:',
   array['El perjuicio a una especie, sin que la otra resulte beneficiada ni perjudicada de forma significativa', 'El beneficio mutuo para las dos especies involucradas', 'El perjuicio mutuo para ambas especies', 'El beneficio para una especie y el perjuicio evidente para la otra, con ambas afectadas'],
   'En el amensalismo, una especie resulta perjudicada, mientras que la otra permanece prácticamente indiferente.'),
  ('994234c7-a12f-4025-bc05-2a93a137880a', 'en',
   'Certain fungi producing chemical substances, such as penicillin, that inhibit the growth of nearby bacteria, without the fungus getting any direct benefit from this inhibition, is an example of:',
   array['Amensalism', 'Mutualism', 'Parasitism', 'Predation'],
   'The fungus harms the bacteria but gets no additional direct benefit from this inhibition, which characterizes amensalism.'),
  ('994234c7-a12f-4025-bc05-2a93a137880a', 'es',
   'La producción de sustancias químicas por ciertos hongos, como la penicilina, que inhiben el crecimiento de bacterias cercanas sin que el hongo obtenga un beneficio directo de esa inhibición, es un ejemplo de:',
   array['Amensalismo', 'Mutualismo', 'Parasitismo', 'Depredación'],
   'El hongo perjudica a las bacterias, pero no obtiene un beneficio directo adicional con esa inhibición, lo que caracteriza el amensalismo.'),
  ('c883b5ec-41a7-489a-b8af-d562f58793b5', 'en',
   'Some plants release chemical substances into the soil (allelopathy) that inhibit the growth of other plants around them, without the producing plant gaining a direct advantage from this effect. This phenomenon is an example of:',
   array['Amensalism', 'Commensalism', 'Mutualism', 'Protocooperation'],
   'The plant that releases the substance harms its neighbors without gaining any additional direct benefit, which characterizes amensalism.'),
  ('c883b5ec-41a7-489a-b8af-d562f58793b5', 'es',
   'Algunas plantas liberan sustancias químicas en el suelo (alelopatía) que inhiben el crecimiento de otras plantas a su alrededor, sin que la planta productora obtenga una ventaja directa con ese efecto. Este fenómeno ejemplifica:',
   array['Amensalismo', 'Comensalismo', 'Mutualismo', 'Protocooperación'],
   'La planta que libera la sustancia perjudica a sus vecinas sin obtener ningún beneficio adicional directo, lo que caracteriza el amensalismo.'),
  ('31be04df-a943-4817-9b98-101b579fc7aa', 'en',
   'Ecologically, amensalism is classified as a relationship that is:',
   array['Disharmonious (negative), since it harms one of the species involved', 'Harmonious, since it benefits both species', 'Identical to mutualism', 'Always beneficial for the harmed species'],
   'Because it harms one of the species, amensalism is classified as a disharmonious ecological relationship.'),
  ('31be04df-a943-4817-9b98-101b579fc7aa', 'es',
   'Ecológicamente, el amensalismo se clasifica como una relación:',
   array['Desarmónica, pues perjudica a una de las especies involucradas', 'Armónica, pues beneficia a ambas especies', 'Idéntica al mutualismo', 'Siempre beneficiosa para la especie perjudicada'],
   'Por causar perjuicio a una de las especies, el amensalismo se clasifica como una relación ecológica desarmónica.'),
  ('6d3aeb86-598c-4ade-ac0f-0cfdcda7f800', 'en',
   'The main difference between amensalism and competition is that:',
   array['In amensalism, only one species is harmed, while in competition both species involved can be harmed by the dispute', 'In amensalism, both species benefit', 'In competition, no species is harmed', 'There is no difference between the two phenomena'],
   'In competition, the dispute can harm both species; in amensalism, typically only one suffers harm.'),
  ('6d3aeb86-598c-4ade-ac0f-0cfdcda7f800', 'es',
   'La principal diferencia entre el amensalismo y la competencia está en que:',
   array['En el amensalismo, solo una especie resulta perjudicada, mientras que en la competencia ambas especies pueden resultar perjudicadas por la disputa', 'En el amensalismo, ambas especies se benefician', 'En la competencia, ninguna especie resulta perjudicada', 'No existe ninguna diferencia entre los dos fenómenos'],
   'En la competencia, la disputa puede perjudicar a ambas especies; en el amensalismo, normalmente solo una sufre el perjuicio.'),
  ('179041a5-c1d1-4dab-b5f6-83c39865cc4f', 'en',
   'Commensalism is an ecological relationship characterized by:',
   array['Benefit for one species, with no significant harm or benefit for the other', 'Mutual benefit for both species involved', 'Harm for both species', 'Benefit for one species and clear harm for the other'],
   'In commensalism, one species benefits while the other is not significantly affected.'),
  ('179041a5-c1d1-4dab-b5f6-83c39865cc4f', 'es',
   'El comensalismo es una relación ecológica caracterizada por:',
   array['El beneficio para una especie, sin perjuicio ni beneficio significativo para la otra', 'El beneficio mutuo para las dos especies involucradas', 'El perjuicio para ambas especies', 'El beneficio para una especie y el perjuicio evidente para la otra'],
   'En el comensalismo, una especie se beneficia, mientras que la otra no resulta afectada significativamente.'),
  ('228974e3-4b6b-40fa-8751-be78d0fcfd04', 'en',
   'The relationship between the remora (a fish) and the shark, in which the remora attaches to the shark''s body to feed on leftover food, is a classic example of:',
   array['Commensalism', 'Mutualism', 'Parasitism', 'Predation'],
   'The remora benefits by getting food and protection, while the shark is not significantly affected.'),
  ('228974e3-4b6b-40fa-8751-be78d0fcfd04', 'es',
   'La relación entre la rémora (pez) y el tiburón, en la que la rémora se adhiere al cuerpo del tiburón para alimentarse de restos de comida, es un ejemplo clásico de:',
   array['Comensalismo', 'Mutualismo', 'Parasitismo', 'Depredación'],
   'La rémora se beneficia al obtener alimento y protección, mientras que el tiburón no resulta afectado significativamente.'),
  ('890a93ca-1540-4af7-9dee-9ce5777500b4', 'en',
   'Epiphytic plants, such as many orchids, which grow on other trees using them only as physical support, are an example of:',
   array['Commensalism', 'Parasitism', 'Mutualism', 'Competition'],
   'Epiphytes benefit from the physical support without taking nutrients from the host tree or causing significant harm.'),
  ('890a93ca-1540-4af7-9dee-9ce5777500b4', 'es',
   'Las plantas epífitas, como muchas orquídeas, que crecen sobre otros árboles usándolos solo como soporte físico, ejemplifican:',
   array['Comensalismo', 'Parasitismo', 'Mutualismo', 'Competencia'],
   'Las epífitas se benefician del soporte físico, sin retirar nutrientes del árbol hospedero ni causarle un perjuicio significativo.'),
  ('cb583fa8-fe05-45ac-b2d1-ab1f123f8a7f', 'en',
   'The main difference between commensalism and parasitism is that, in commensalism:',
   array['The host species suffers no significant harm from the interaction', 'The host species is always harmed', 'Both species benefit equally', 'Neither species interacts physically'],
   'While in parasitism the host is harmed, in commensalism it remains practically unaffected.'),
  ('cb583fa8-fe05-45ac-b2d1-ab1f123f8a7f', 'es',
   'La principal diferencia entre el comensalismo y el parasitismo está en que, en el comensalismo:',
   array['La especie hospedera no sufre un perjuicio significativo con la interacción', 'La especie hospedera siempre resulta perjudicada', 'Ambas especies se benefician por igual', 'Ninguna de las especies interactúa físicamente'],
   'Mientras que en el parasitismo el hospedero resulta perjudicado, en el comensalismo permanece prácticamente indiferente.'),
  ('06f2ab74-d836-4c48-96a3-ef55ef71a788', 'en',
   'Ecologically, commensalism is classified as a relationship that is:',
   array['Harmonious, since it causes no clear harm to either of the species involved', 'Disharmonious, because it harms one of the species', 'Always mutually beneficial, like mutualism', 'Exclusively competitive'],
   'Because it harms neither species and only benefits one of them, commensalism is a harmonious relationship.'),
  ('06f2ab74-d836-4c48-96a3-ef55ef71a788', 'es',
   'Ecológicamente, el comensalismo se clasifica como una relación:',
   array['Armónica, ya que no causa un perjuicio evidente a ninguna de las especies involucradas', 'Desarmónica, por perjudicar a una de las especies', 'Siempre mutuamente beneficiosa, como el mutualismo', 'Exclusivamente competitiva'],
   'Por no perjudicar a ninguna de las especies y solo beneficiar a una de ellas, el comensalismo es una relación armónica.'),
  ('84a79b15-07ae-4505-a675-a172537b5004', 'en',
   'In ecology, competition occurs when:',
   array['Two or more species (or individuals) fight over the same limited resource in the environment', 'Two species benefit mutually from the interaction', 'One species feeds directly on another', 'One organism lives on another''s body without causing harm'],
   'Competition arises when resources such as food, water, light or territory are contested by different organisms.'),
  ('84a79b15-07ae-4505-a675-a172537b5004', 'es',
   'En ecología, la competencia ocurre cuando:',
   array['Dos o más especies (o individuos) se disputan el mismo recurso limitado del ambiente', 'Dos especies se benefician mutuamente de la interacción', 'Una especie se alimenta directamente de otra', 'Un organismo vive sobre el cuerpo de otro sin causarle perjuicio'],
   'La competencia surge cuando diferentes organismos se disputan recursos como alimento, agua, luz o territorio.'),
  ('6366b7d6-a94c-4daa-869f-6eb7921209f0', 'en',
   'Interspecific competition occurs between:',
   array['Individuals of different species', 'Individuals of the same species exclusively', 'A predator and its prey', 'A parasite and its host'],
   'Interspecific competition involves organisms of different species competing for resources.'),
  ('6366b7d6-a94c-4daa-869f-6eb7921209f0', 'es',
   'La competencia interespecífica ocurre entre:',
   array['Individuos de especies diferentes', 'Individuos exclusivamente de la misma especie', 'Un depredador y su presa', 'Un parásito y su hospedero'],
   'La competencia interespecífica implica la disputa por recursos entre organismos de especies distintas.'),
  ('127f7582-4797-45a0-a640-8a71175cf9dc', 'en',
   'Intraspecific competition, in turn, occurs between:',
   array['Individuals of the same species', 'Individuals of different species', 'A predator and a prey', 'A fungus and an alga'],
   'Individuals of the same species often compete with each other for territory, food or mates.'),
  ('127f7582-4797-45a0-a640-8a71175cf9dc', 'es',
   'La competencia intraespecífica, por su parte, ocurre entre:',
   array['Individuos de la misma especie', 'Individuos de especies diferentes', 'Un depredador y una presa', 'Un hongo y un alga'],
   'Los individuos de una misma especie suelen competir entre sí por territorio, alimento o pareja.'),
  ('5c3eaceb-3d4e-4646-8e12-e1b4bc31df8c', 'en',
   'The "competitive exclusion principle" proposes that:',
   array['Two species with identical ecological requirements cannot coexist indefinitely in the same environment', 'All species can coexist indefinitely, regardless of competition', 'Competition never influences the distribution of species', 'Only genetically identical species can compete with each other'],
   'When two species compete for exactly the same resources, one tends to be eliminated or to adapt.'),
  ('5c3eaceb-3d4e-4646-8e12-e1b4bc31df8c', 'es',
   'El "principio de exclusión competitiva" propone que:',
   array['Dos especies con exigencias ecológicas idénticas no pueden coexistir indefinidamente en el mismo ambiente', 'Todas las especies pueden coexistir indefinidamente, independientemente de la competencia', 'La competencia nunca influye en la distribución de las especies', 'Solo las especies genéticamente idénticas pueden competir entre sí'],
   'Cuando dos especies compiten exactamente por los mismos recursos, una tiende a ser eliminada o a adaptarse.'),
  ('491cdf36-5992-44db-8a81-24385465da22', 'en',
   'Over evolutionary time, competition for limited resources is one of the main factors that drive:',
   array['Natural selection and the adaptation of species to the environment', 'A complete absence of evolutionary change', 'The elimination of all genetic variability', 'The immediate extinction of all the species involved'],
   'The pressure created by competition favors the fittest individuals and is a driving force of natural selection.'),
  ('491cdf36-5992-44db-8a81-24385465da22', 'es',
   'A lo largo del tiempo evolutivo, la competencia por recursos limitados es uno de los principales factores que impulsan:',
   array['La selección natural y la adaptación de las especies al ambiente', 'La ausencia total de cambios evolutivos', 'La eliminación de cualquier variabilidad genética', 'La extinción inmediata de todas las especies involucradas'],
   'La presión que genera la competencia favorece a los individuos más aptos y es un motor de la selección natural.'),
  ('f58469fc-db0e-458c-ab25-08c9b0130de1', 'en',
   'Mutualism is an ecological relationship characterized by:',
   array['Mutual benefit for both species involved, being essential for the survival of both', 'Benefit for only one species, with no harm to the other', 'Harm to both species involved', 'Benefit for one species and harm to the other'],
   'In mutualism, both species gain significant benefits, and the relationship is often essential for their survival.'),
  ('f58469fc-db0e-458c-ab25-08c9b0130de1', 'es',
   'El mutualismo es una relación ecológica caracterizada por:',
   array['El beneficio mutuo para las dos especies involucradas, siendo esencial para la supervivencia de ambas', 'El beneficio para solo una de las especies, sin perjuicio para la otra', 'El perjuicio para ambas especies involucradas', 'El beneficio para una especie y el perjuicio para la otra'],
   'En el mutualismo, ambas especies obtienen beneficios significativos, y esta relación suele ser esencial para su supervivencia.'),
  ('d9e6fb34-7128-411c-9b25-d2659b22b693', 'en',
   'Lichens, formed by the association between fungi and algae (or cyanobacteria), are a classic example of:',
   array['Mutualism', 'Parasitism', 'Predation', 'Amensalism'],
   'In a lichen, the fungus provides protection and absorbs water and minerals, while the alga provides nutrients from photosynthesis, benefiting both.'),
  ('d9e6fb34-7128-411c-9b25-d2659b22b693', 'es',
   'Los líquenes, formados por la asociación entre hongos y algas (o cianobacterias), son un ejemplo clásico de:',
   array['Mutualismo', 'Parasitismo', 'Depredación', 'Amensalismo'],
   'En el liquen, el hongo proporciona protección y absorbe agua y minerales, mientras que el alga aporta nutrientes de la fotosíntesis, y ambos se benefician.'),
  ('bd6f0d57-f2b5-48b6-9cfe-204a12d5c37e', 'en',
   'The relationship between bees and flowers, in which the bees get nectar and the flowers are pollinated, is an example of:',
   array['Mutualism', 'Commensalism', 'Parasitism', 'Competition'],
   'Both sides benefit: the bees get food, while the flowers ensure their reproduction.'),
  ('bd6f0d57-f2b5-48b6-9cfe-204a12d5c37e', 'es',
   'La relación entre las abejas y las flores, en la que las abejas obtienen néctar y las flores son polinizadas, ejemplifica:',
   array['Mutualismo', 'Comensalismo', 'Parasitismo', 'Competencia'],
   'Ambas partes se benefician: las abejas obtienen alimento, mientras que las flores garantizan su reproducción.'),
  ('64eaee6f-c3f8-40b3-aa33-49fc66123fd2', 'en',
   'Bacteria in the intestines of many animals, including humans, which help digest food in exchange for nutrients and shelter, are an example of a relationship of:',
   array['Mutualism', 'Predation', 'Amensalism', 'Competition'],
   'Beneficial gut bacteria help with digestion while receiving nutrients and shelter, which characterizes mutualism.'),
  ('64eaee6f-c3f8-40b3-aa33-49fc66123fd2', 'es',
   'Las bacterias presentes en el intestino de muchos animales, incluidos los seres humanos, que ayudan a digerir los alimentos a cambio de nutrientes y refugio, ejemplifican una relación de:',
   array['Mutualismo', 'Depredación', 'Amensalismo', 'Competencia'],
   'Las bacterias intestinales beneficiosas ayudan en la digestión mientras reciben nutrientes y refugio, lo que caracteriza el mutualismo.'),
  ('3056a2c7-7a88-4357-8f63-94be74249ded', 'en',
   'In obligate mutualism, unlike facultative mutualism, the species involved:',
   array['Depend completely on each other to survive', 'Can survive perfectly well without the interaction', 'Never interact directly', 'Always compete for the same resources'],
   'In obligate mutualism, the relationship is essential for the survival of at least one of the species involved.'),
  ('3056a2c7-7a88-4357-8f63-94be74249ded', 'es',
   'En el mutualismo obligatorio, a diferencia del facultativo, las especies involucradas:',
   array['Dependen totalmente una de la otra para sobrevivir', 'Pueden sobrevivir perfectamente sin la interacción', 'Nunca interactúan directamente', 'Siempre compiten por los mismos recursos'],
   'En el mutualismo obligatorio, la relación es esencial para la supervivencia de al menos una de las especies involucradas.'),
  ('97cce2bc-77e3-4dc9-ae01-b55ca5220c4b', 'en',
   'Parasitism is an ecological relationship in which:',
   array['One organism (the parasite) lives at the expense of another (the host), usually harming it without killing it immediately', 'Both species benefit mutually', 'One species kills and eats the other immediately', 'Two species compete for the same resource, with no direct relationship'],
   'In parasitism, the parasite gets nutrients or shelter from the host, usually causing harm without immediate death.'),
  ('97cce2bc-77e3-4dc9-ae01-b55ca5220c4b', 'es',
   'El parasitismo es una relación ecológica en la que:',
   array['Un organismo (el parásito) vive a costa de otro (el hospedero), generalmente perjudicándolo sin matarlo de inmediato', 'Ambas especies se benefician mutuamente', 'Una especie mata y consume a la otra de inmediato', 'Dos especies compiten por el mismo recurso, sin ninguna relación directa'],
   'En el parasitismo, el parásito obtiene nutrientes o refugio del hospedero y generalmente le causa perjuicio sin la muerte inmediata.'),
  ('11ec2a23-45c9-43f1-9883-ca647b8be65e', 'en',
   'Intestinal worms, such as the roundworm (Ascaris lumbricoides), which live inside the host''s body, are classified as:',
   array['Endoparasites', 'Ectoparasites', 'Predators', 'Mutualistic organisms'],
   'Endoparasites live inside the host organism, unlike ectoparasites.'),
  ('11ec2a23-45c9-43f1-9883-ca647b8be65e', 'es',
   'Los gusanos intestinales, como la lombriz intestinal (Ascaris lumbricoides), que viven en el interior del cuerpo del hospedero, se clasifican como:',
   array['Endoparásitos', 'Ectoparásitos', 'Depredadores', 'Organismos mutualistas'],
   'Los endoparásitos viven en el interior del organismo hospedero, a diferencia de los ectoparásitos.'),
  ('23d8d4b2-170c-430d-b93f-078d9f67b2fa', 'en',
   'Fleas and ticks, which live on their hosts'' skin and feed on their blood, are classified as:',
   array['Ectoparasites', 'Endoparasites', 'Typical predators', 'Mutualistic organisms'],
   'Because they live outside the host''s body, fleas and ticks are classified as ectoparasites.'),
  ('23d8d4b2-170c-430d-b93f-078d9f67b2fa', 'es',
   'Las pulgas y las garrapatas, que viven sobre la piel de sus hospederos y se alimentan de su sangre, se clasifican como:',
   array['Ectoparásitos', 'Endoparásitos', 'Depredadores típicos', 'Organismos mutualistas'],
   'Por vivir fuera del cuerpo del hospedero, las pulgas y las garrapatas se clasifican como ectoparásitos.'),
  ('216974b5-6643-494f-9b75-890ba1635c1d', 'en',
   'Unlike predators, parasites usually:',
   array['Do not cause the host''s immediate death and can live with it for long periods', 'Kill the host instantly', 'Significantly benefit the host', 'Never cause any kind of harm to the host'],
   'Unlike predators, many parasites depend on the host surviving for a long time.'),
  ('216974b5-6643-494f-9b75-890ba1635c1d', 'es',
   'A diferencia de los depredadores, los parásitos generalmente:',
   array['No causan la muerte inmediata del hospedero y pueden convivir con él durante largos períodos', 'Matan al hospedero instantáneamente', 'Benefician significativamente al hospedero', 'Nunca causan ningún tipo de perjuicio al hospedero'],
   'A diferencia de los depredadores, muchos parásitos dependen de que el hospedero sobreviva durante mucho tiempo.'),
  ('3ab5a118-e203-4380-88e8-afd9a87f1a75', 'en',
   'Ecologically, parasitism is classified as a relationship that is:',
   array['Disharmonious, since it harms one of the species involved (the host)', 'Harmonious, since it benefits both species', 'Neutral, with no harm to either side', 'Identical to mutualism'],
   'Since the host is harmed, parasitism is classified as a disharmonious ecological relationship.'),
  ('3ab5a118-e203-4380-88e8-afd9a87f1a75', 'es',
   'Ecológicamente, el parasitismo se clasifica como una relación:',
   array['Desarmónica, pues perjudica a una de las especies involucradas (el hospedero)', 'Armónica, ya que beneficia a ambas especies', 'Neutra, sin ningún perjuicio para ninguna de las partes', 'Idéntica al mutualismo'],
   'Como el hospedero resulta perjudicado, el parasitismo se clasifica como una relación ecológica desarmónica.'),
  ('63c8723f-9f3a-47af-b2af-1fa759900335', 'en',
   'Predation is an ecological relationship in which:',
   array['One organism (the predator) hunts and feeds on another organism (the prey)', 'Two species compete for the same resource, with no predation', 'Both species benefit mutually', 'One species lives inside or on the other without causing its death'],
   'In predation, the predator kills the prey in order to feed on it.'),
  ('63c8723f-9f3a-47af-b2af-1fa759900335', 'es',
   'La depredación es una relación ecológica en la que:',
   array['Un organismo (el depredador) caza y se alimenta de otro organismo (la presa)', 'Dos especies compiten por el mismo recurso, sin ninguna depredación', 'Ambas especies se benefician mutuamente', 'Una especie vive dentro o sobre la otra sin causarle la muerte'],
   'En la depredación, el depredador mata a la presa para alimentarse de ella.'),
  ('4e115a82-12ba-4813-a67e-baf23a652fa3', 'en',
   'Predation plays an important ecological role by helping to:',
   array['Control the size of prey populations in an ecosystem', 'Completely eliminate any prey population', 'Prevent any form of evolution of the species', 'Always reduce the biodiversity of an ecosystem'],
   'Predators help keep prey populations in balance, preventing uncontrolled growth.'),
  ('4e115a82-12ba-4813-a67e-baf23a652fa3', 'es',
   'La depredación cumple un papel ecológico importante al ayudar a:',
   array['Controlar el tamaño de las poblaciones de presas en un ecosistema', 'Eliminar por completo cualquier población de presas', 'Impedir cualquier forma de evolución de las especies', 'Reducir siempre la biodiversidad de un ecosistema'],
   'Los depredadores ayudan a mantener el equilibrio poblacional de las presas y evitan su crecimiento descontrolado.'),
  ('161d1168-05ee-4e56-a497-d89351596532', 'en',
   'The relationship between lions and zebras, on the African savanna, is a classic example of:',
   array['Predation', 'Mutualism', 'Commensalism', 'Amensalism'],
   'Lions (predators) hunt and feed on zebras (prey), a classic predator-prey relationship.'),
  ('161d1168-05ee-4e56-a497-d89351596532', 'es',
   'La relación entre los leones y las cebras, en la sabana africana, es un ejemplo clásico de:',
   array['Depredación', 'Mutualismo', 'Comensalismo', 'Amensalismo'],
   'Los leones (depredadores) cazan y se alimentan de las cebras (presas), una clásica relación de depredación.'),
  ('31f82f6e-0641-4d20-9909-c7bfcc8ba453', 'en',
   'Over the course of evolution, predation has driven the development of:',
   array['Defensive adaptations in prey and more efficient hunting adaptations in predators', 'No significant evolutionary change in either species', 'The immediate extinction of all prey species', 'The complete elimination of genetic variability'],
   'The pressure of predation favors defense and capture adaptations, in a process of coevolution.'),
  ('31f82f6e-0641-4d20-9909-c7bfcc8ba453', 'es',
   'A lo largo de la evolución, la depredación ha impulsado el desarrollo de:',
   array['Adaptaciones defensivas en las presas y adaptaciones de caza más eficientes en los depredadores', 'Ningún cambio evolutivo significativo en ninguna de las especies', 'La extinción inmediata de todas las especies de presas', 'La eliminación completa de la variabilidad genética'],
   'La presión de la depredación favorece adaptaciones de defensa y de captura, en un proceso de coevolución.'),
  ('e229dfc0-f178-4eae-90c6-d09b03bf6304', 'en',
   'Unlike parasitism, in typical predation:',
   array['The prey usually dies immediately during the interaction', 'The host survives the interaction normally', 'No tissue of the affected organism is consumed', 'The relationship is always beneficial to both species'],
   'In classic predation, the prey is killed and eaten quickly, unlike the prolonged relationship of parasitism.'),
  ('e229dfc0-f178-4eae-90c6-d09b03bf6304', 'es',
   'A diferencia del parasitismo, en la depredación típica:',
   array['La presa generalmente muere de inmediato durante la interacción', 'El hospedero sobrevive a la interacción con normalidad', 'No se consume ningún tejido del organismo afectado', 'La relación es siempre beneficiosa para ambas especies'],
   'En la depredación clásica, la presa muere y es consumida rápidamente, a diferencia de la relación prolongada del parasitismo.'),
  ('04c37d05-1156-4778-84a7-699c0df0d0e4', 'en',
   'Protocooperation is an ecological relationship characterized by:',
   array['Mutual benefit between two species, without the relationship being necessary for the survival of either', 'An obligatory benefit, essential for the survival of both species', 'Harm to both species involved', 'Benefit for one species and harm to the other'],
   'Unlike obligate mutualism, in protocooperation the species survive normally even without the interaction.'),
  ('04c37d05-1156-4778-84a7-699c0df0d0e4', 'es',
   'La protocooperación es una relación ecológica caracterizada por:',
   array['El beneficio mutuo entre dos especies, sin que la relación sea obligatoria para la supervivencia de ninguna de ellas', 'Un beneficio obligatorio y esencial para la supervivencia de ambas especies', 'El perjuicio para las dos especies involucradas', 'El beneficio para una especie y el perjuicio para la otra'],
   'A diferencia del mutualismo obligatorio, en la protocooperación las especies sobreviven con normalidad incluso sin la interacción.'),
  ('c46f8082-e959-47ad-a380-b3a3e6be0d35', 'en',
   'The relationship between the crocodile and the plover (a small bird that picks food scraps from between the reptile''s teeth) is a classic example of:',
   array['Protocooperation', 'Parasitism', 'Predation', 'Amensalism'],
   'The bird feeds on the scraps while the crocodile gets its teeth cleaned, but both survive without this specific interaction.'),
  ('c46f8082-e959-47ad-a380-b3a3e6be0d35', 'es',
   'La relación entre el cocodrilo y el pájaro corredor (chorlito egipcio), que retira restos de comida de entre los dientes del reptil, es un ejemplo clásico de:',
   array['Protocooperación', 'Parasitismo', 'Depredación', 'Amensalismo'],
   'El pájaro se alimenta de los restos mientras el cocodrilo obtiene los dientes limpios, pero ambos sobreviven sin esa interacción específica.'),
  ('3b556ff3-62e8-420f-8337-a19b98fd2774', 'en',
   'The main difference between protocooperation and obligate mutualism is that:',
   array['Protocooperation is not essential to the survival of the species involved', 'Protocooperation always harms one of the species', 'Mutualism never benefits both species', 'There is no difference between the two phenomena'],
   'While obligate mutualism is essential for survival, protocooperation is advantageous but dispensable.'),
  ('3b556ff3-62e8-420f-8337-a19b98fd2774', 'es',
   'La principal diferencia entre la protocooperación y el mutualismo obligatorio está en que:',
   array['La protocooperación no es indispensable para la supervivencia de las especies involucradas', 'La protocooperación siempre perjudica a una de las especies', 'El mutualismo nunca beneficia a ambas especies', 'No existe ninguna diferencia entre los dos fenómenos'],
   'Mientras que el mutualismo obligatorio es esencial para la supervivencia, la protocooperación es ventajosa, pero prescindible.'),
  ('d2a2a63e-7d29-48b8-89b9-834be3ce873e', 'en',
   'The relationship between birds that eat ticks off the skin of large mammals, such as cattle, is commonly classified as:',
   array['Protocooperation', 'Parasitism', 'Amensalism', 'Predation'],
   'The bird benefits by getting food, and the mammal benefits from having the parasites removed, but neither depends exclusively on this relationship.'),
  ('d2a2a63e-7d29-48b8-89b9-834be3ce873e', 'es',
   'La relación entre las aves que se alimentan de garrapatas sobre la piel de grandes mamíferos, como el buey, suele clasificarse como:',
   array['Protocooperación', 'Parasitismo', 'Amensalismo', 'Depredación'],
   'El ave se beneficia al obtener alimento y el mamífero se beneficia de la retirada de los parásitos, pero ninguno depende exclusivamente de esa relación.'),
  ('3399060e-cc7a-4561-b81f-28ca2dd5c413', 'en',
   'Like mutualism, protocooperation is ecologically classified as a relationship that is:',
   array['Harmonious (positive for both species involved)', 'Disharmonious (harmful to at least one species)', 'Neutral, with no effect at all', 'Exclusively competitive'],
   'Because they benefit both species, both mutualism and protocooperation are harmonious ecological relationships.'),
  ('3399060e-cc7a-4561-b81f-28ca2dd5c413', 'es',
   'Al igual que el mutualismo, la protocooperación se clasifica ecológicamente como una relación:',
   array['Armónica (positiva para ambas especies involucradas)', 'Desarmónica (perjudicial para al menos una especie)', 'Neutra, sin ningún efecto', 'Exclusivamente competitiva'],
   'Por beneficiar a ambas especies, tanto el mutualismo como la protocooperación son relaciones ecológicas armónicas.'),
  ('feb82797-1023-4c80-9d16-7f5f1fc60821', 'en',
   'The Theory of Evolution by Natural Selection, proposed by Charles Darwin, is based mainly on the idea that:',
   array['Individuals better adapted to the environment are more likely to survive and reproduce, passing on their characteristics', 'All individuals in a population have exactly the same chances of survival, regardless of their characteristics', 'Characteristics acquired during life are always passed on genetically to offspring', 'Evolution happens instantly, in a single generation'],
   'Natural selection favors the differential survival and reproduction of the best-adapted individuals over generations.'),
  ('feb82797-1023-4c80-9d16-7f5f1fc60821', 'es',
   'La Teoría de la Evolución por Selección Natural, propuesta por Charles Darwin, se basa principalmente en la idea de que:',
   array['Los individuos mejor adaptados al ambiente tienen más probabilidades de sobrevivir y reproducirse, transmitiendo sus características', 'Todos los individuos de una población tienen exactamente las mismas probabilidades de supervivencia, independientemente de sus características', 'Las características adquiridas a lo largo de la vida siempre se transmiten genéticamente a la descendencia', 'La evolución ocurre de forma instantánea, en una sola generación'],
   'La selección natural favorece la supervivencia y la reproducción diferencial de los individuos más adaptados a lo largo de las generaciones.'),
  ('4d94c9dd-1451-498d-9295-47753121876c', 'en',
   'Genetic variability within a population is fundamental to the evolutionary process because:',
   array['It provides the raw material on which natural selection can act', 'It completely prevents any evolutionary change', 'It ensures that all individuals are always identical to one another', 'It has nothing to do with the evolution of species'],
   'Without genetic variability, there would be no differences between individuals for natural selection to act on.'),
  ('4d94c9dd-1451-498d-9295-47753121876c', 'es',
   'La variabilidad genética dentro de una población es fundamental para el proceso evolutivo porque:',
   array['Proporciona la materia prima sobre la que puede actuar la selección natural', 'Impide por completo cualquier cambio evolutivo', 'Garantiza que todos los individuos sean siempre idénticos entre sí', 'No tiene ninguna relación con la evolución de las especies'],
   'Sin variabilidad genética, no habría diferencias entre los individuos sobre las cuales pudiera actuar la selección natural.'),
  ('694cd3ab-1ff6-4c0e-bc38-0693fada0b61', 'en',
   'The concept of "adaptation", central to evolutionary theory, refers to:',
   array['Characteristics that increase an organism''s ability to survive and reproduce in its environment', 'Random changes unrelated to the environment', 'Characteristics that always harm the organism''s survival', 'A process that only occurs in plants, never in animals'],
   'Adaptations are characteristics that give advantages for survival and reproduction in a given environment.'),
  ('694cd3ab-1ff6-4c0e-bc38-0693fada0b61', 'es',
   'El concepto de "adaptación", central en la teoría evolutiva, se refiere a:',
   array['Características que aumentan la capacidad de supervivencia y reproducción de un organismo en su ambiente', 'Cambios aleatorios sin ninguna relación con el ambiente', 'Características que siempre perjudican la supervivencia del organismo', 'Un proceso que ocurre solo en las plantas, nunca en los animales'],
   'Las adaptaciones son características que confieren ventajas para la supervivencia y la reproducción en un ambiente determinado.'),
  ('e5ecb6df-d7a6-4385-8383-17bd0c2e48a0', 'en',
   'The process of speciation, which results in the formation of new species, usually occurs when:',
   array['Populations of the same species become reproductively isolated, accumulating genetic differences over time', 'All individuals of a species always remain in direct contact, with no isolation', 'There is no genetic variation between individuals', 'Natural selection never influences the formation of new species'],
   'Reproductive isolation between populations allows genetic changes to accumulate independently, which can give rise to new species.'),
  ('e5ecb6df-d7a6-4385-8383-17bd0c2e48a0', 'es',
   'El proceso de especiación, que da lugar a la formación de nuevas especies, suele ocurrir cuando:',
   array['Poblaciones de una misma especie quedan aisladas reproductivamente y acumulan diferencias genéticas con el tiempo', 'Todos los individuos de una especie permanecen siempre en contacto directo, sin ningún aislamiento', 'No existe ninguna variación genética entre los individuos', 'La selección natural nunca influye en la formación de nuevas especies'],
   'El aislamiento reproductivo entre poblaciones permite la acumulación independiente de cambios genéticos, lo que puede generar nuevas especies.'),
  ('30ec4c03-d95c-4f20-99af-df91e4d6e6bf', 'en',
   'The fossil record is one of the main pieces of evidence used to support the theory of evolution because it:',
   array['Documents gradual changes in organisms'' characteristics over long geological periods', 'Proves that no species has ever gone extinct', 'Shows that all species have always remained identical over time', 'Has nothing to do with the study of evolution'],
   'Analyzing fossils from different periods reveals gradual changes, providing evidence of evolutionary processes.'),
  ('30ec4c03-d95c-4f20-99af-df91e4d6e6bf', 'es',
   'El registro fósil es una de las principales evidencias usadas para sostener la teoría de la evolución porque:',
   array['Documenta cambios graduales en las características de los organismos a lo largo de largos períodos geológicos', 'Demuestra que ninguna especie se ha extinguido jamás', 'Muestra que todas las especies han permanecido siempre idénticas a lo largo del tiempo', 'No tiene ninguna relación con el estudio de la evolución'],
   'El análisis de fósiles de distintos períodos permite observar cambios graduales, lo que evidencia procesos evolutivos.'),
  ('093f5d7d-ad88-4838-a651-4055e9a67e9d', 'en',
   'Homology between anatomical structures of different species, such as mammal limbs with different functions (swimming, flying, running) but a similar bone structure, is considered evidence of:',
   array['Common ancestry among these species', 'A complete absence of any evolutionary relationship between the species', 'These species having arisen completely independently', 'Evolution never having occurred among these groups'],
   'Homologous structures, despite having different functions, share a common evolutionary origin.'),
  ('093f5d7d-ad88-4838-a651-4055e9a67e9d', 'es',
   'La homología entre estructuras anatómicas de diferentes especies, como las extremidades de mamíferos con funciones distintas (nadar, volar, correr) pero con estructura ósea semejante, se considera una evidencia de:',
   array['Ascendencia común entre esas especies', 'La ausencia total de cualquier relación evolutiva entre las especies', 'Que esas especies surgieron de forma completamente independiente', 'Que la evolución nunca ocurrió entre esos grupos'],
   'Las estructuras homólogas, aunque tengan funciones diferentes, comparten un origen evolutivo común.'),
  ('c7798651-498f-4b36-99d6-70a8ff58cd3f', 'en',
   'The resistance of certain bacteria to antibiotics, observed over time, is a current, observable example of:',
   array['Natural selection in action', 'A phenomenon that never occurs in nature', 'A completely random process, unrelated to survival', 'A complete absence of genetic variability in bacterial populations'],
   'Bacteria with mutations that confer resistance survive and reproduce preferentially, a direct example of natural selection.'),
  ('c7798651-498f-4b36-99d6-70a8ff58cd3f', 'es',
   'La resistencia de ciertas bacterias a los antibióticos, observada a lo largo del tiempo, es un ejemplo actual y observable de:',
   array['La selección natural en acción', 'Un fenómeno que nunca ocurre en la naturaleza', 'Un proceso completamente aleatorio, sin ninguna relación con la supervivencia', 'La ausencia total de variabilidad genética en las poblaciones bacterianas'],
   'Las bacterias con mutaciones que confieren resistencia sobreviven y se reproducen preferentemente, un ejemplo directo de selección natural.'),
  ('a0d9614c-51e1-4727-ba14-c3d48a61aebc', 'en',
   'Convergent evolution occurs when species that are not closely related independently develop similar characteristics because of:',
   array['Similar selective pressures in similar environments', 'Necessarily sharing a recent common ancestor', 'No relationship with the environment they live in', 'An identical mutation occurring simultaneously in both species'],
   'Convergent evolution explains, for example, the similar body shape of dolphins and sharks, both adapted to similar aquatic environments.'),
  ('a0d9614c-51e1-4727-ba14-c3d48a61aebc', 'es',
   'La evolución convergente ocurre cuando especies no emparentadas directamente desarrollan, de forma independiente, características semejantes debido a:',
   array['Presiones selectivas semejantes en ambientes parecidos', 'Compartir obligatoriamente un ancestro común reciente', 'Ninguna relación con el ambiente en que viven', 'Una mutación idéntica ocurrida simultáneamente en las dos especies'],
   'La evolución convergente explica, por ejemplo, la semejanza en la forma del cuerpo de los delfines y los tiburones, adaptados a ambientes acuáticos semejantes.'),
  ('4ae90696-321d-4dd8-b3bf-a4104a78bb98', 'en',
   'Alleles are defined as:',
   array['Different forms (versions) of the same gene, occupying the same position on homologous chromosomes', 'Completely different genes, with no relationship to each other', 'Cytoplasmic organelles', 'Proteins produced by a single gene'],
   'Alleles are variations of the same gene and can produce different versions of the same characteristic.'),
  ('4ae90696-321d-4dd8-b3bf-a4104a78bb98', 'es',
   'Los alelos se definen como:',
   array['Diferentes formas (versiones) de un mismo gen, que ocupan la misma posición en cromosomas homólogos', 'Genes completamente distintos, sin ninguna relación entre sí', 'Orgánulos citoplasmáticos', 'Proteínas producidas por un único gen'],
   'Los alelos son variaciones de un mismo gen y pueden generar distintas versiones de una misma característica.'),
  ('a7951f74-503a-4e07-bd76-89b944daea59', 'en',
   'In a diploid organism, such as a human, each characteristic is usually controlled by:',
   array['Two alleles, one inherited from each parent', 'A single allele only', 'Three or more alleles at the same time, always', 'No allele, only by the environment'],
   'Diploid organisms have pairs of homologous chromosomes, carrying two alleles for each characteristic.'),
  ('a7951f74-503a-4e07-bd76-89b944daea59', 'es',
   'En un organismo diploide, como el ser humano, cada característica suele estar controlada por:',
   array['Dos alelos, uno heredado de cada progenitor', 'Un único alelo solamente', 'Tres o más alelos al mismo tiempo, siempre', 'Ningún alelo, solo por el ambiente'],
   'Los organismos diploides tienen pares de cromosomas homólogos y portan dos alelos para cada característica.'),
  ('252a1e31-979a-4aa2-83a1-45fe6d97bac6', 'en',
   'When the two alleles of a pair are identical, the individual is classified, for that characteristic, as:',
   array['Homozygous', 'Heterozygous', 'Hemizygous', 'Polyploid'],
   'Homozygosity occurs when the two inherited alleles are the same.'),
  ('252a1e31-979a-4aa2-83a1-45fe6d97bac6', 'es',
   'Cuando los dos alelos de un par son idénticos, el individuo se clasifica, para esa característica, como:',
   array['Homocigoto', 'Heterocigoto', 'Hemicigoto', 'Poliploide'],
   'La homocigosis ocurre cuando los dos alelos heredados son iguales entre sí.'),
  ('1956e01f-e433-47f1-8003-ca016547e588', 'en',
   'The term "dominant allele" refers to the one that:',
   array['Shows up in the phenotype even in heterozygosity, masking the effect of the recessive allele', 'Never shows up in the individual''s phenotype', 'Only shows up when present in a double dose', 'Is always less frequent in the population'],
   'The dominant allele determines the phenotype even with just one copy, overriding the recessive allele.'),
  ('1956e01f-e433-47f1-8003-ca016547e588', 'es',
   'El término "alelo dominante" se refiere a aquel que:',
   array['Se manifiesta en el fenotipo incluso en heterocigosis, enmascarando el efecto del alelo recesivo', 'Nunca se manifiesta en el fenotipo del individuo', 'Solo se manifiesta cuando está presente en dosis doble', 'Es siempre menos frecuente en la población'],
   'El alelo dominante determina el fenotipo incluso con una sola copia y se impone al alelo recesivo.'),
  ('a1c032f5-ce5f-4fd5-8375-dac8884d21df', 'en',
   'Eye color in humans, an example commonly studied in genetics, is influenced by different alleles that, combined, determine:',
   array['The observable phenotype of the characteristic', 'Only the individual''s sex', 'No visible phenotypic variation', 'Exclusively characteristics acquired during life'],
   'The specific combination of inherited alleles determines the phenotype, such as eye color.'),
  ('a1c032f5-ce5f-4fd5-8375-dac8884d21df', 'es',
   'El color de los ojos en los seres humanos, ejemplo muy estudiado en genética, está influido por diferentes alelos que, combinados, determinan:',
   array['El fenotipo observable de la característica', 'Solo el sexo del individuo', 'Ninguna variación fenotípica visible', 'Exclusivamente características adquiridas a lo largo de la vida'],
   'La combinación específica de los alelos heredados determina el fenotipo, como el color de los ojos.'),
  ('fcac50d8-4383-4f0b-866e-fb604e3aff9b', 'en',
   'An organism''s phenotype corresponds to:',
   array['Its observable characteristics, resulting from the interaction between genotype and environment', 'Only the combination of alleles it has', 'Exclusively internal, non-visible characteristics', 'A concept identical to genotype, with no difference'],
   'The phenotype is the visible expression of characteristics, influenced by genes and the environment.'),
  ('fcac50d8-4383-4f0b-866e-fb604e3aff9b', 'es',
   'El fenotipo de un organismo corresponde a:',
   array['Las características observables, resultantes de la interacción entre el genotipo y el ambiente', 'Solo la combinación de alelos que posee', 'Exclusivamente características internas, no visibles', 'Un concepto idéntico al de genotipo, sin ninguna diferencia'],
   'El fenotipo es la manifestación visible de las características, influida por los genes y por el ambiente.'),
  ('02b2c04b-c471-4f05-bcc5-e45570631312', 'en',
   'Two genetically identical plants can show different phenotypes if they are grown under different environmental conditions, which shows:',
   array['The influence of the environment on the expression of the phenotype', 'That the genotype has no influence on the phenotype', 'That phenotype and genotype are always identical', 'That mutations happen instantly in response to the environment'],
   'The phenotype results from the interaction between genotype and environment, even with an identical genotype.'),
  ('02b2c04b-c471-4f05-bcc5-e45570631312', 'es',
   'Dos plantas genéticamente idénticas pueden presentar fenotipos diferentes si se cultivan en condiciones ambientales distintas, lo que demuestra:',
   array['La influencia del ambiente en la expresión del fenotipo', 'Que el genotipo no tiene ninguna influencia sobre el fenotipo', 'Que el fenotipo y el genotipo son siempre idénticos', 'Que las mutaciones ocurren instantáneamente en respuesta al ambiente'],
   'El fenotipo resulta de la interacción entre el genotipo y el ambiente, incluso con un genotipo idéntico.'),
  ('0331938c-e47d-4633-97c7-910cc35aaed7', 'en',
   'The height of a plant, influenced by both genetics and the availability of nutrients and light, is an example of a characteristic that is:',
   array['Phenotypic, polygenic and multifactorial', 'Controlled exclusively by a single gene, with no environmental influence', 'Without any genetic basis', 'Identical to the plant''s genotype'],
   'Many phenotypic characteristics are influenced by multiple genes and environmental factors.'),
  ('0331938c-e47d-4633-97c7-910cc35aaed7', 'es',
   'La altura de una planta, influida tanto por la genética como por la disponibilidad de nutrientes y luz, es un ejemplo de característica:',
   array['Fenotípica, poligénica y multifactorial', 'Controlada exclusivamente por un único gen, sin influencia ambiental', 'Sin ninguna base genética', 'Idéntica al genotipo de la planta'],
   'Muchas características fenotípicas están influidas por múltiples genes y factores ambientales.'),
  ('29081264-30b6-42be-9d58-247bb3a1d7fe', 'en',
   'Skin color in humans is an example of a phenotypic characteristic that:',
   array['Results from the combined action of several genes (polygenic inheritance)', 'Is determined by a single gene, with only two possible alleles', 'Has no genetic component', 'Is determined exclusively by the environment, with no genetic influence'],
   'Human skin color is a classic example of polygenic inheritance.'),
  ('29081264-30b6-42be-9d58-247bb3a1d7fe', 'es',
   'El color de la piel en los seres humanos es un ejemplo de característica fenotípica que:',
   array['Resulta de la acción combinada de varios genes (herencia poligénica)', 'Está determinada por un único gen, con solo dos alelos posibles', 'No tiene ningún componente genético', 'Está determinada exclusivamente por el ambiente, sin influencia genética'],
   'El color de la piel humana es un ejemplo clásico de herencia poligénica.'),
  ('002dbd7b-b775-41c6-855c-99e3ff03131e', 'en',
   'Studying the relationship between genotype, environment and phenotype is fundamental to understanding:',
   array['How hereditary characteristics are expressed in varied ways in different contexts', 'Only processes completely independent of genetics', 'That the environment never influences an organism''s characteristics', 'That the phenotype is always identical to the genotype, with no exceptions'],
   'Understanding the genotype-environment-phenotype interaction is essential to many areas of biology and medicine.'),
  ('002dbd7b-b775-41c6-855c-99e3ff03131e', 'es',
   'El estudio de la relación entre genotipo, ambiente y fenotipo es fundamental para comprender:',
   array['Cómo las características hereditarias se expresan de formas variadas en distintos contextos', 'Solo procesos totalmente independientes de la genética', 'Que el ambiente nunca influye en las características de un organismo', 'Que el fenotipo es siempre idéntico al genotipo, sin excepciones'],
   'Comprender la interacción genotipo-ambiente-fenotipo es esencial para diversas áreas de la biología y la medicina.'),
  ('57548181-13cf-4521-8d4b-4dacbbe8e2e9', 'en',
   'A gene can be defined as:',
   array['A segment of DNA that contains the information to produce a specific protein or characteristic', 'A complete reproductive cell', 'A type of cell organelle', 'A structural protein of the cell membrane'],
   'The gene is the basic unit of heredity, a stretch of DNA that codes for a protein or characteristic.'),
  ('57548181-13cf-4521-8d4b-4dacbbe8e2e9', 'es',
   'Un gen puede definirse como:',
   array['Un segmento de ADN que contiene la información para producir una proteína o característica específica', 'Una célula reproductiva completa', 'Un tipo de orgánulo celular', 'Una proteína estructural de la membrana celular'],
   'El gen es la unidad básica de la herencia, un tramo de ADN que codifica una proteína o característica.'),
  ('a1dd0d94-1f6f-4457-b9e2-4f113a511f76', 'en',
   'Inside the cell, genes are located mainly:',
   array['Along the chromosomes, in the cell nucleus', 'Exclusively in the cytoplasm, outside the nucleus', 'Only in the mitochondria', 'Outside the cell, in the extracellular environment'],
   'Genes occupy specific positions (loci) along the chromosomes, in the nucleus of eukaryotic cells.'),
  ('a1dd0d94-1f6f-4457-b9e2-4f113a511f76', 'es',
   'Dentro de la célula, los genes se ubican principalmente:',
   array['A lo largo de los cromosomas, en el núcleo celular', 'Exclusivamente en el citoplasma, fuera del núcleo', 'Solo en las mitocondrias', 'Fuera de la célula, en el medio extracelular'],
   'Los genes ocupan posiciones específicas (loci) a lo largo de los cromosomas, en el núcleo de las células eucariotas.'),
  ('28684135-deb9-47e8-b411-697393ed8582', 'en',
   'The full set of an organism''s genes is called its:',
   array['Genome', 'Genotype only', 'Phenotype', 'Karyotype'],
   'The genome is the complete set of genetic material (all the genes) of an organism.'),
  ('28684135-deb9-47e8-b411-697393ed8582', 'es',
   'El conjunto total de los genes de un organismo se llama:',
   array['Genoma', 'Genotipo solamente', 'Fenotipo', 'Cariotipo'],
   'El genoma corresponde al conjunto completo de material genético (todos los genes) de un organismo.'),
  ('8a20d5f7-8abe-4eba-8de7-30e64f153b28', 'en',
   'Genetic mutations are:',
   array['Changes in the DNA sequence of a gene, which can give rise to new variations', 'The complete absence of genes in a cell', 'The mandatory, identical duplication of all chromosomes', 'A process that never occurs naturally'],
   'Mutations are changes in the genetic material that can create genetic variability.'),
  ('8a20d5f7-8abe-4eba-8de7-30e64f153b28', 'es',
   'Las mutaciones genéticas corresponden a:',
   array['Cambios en la secuencia de ADN de un gen, que pueden originar nuevas variaciones', 'La ausencia total de genes en una célula', 'La duplicación obligatoria e idéntica de todos los cromosomas', 'Un proceso que nunca ocurre de forma natural'],
   'Las mutaciones son alteraciones del material genético que pueden generar variabilidad genética.'),
  ('3dfa60f5-525e-473e-8b02-3b3f14811f99', 'en',
   'Genes are passed from parents to children, across generations, through:',
   array['The gametes (reproductive cells), during sexual reproduction', 'Exclusively the environment the individual lives in', 'Completely random processes, unrelated to the parents', 'Only the mother, never the father'],
   'In sexual reproduction, eggs and sperm each carry half of the genetic information of each parent.'),
  ('3dfa60f5-525e-473e-8b02-3b3f14811f99', 'es',
   'Los genes se transmiten de padres a hijos, a lo largo de las generaciones, mediante:',
   array['Los gametos (células reproductivas), durante la reproducción sexual', 'Exclusivamente el ambiente en que vive el individuo', 'Procesos completamente aleatorios, sin ninguna relación con los padres', 'Solo la madre, nunca el padre'],
   'En la reproducción sexual, los óvulos y los espermatozoides llevan la mitad de la información genética de cada progenitor.'),
  ('cc9de4d5-74b8-42c5-a02b-6c5b395a3ee4', 'en',
   'An individual''s genotype corresponds to:',
   array['The genetic makeup (combination of alleles) it has for a given characteristic', 'The individual''s physical, observable characteristics', 'Only characteristics acquired during life', 'The individual''s external appearance, exclusively'],
   'The genotype is the set of genes (alleles) an organism has, regardless of how they show up externally.'),
  ('cc9de4d5-74b8-42c5-a02b-6c5b395a3ee4', 'es',
   'El genotipo de un individuo corresponde a:',
   array['La constitución genética (combinación de alelos) que posee para una característica determinada', 'Las características físicas y observables del individuo', 'Solo las características adquiridas a lo largo de la vida', 'La apariencia externa del individuo, exclusivamente'],
   'El genotipo es el conjunto de genes (alelos) que posee un organismo, independientemente de su manifestación externa.'),
  ('f82bf984-a5e5-4863-a8c2-c497b0e9d430', 'en',
   'An individual with the genotype "Aa" for a given characteristic is classified as:',
   array['Heterozygous', 'Homozygous dominant', 'Homozygous recessive', 'With no possible genetic classification'],
   'The combination of different alleles ("A" and "a") characterizes a heterozygote.'),
  ('f82bf984-a5e5-4863-a8c2-c497b0e9d430', 'es',
   'Un individuo con genotipo "Aa" para una característica determinada se clasifica como:',
   array['Heterocigoto', 'Homocigoto dominante', 'Homocigoto recesivo', 'Sin ninguna clasificación genética posible'],
   'La combinación de alelos diferentes ("A" y "a") caracteriza a un heterocigoto.'),
  ('23da266d-97a4-4e73-9968-67559ce1aad3', 'en',
   'Two individuals can have identical phenotypes but different genotypes when one of them is:',
   array['Homozygous dominant (AA) and the other heterozygous (Aa) for a characteristic with complete dominance', 'Both homozygous recessive', 'Impossible, since genotype and phenotype are always identical', 'Of different species'],
   'With complete dominance, AA and Aa show the same dominant phenotype, despite having different genotypes.'),
  ('23da266d-97a4-4e73-9968-67559ce1aad3', 'es',
   'Dos individuos pueden tener fenotipos idénticos pero genotipos diferentes cuando uno de ellos es:',
   array['Homocigoto dominante (AA) y el otro heterocigoto (Aa) para una característica de dominancia completa', 'Ambos homocigotos recesivos', 'Imposible, pues el genotipo y el fenotipo son siempre idénticos', 'De especies diferentes'],
   'En la dominancia completa, AA y Aa presentan el mismo fenotipo dominante, a pesar de tener genotipos diferentes.'),
  ('6d1bec2a-edb0-4085-bbed-7d9371f992c0', 'en',
   'An individual''s genotype is determined at the moment of:',
   array['Fertilization, when the parental gametes join', 'Only after birth', 'Continuously throughout life, changing every day', 'Exclusively by the influence of the environment'],
   'The genotype is set at fertilization and usually remains stable throughout life.'),
  ('6d1bec2a-edb0-4085-bbed-7d9371f992c0', 'es',
   'El genotipo de un individuo se determina en el momento de:',
   array['La fecundación, con la unión de los gametos de los progenitores', 'Solo después del nacimiento', 'De forma continua a lo largo de toda la vida, cambiando cada día', 'Exclusivamente por la influencia del ambiente'],
   'El genotipo se establece en la fecundación y suele permanecer estable a lo largo de la vida.'),
  ('1d0ee9bc-9ddc-4d38-9633-3645a39d5a7b', 'en',
   'Studying the genotype is fundamental, among other applications, for:',
   array['Predicting the probability of passing on certain characteristics or hereditary diseases', 'Determining only an individual''s physical appearance', 'Completely replacing the need to study the phenotype', 'Predicting characteristics acquired during life, with no genetic basis'],
   'Knowing the genotype makes it possible to calculate the probability of inheriting characteristics and genetic diseases.'),
  ('1d0ee9bc-9ddc-4d38-9633-3645a39d5a7b', 'es',
   'El estudio del genotipo es fundamental, entre otras aplicaciones, para:',
   array['Predecir la probabilidad de transmisión de ciertas características o enfermedades hereditarias', 'Determinar exclusivamente la apariencia física de un individuo', 'Sustituir por completo la necesidad de estudiar el fenotipo', 'Predecir características adquiridas a lo largo de la vida, sin ninguna relación genética'],
   'Conocer el genotipo permite calcular las probabilidades de herencia de características y enfermedades genéticas.'),
  ('2fca4756-b7b8-4950-9a15-b5db024f45f2', 'en',
   'An individual is classified as heterozygous for a given characteristic when it:',
   array['Has two different alleles for that gene', 'Has two identical alleles for that gene', 'Has no allele for that gene', 'Has three or more alleles at the same time'],
   'Heterozygosity occurs when the two alleles inherited from the parents are different from each other (for example, "Aa").'),
  ('2fca4756-b7b8-4950-9a15-b5db024f45f2', 'es',
   'Un individuo se clasifica como heterocigoto para una característica determinada cuando:',
   array['Tiene dos alelos diferentes para ese gen', 'Tiene dos alelos idénticos para ese gen', 'No tiene ningún alelo para ese gen', 'Tiene tres o más alelos al mismo tiempo'],
   'La heterocigosis ocurre cuando los dos alelos heredados de los progenitores son diferentes entre sí (por ejemplo, "Aa").'),
  ('f85bb7df-d5fb-4d0c-a74c-8b3202ce5cff', 'en',
   'For a characteristic with complete dominance, a heterozygous individual (Aa) has a phenotype that is:',
   array['Identical to that of the homozygous dominant (AA)', 'Identical to that of the homozygous recessive (aa)', 'Intermediate between the two homozygotes', 'Completely unpredictable'],
   'With complete dominance, the dominant allele is fully expressed even in heterozygosity.'),
  ('f85bb7df-d5fb-4d0c-a74c-8b3202ce5cff', 'es',
   'En una característica de dominancia completa, un individuo heterocigoto (Aa) presenta un fenotipo:',
   array['Idéntico al del homocigoto dominante (AA)', 'Idéntico al del homocigoto recesivo (aa)', 'Intermedio entre los dos homocigotos', 'Completamente imprevisible'],
   'En la dominancia completa, el alelo dominante se expresa totalmente incluso en heterocigosis.'),
  ('c0513f72-5202-448c-8962-4b10720058b5', 'en',
   'In genetics, heterozygous individuals are often called:',
   array['Hybrids, for that characteristic', 'Pure-breeding, for that characteristic', 'Genetically identical clones', 'Sterile, with no ability to reproduce'],
   'The term "hybrid" refers to heterozygous individuals, which carry different alleles for a given characteristic.'),
  ('c0513f72-5202-448c-8962-4b10720058b5', 'es',
   'En genética, a los individuos heterocigotos se los suele llamar:',
   array['Híbridos, para esa característica', 'Puros, para esa característica', 'Clones genéticamente idénticos', 'Estériles, sin capacidad reproductiva'],
   'El término "híbrido" designa a los individuos heterocigotos, que portan alelos diferentes para una característica determinada.'),
  ('b0a88c52-f6e6-4e5a-ae93-8cc3dddd2244', 'en',
   'When two heterozygous individuals (Aa x Aa) are crossed for a characteristic with complete dominance, the expected genotypic ratio in the offspring is:',
   array['1 AA : 2 Aa : 1 aa', '3 AA : 1 aa, with no Aa', 'All offspring will necessarily be Aa', '1 AA : 1 aa, with no Aa'],
   'A cross between two heterozygotes produces, on average, the classic 1:2:1 genotypic ratio.'),
  ('b0a88c52-f6e6-4e5a-ae93-8cc3dddd2244', 'es',
   'Al cruzar dos individuos heterocigotos (Aa x Aa) para una característica de dominancia completa, la proporción genotípica esperada en la descendencia es de:',
   array['1 AA : 2 Aa : 1 aa', '3 AA : 1 aa, sin ningún Aa', 'Todos los descendientes serán necesariamente Aa', '1 AA : 1 aa, sin ningún Aa'],
   'El cruce entre dos heterocigotos genera, en promedio, la clásica proporción genotípica 1:2:1.'),
  ('d1ae83a3-9a18-4b8f-be30-a82ceb2bbc9a', 'en',
   'For characteristics with incomplete dominance or codominance, heterozygotes tend to show phenotypes that are:',
   array['Intermediate or combined between the two alleles, unlike complete dominance', 'Always identical to those of the homozygous dominant', 'Always identical to those of the homozygous recessive', 'Impossible to observe'],
   'Unlike complete dominance, in these cases heterozygotes show distinct phenotypes, either intermediate or combined.'),
  ('d1ae83a3-9a18-4b8f-be30-a82ceb2bbc9a', 'es',
   'En las características con dominancia incompleta o codominancia, los heterocigotos tienden a presentar fenotipos:',
   array['Intermedios o combinados entre los dos alelos, a diferencia de la dominancia completa', 'Siempre idénticos a los del homocigoto dominante', 'Siempre idénticos a los del homocigoto recesivo', 'Imposibles de observar'],
   'A diferencia de la dominancia completa, en estos casos los heterocigotos muestran fenotipos distintos, intermedios o combinados.'),
  ('08035d7e-53da-4308-ba25-97a8e19dee9f', 'en',
   'An individual is classified as homozygous for a given characteristic when it:',
   array['Has two identical alleles for that gene', 'Has two different alleles for that gene', 'Has no allele for that gene', 'Has three or more alleles at the same time'],
   'Homozygosity occurs when the two alleles inherited from the parents are identical.'),
  ('08035d7e-53da-4308-ba25-97a8e19dee9f', 'es',
   'Un individuo se clasifica como homocigoto para una característica determinada cuando:',
   array['Tiene dos alelos idénticos para ese gen', 'Tiene dos alelos diferentes para ese gen', 'No tiene ningún alelo para ese gen', 'Tiene tres o más alelos al mismo tiempo'],
   'La homocigosis ocurre cuando los dos alelos heredados de los progenitores son idénticos entre sí.'),
  ('d875b172-09e1-42e0-9dc4-3fc484680ca5', 'en',
   'An individual with the genotype "AA" is classified as:',
   array['Homozygous dominant', 'Homozygous recessive', 'Heterozygous', 'With no possible classification'],
   'Having two identical dominant alleles ("AA") characterizes a homozygous dominant individual.'),
  ('d875b172-09e1-42e0-9dc4-3fc484680ca5', 'es',
   'Un individuo con genotipo "AA" se clasifica como:',
   array['Homocigoto dominante', 'Homocigoto recesivo', 'Heterocigoto', 'Sin ninguna clasificación posible'],
   'La presencia de dos alelos dominantes idénticos ("AA") caracteriza a un homocigoto dominante.'),
  ('5fdab696-666f-467d-9cbc-3c77d48dcead', 'en',
   'An individual with the genotype "aa" is classified as:',
   array['Homozygous recessive', 'Homozygous dominant', 'Heterozygous', 'With no possible classification'],
   'Having two identical recessive alleles ("aa") characterizes a homozygous recessive individual.'),
  ('5fdab696-666f-467d-9cbc-3c77d48dcead', 'es',
   'Un individuo con genotipo "aa" se clasifica como:',
   array['Homocigoto recesivo', 'Homocigoto dominante', 'Heterocigoto', 'Sin ninguna clasificación posible'],
   'La presencia de dos alelos recesivos idénticos ("aa") caracteriza a un homocigoto recesivo.'),
  ('0c8081ac-7a62-4467-81cb-ab7fcd96f9a5', 'en',
   'When it self-fertilizes (or is crossed with another identical individual), a homozygous individual tends to produce offspring that are:',
   array['Genetically uniform for that characteristic, the same as the parent', 'Always genetically different from one another', 'Of completely random genotypes', 'Genetically unrelated to the parents'],
   'Since it passes on only one type of allele, a homozygote produces uniform offspring for the gene in question.'),
  ('0c8081ac-7a62-4467-81cb-ab7fcd96f9a5', 'es',
   'Al autofecundarse (o cruzarse con otro individuo idéntico), un individuo homocigoto tiende a generar descendientes:',
   array['Genéticamente uniformes para esa característica, iguales al progenitor', 'Siempre genéticamente diferentes entre sí', 'Con genotipos completamente aleatorios', 'Sin ninguna relación genética con los progenitores'],
   'Como solo transmite un único tipo de alelo, un homocigoto genera descendientes uniformes para el gen en cuestión.'),
  ('d0f96a5a-bbe2-40f0-abb0-8c0f26462054', 'en',
   'Only homozygous recessive individuals can express the recessive phenotype because:',
   array['The dominant allele, when present, masks the expression of the recessive allele', 'The recessive allele is always stronger than the dominant one', 'Homozygous recessive individuals have no alleles at all', 'There is no relationship between genotype and phenotype in this case'],
   'Since the dominant allele overrides the recessive one in heterozygosity, the recessive phenotype only shows up when the dominant allele is completely absent.'),
  ('d0f96a5a-bbe2-40f0-abb0-8c0f26462054', 'es',
   'Solo los individuos homocigotos recesivos pueden expresar el fenotipo recesivo porque:',
   array['El alelo dominante, cuando está presente, enmascara la expresión del alelo recesivo', 'El alelo recesivo es siempre más fuerte que el dominante', 'Los homocigotos recesivos no tienen ningún alelo', 'No existe ninguna relación entre genotipo y fenotipo en este caso'],
   'Como el alelo dominante se impone al recesivo en heterocigosis, el fenotipo recesivo solo se manifiesta en ausencia total del dominante.'),
  ('5df700f6-118e-4bfa-830c-635f0ef373f3', 'en',
   'In codominance, the two alleles of a heterozygote are expressed:',
   array['Simultaneously and fully, without blending, producing a combined phenotype', 'In an intermediate way, blending completely', 'With only one allele expressed, completely masking the other', 'With neither allele expressed'],
   'In codominance, both alleles show up fully and independently in the heterozygote''s phenotype.'),
  ('5df700f6-118e-4bfa-830c-635f0ef373f3', 'es',
   'En la codominancia, los dos alelos de un heterocigoto se expresan:',
   array['De forma simultánea y plena, sin mezclarse, generando un fenotipo combinado', 'De forma intermedia, mezclándose por completo', 'Solo uno de los alelos se expresa y enmascara totalmente al otro', 'Ninguno de los alelos se expresa'],
   'En la codominancia, ambos alelos se manifiestan de forma total e independiente en el fenotipo del heterocigoto.'),
  ('0371392d-7b72-4d58-ab4d-f28f419da2fd', 'en',
   'The ABO blood group system in humans is a classic example of codominance, seen mainly in the genotype:',
   array['IᴬIᴮ, which results in blood type AB', 'IᴬIᴼ, which results in blood type A', 'IᴼIᴼ, which results in blood type O', 'Only in individuals with blood type O'],
   'In the IᴬIᴮ genotype, the A and B alleles are expressed simultaneously, resulting in the AB blood phenotype.'),
  ('0371392d-7b72-4d58-ab4d-f28f419da2fd', 'es',
   'El sistema sanguíneo ABO, en los seres humanos, es un ejemplo clásico de codominancia, que se observa principalmente en el genotipo:',
   array['IᴬIᴮ, que da como resultado el grupo sanguíneo AB', 'IᴬIᴼ, que da como resultado el grupo sanguíneo A', 'IᴼIᴼ, que da como resultado el grupo sanguíneo O', 'Solo en individuos del grupo sanguíneo O'],
   'En el genotipo IᴬIᴮ, los alelos A y B se expresan simultáneamente, lo que da como resultado el fenotipo sanguíneo AB.'),
  ('98bd0ad2-8b11-418c-b087-b862fe1cd253', 'en',
   'The fundamental difference between codominance and incomplete dominance is that, in codominance:',
   array['Both parental phenotypes appear simultaneously and distinctly in the heterozygote, without blending', 'The two phenotypes always blend completely', 'One of the alleles is always completely dominant over the other', 'There is no difference between the two phenomena'],
   'In codominance, the phenotypes appear side by side; in incomplete dominance, they blend into an intermediate phenotype.'),
  ('98bd0ad2-8b11-418c-b087-b862fe1cd253', 'es',
   'La diferencia fundamental entre la codominancia y la dominancia incompleta es que, en la codominancia:',
   array['Los dos fenotipos parentales aparecen de forma simultánea y distinta en el heterocigoto, sin mezclarse', 'Ocurre siempre una mezcla completa de los dos fenotipos', 'Uno de los alelos es siempre completamente dominante sobre el otro', 'No existe ninguna diferencia entre los dos fenómenos'],
   'En la codominancia, los fenotipos aparecen uno junto al otro; en la dominancia incompleta, se mezclan en un fenotipo intermedio.'),
  ('53be6685-f018-49e8-a8d9-810cdce78e82', 'en',
   'A frequently cited example of codominance in animals is the coat pattern of certain cattle breeds, in which a heterozygous individual shows:',
   array['Distinct white and red hairs mixed on the same animal, without forming an intermediate color', 'A completely pink coat, uniform over the whole body', 'A coat identical to one of the parents, with no mixing', 'No hair at all'],
   'In cattle with codominant coat color, the heterozygote shows hairs of both colors distributed distinctly.'),
  ('53be6685-f018-49e8-a8d9-810cdce78e82', 'es',
   'Un ejemplo frecuente de codominancia en animales es el patrón del pelaje de ciertas razas de ganado, en el que un individuo heterocigoto presenta:',
   array['Pelos blancos y rojos bien distintos, mezclados en el mismo animal, sin formar un color intermedio', 'Un pelaje completamente rosado, uniforme en todo el cuerpo', 'Un pelaje idéntico al de uno de los progenitores, sin ninguna mezcla', 'La ausencia total de pelo'],
   'En el ganado con codominancia de color, el heterocigoto muestra pelos de los dos colores distribuidos de forma distinta.'),
  ('4e076384-d6f3-4ef9-85f4-e0048d4a188e', 'en',
   'Codominance reinforces the idea that, in genetics, the relationship between alleles can be:',
   array['Much more varied than just dominant or recessive', 'Always limited to only two possible patterns', 'Completely random, with no pattern', 'Identical in every case of genetic inheritance'],
   'Phenomena such as codominance and incomplete dominance show that the interaction between alleles is complex and varied.'),
  ('4e076384-d6f3-4ef9-85f4-e0048d4a188e', 'es',
   'La codominancia refuerza la idea de que, en genética, la relación entre alelos puede ser:',
   array['Mucho más variada que solo dominante o recesiva', 'Siempre limitada a solo dos patrones posibles', 'Completamente aleatoria, sin ningún patrón', 'Idéntica en todos los casos de herencia genética'],
   'Fenómenos como la codominancia y la dominancia incompleta muestran que la interacción entre alelos es compleja y variada.'),
  ('7120d873-9178-46c5-9ca3-b2f16b3be79e', 'en',
   'With complete dominance, the phenotype of the heterozygote (Aa) is:',
   array['Identical to that of the homozygous dominant (AA)', 'Intermediate between the two homozygotes', 'Identical to that of the homozygous recessive (aa)', 'Always unpredictable'],
   'With complete dominance, the dominant allele is fully expressed, masking the effect of the recessive allele.'),
  ('7120d873-9178-46c5-9ca3-b2f16b3be79e', 'es',
   'En la dominancia completa, el fenotipo del heterocigoto (Aa) es:',
   array['Idéntico al del homocigoto dominante (AA)', 'Intermedio entre los dos homocigotos', 'Idéntico al del homocigoto recesivo (aa)', 'Siempre imprevisible'],
   'En la dominancia completa, el alelo dominante se expresa íntegramente y enmascara el efecto del alelo recesivo.'),
  ('770fba1f-4534-498d-8f4d-f37d65052d61', 'en',
   'The color of pea seeds (yellow dominant over green), studied by Mendel, is a classic example of:',
   array['Complete dominance', 'Incomplete dominance', 'Codominance', 'Sex-linked inheritance'],
   'In the model Mendel studied, the allele for yellow seeds is completely dominant over the allele for green seeds.'),
  ('770fba1f-4534-498d-8f4d-f37d65052d61', 'es',
   'El color de las semillas de guisante (amarillo dominante sobre verde), estudiado por Mendel, es un ejemplo clásico de:',
   array['Dominancia completa', 'Dominancia incompleta', 'Codominancia', 'Herencia ligada al sexo'],
   'En el modelo que estudió Mendel, el alelo para semilla amarilla es completamente dominante sobre el alelo para semilla verde.'),
  ('28c558a0-9efc-4d3e-961c-03f5cf732132', 'en',
   'For a characteristic with complete dominance, how many different phenotypes are possible for a gene with two alleles (one dominant and one recessive)?',
   array['2 (dominant and recessive)', '3 (dominant, intermediate and recessive)', '4', '1, since they all have the same phenotype'],
   'With complete dominance, although there are three possible genotypes, there are only two phenotypes.'),
  ('28c558a0-9efc-4d3e-961c-03f5cf732132', 'es',
   'En una característica de dominancia completa, ¿cuántos fenotipos diferentes son posibles para un gen con dos alelos (uno dominante y uno recesivo)?',
   array['2 (dominante y recesivo)', '3 (dominante, intermedio y recesivo)', '4', '1, pues todos presentan el mismo fenotipo'],
   'En la dominancia completa, aunque existen tres genotipos posibles, solo hay dos fenotipos.'),
  ('850450ce-db27-4b4c-8d66-49dbd31e6144', 'en',
   'Looking at the phenotype of a dominant individual, without knowing its genotype, it is not possible to tell whether it is:',
   array['Homozygous dominant (AA) or heterozygous (Aa)', 'Homozygous dominant (AA) or homozygous recessive (aa)', 'Heterozygous (Aa) or homozygous recessive (aa)', 'Male or female'],
   'Since AA and Aa produce the same phenotype under complete dominance, the phenotype alone cannot tell these two genotypes apart.'),
  ('850450ce-db27-4b4c-8d66-49dbd31e6144', 'es',
   'Al analizar el fenotipo de un individuo dominante, sin conocer su genotipo, no es posible saber si es:',
   array['Homocigoto dominante (AA) o heterocigoto (Aa)', 'Homocigoto dominante (AA) u homocigoto recesivo (aa)', 'Heterocigoto (Aa) u homocigoto recesivo (aa)', 'Macho o hembra'],
   'Como AA y Aa producen el mismo fenotipo en la dominancia completa, el fenotipo por sí solo no distingue esos dos genotipos.'),
  ('fc3d00d5-0f80-42a8-9775-028d496a3e84', 'en',
   'A "test cross", used to determine the genotype of an individual with the dominant phenotype, consists of crossing it with an individual that is:',
   array['Homozygous recessive (aa)', 'Homozygous dominant (AA)', 'Of another species', 'Sterile, with no ability to reproduce'],
   'By crossing with a homozygous recessive, the genotype can be inferred from the proportion of recessive offspring.'),
  ('fc3d00d5-0f80-42a8-9775-028d496a3e84', 'es',
   'Un "cruce de prueba", usado para determinar el genotipo de un individuo de fenotipo dominante, consiste en cruzarlo con un individuo:',
   array['Homocigoto recesivo (aa)', 'Homocigoto dominante (AA)', 'De otra especie', 'Estéril, sin ninguna capacidad reproductiva'],
   'Al cruzarlo con un homocigoto recesivo, es posible inferir el genotipo por la proporción de descendientes recesivos.'),
  ('48302b6b-1064-4c6c-b261-4827f634668e', 'en',
   'With incomplete dominance, the phenotype of the heterozygote is:',
   array['Intermediate between the phenotypes of the two homozygotes', 'Identical to that of the homozygous dominant', 'Identical to that of the homozygous recessive', 'Always the same as the phenotype of one of the parents'],
   'With incomplete dominance, neither allele fully overrides the other, producing an intermediate phenotype.'),
  ('48302b6b-1064-4c6c-b261-4827f634668e', 'es',
   'En la dominancia incompleta, el fenotipo del heterocigoto es:',
   array['Intermedio entre los fenotipos de los dos homocigotos', 'Idéntico al del homocigoto dominante', 'Idéntico al del homocigoto recesivo', 'Siempre igual al fenotipo de uno de los progenitores'],
   'En la dominancia incompleta, ningún alelo se impone totalmente al otro, lo que genera un fenotipo intermedio.'),
  ('8c6b627b-f35a-4222-bd5a-6bb4dcaa1384', 'en',
   'In the four o''clock flower (Mirabilis jalapa), a classic example of incomplete dominance, crossing a red-flowered plant with a white-flowered plant produces offspring with flowers that are:',
   array['Pink (intermediate)', 'Red, identical to one of the parents', 'White, identical to the other parent', 'Impossible to predict'],
   'Combining the alleles for red and white results in an intermediate color (pink).'),
  ('8c6b627b-f35a-4222-bd5a-6bb4dcaa1384', 'es',
   'En el dondiego de noche (Mirabilis jalapa), ejemplo clásico de dominancia incompleta, al cruzar una planta de flor roja con una de flor blanca, se obtienen descendientes con flores de color:',
   array['Rosado (intermedio)', 'Rojo, idéntico a uno de los progenitores', 'Blanco, idéntico al otro progenitor', 'Imposible de predecir'],
   'La combinación de los alelos para rojo y blanco da como resultado un color intermedio (rosado).'),
  ('e6940fef-9ccb-4c96-b782-8af4b8dac467', 'en',
   'With incomplete dominance, unlike complete dominance, each different genotype (AA, Aa, aa) corresponds to:',
   array['A distinct, observable phenotype', 'Always the same phenotype, with no distinction', 'Only two possible phenotypes, as in complete dominance', 'No observable phenotype'],
   'With incomplete dominance, each of the three possible genotypes produces its own, distinguishable phenotype.'),
  ('e6940fef-9ccb-4c96-b782-8af4b8dac467', 'es',
   'En la dominancia incompleta, a diferencia de la dominancia completa, cada genotipo diferente (AA, Aa, aa) corresponde a:',
   array['Un fenotipo distinto y observable', 'Siempre el mismo fenotipo, sin ninguna distinción', 'Solo dos fenotipos posibles, como en la dominancia completa', 'Ningún fenotipo observable'],
   'En la dominancia incompleta, cada uno de los tres genotipos posibles genera un fenotipo propio y distinguible.'),
  ('210d4790-ee1d-450f-bed9-5cb3893c4838', 'en',
   'When two pink-flowered (heterozygous) plants are crossed in an example of incomplete dominance, the expected phenotypic ratio in the offspring is:',
   array['1 red : 2 pink : 1 white', '3 red : 1 white', 'All the flowers will be pink', '1 red : 1 white, with no pink'],
   'Since the phenotype directly reflects the genotype, the 1:2:1 ratio is also the observed phenotypic ratio.'),
  ('210d4790-ee1d-450f-bed9-5cb3893c4838', 'es',
   'Al cruzar dos plantas de flor rosada (heterocigotas) en un ejemplo de dominancia incompleta, la proporción fenotípica esperada en la descendencia es de:',
   array['1 roja : 2 rosadas : 1 blanca', '3 rojas : 1 blanca', 'Todas las flores serán rosadas', '1 roja : 1 blanca, sin ninguna rosada'],
   'Como el fenotipo refleja directamente el genotipo, la proporción 1:2:1 también es la proporción fenotípica observada.'),
  ('8825a2fa-b9c9-46bf-9d89-a885c84bec85', 'en',
   'Incomplete dominance shows that the relationship between the alleles of a gene can be more complex than simple complete dominance, because:',
   array['Neither allele fully overrides the other, producing an intermediate expression', 'One of the alleles always disappears completely', 'The alleles never interact with each other', 'The phenotype never reflects the genotype in this case'],
   'Incomplete dominance illustrates that the interaction between alleles can produce intermediate phenotypes.'),
  ('8825a2fa-b9c9-46bf-9d89-a885c84bec85', 'es',
   'La dominancia incompleta demuestra que la relación entre los alelos de un gen puede ser más compleja que la simple dominancia completa, porque:',
   array['Ningún alelo se impone totalmente al otro, lo que genera una expresión intermedia', 'Uno de los alelos siempre desaparece por completo', 'Los alelos nunca interactúan entre sí', 'El fenotipo nunca refleja el genotipo en este caso'],
   'La dominancia incompleta ilustra que la interacción entre alelos puede generar fenotipos intermedios.'),
  ('49a414b5-a3cb-4439-944a-2f2743391bf7', 'en',
   'Sex-linked inheritance refers to characteristics whose genes are located:',
   array['On the sex chromosomes, usually the X chromosome', 'Exclusively on the autosomes', 'Outside any chromosome', 'Only on the Y chromosome, without exception'],
   'Sex-linked inheritance involves genes on the sex chromosomes, with patterns different from autosomal ones.'),
  ('49a414b5-a3cb-4439-944a-2f2743391bf7', 'es',
   'La herencia ligada al sexo se refiere a características cuyos genes están ubicados:',
   array['En los cromosomas sexuales, generalmente en el cromosoma X', 'Exclusivamente en los autosomas', 'Fuera de cualquier cromosoma', 'Solo en el cromosoma Y, sin excepción'],
   'La herencia ligada al sexo implica genes presentes en los cromosomas sexuales, con patrones distintos de los autosómicos.'),
  ('1f584661-31b8-4cd9-97a5-98ef21b25b07', 'en',
   'Color blindness and hemophilia, human conditions commonly studied in genetics, are examples of inheritance that is:',
   array['Recessive and X-linked', 'Dominant and Y-linked', 'Exclusively Y-linked', 'Unrelated to the sex chromosomes'],
   'Both color blindness and hemophilia are caused by recessive alleles located on the X chromosome.'),
  ('1f584661-31b8-4cd9-97a5-98ef21b25b07', 'es',
   'El daltonismo y la hemofilia, afecciones humanas muy estudiadas en genética, son ejemplos de herencia:',
   array['Recesiva ligada al cromosoma X', 'Dominante ligada al cromosoma Y', 'Exclusivamente ligada al cromosoma Y', 'Sin ninguna relación con los cromosomas sexuales'],
   'Tanto el daltonismo como la hemofilia son causados por alelos recesivos ubicados en el cromosoma X.'),
  ('9567b5a1-c01a-400c-825f-e0ea74a6fef8', 'en',
   'Men are more often affected by X-linked recessive diseases, such as color blindness, mainly because they:',
   array['Have only one X chromosome, making them hemizygous for the genes on that chromosome', 'Have two X chromosomes, like women', 'Have no sex chromosome at all', 'Always automatically inherit two recessive alleles'],
   'With only one X (and one Y), men directly express any allele present on that single X chromosome.'),
  ('9567b5a1-c01a-400c-825f-e0ea74a6fef8', 'es',
   'Los hombres se ven afectados con más frecuencia por enfermedades recesivas ligadas al X, como el daltonismo, principalmente porque:',
   array['Tienen solo un cromosoma X, por lo que son hemicigotos para los genes de ese cromosoma', 'Tienen dos cromosomas X, como las mujeres', 'No tienen ningún cromosoma sexual', 'Heredan siempre dos alelos recesivos automáticamente'],
   'Con un solo X (y un Y), los hombres expresan directamente cualquier alelo presente en ese único cromosoma X.'),
  ('7139986d-7931-4347-85dc-27b243e05b35', 'en',
   'A woman who is heterozygous for an X-linked recessive disease but does not show the disease is called a:',
   array['Carrier', 'Affected homozygote', 'Hemizygote', 'Sterile individual'],
   'Heterozygous women do not show the disease but can pass it on to their children, so they are called carriers.'),
  ('7139986d-7931-4347-85dc-27b243e05b35', 'es',
   'Una mujer heterocigota para una enfermedad recesiva ligada al X, pero que no manifiesta la enfermedad, se llama:',
   array['Portadora', 'Homocigota afectada', 'Hemicigota', 'Estéril'],
   'Las mujeres heterocigotas no manifiestan la enfermedad, pero pueden transmitirla a sus hijos, por lo que se llaman portadoras.'),
  ('f616fc7e-f582-4bd1-9d74-d55580aaf168', 'en',
   'For a woman to show an X-linked recessive characteristic, she needs to:',
   array['Inherit the recessive allele on both X chromosomes (from her father and her mother)', 'Inherit the recessive allele from only one of her parents', 'Have only one X chromosome', 'She can never show this characteristic, regardless of inheritance'],
   'Since they have two X chromosomes, women need to inherit the recessive allele from both parents.'),
  ('f616fc7e-f582-4bd1-9d74-d55580aaf168', 'es',
   'Para que una mujer manifieste una característica recesiva ligada al X, necesita:',
   array['Heredar el alelo recesivo en ambos cromosomas X (del padre y de la madre)', 'Heredar el alelo recesivo de uno solo de los progenitores', 'Tener solo un cromosoma X', 'Nunca puede manifestar esa característica, independientemente de la herencia'],
   'Como tienen dos cromosomas X, las mujeres necesitan heredar el alelo recesivo de ambos progenitores.'),
  ('49c44cde-4f28-4e57-b44e-e616cd8c6ae9', 'en',
   'A pedigree chart is a graphic representation used to:',
   array['Illustrate the transmission of hereditary characteristics over generations of a family', 'Represent only the structure of a cell', 'Show the chemical composition of DNA', 'Indicate only the geographic location of a population'],
   'Pedigree charts organize information visually about how characteristics are inherited among members of a family.'),
  ('49c44cde-4f28-4e57-b44e-e616cd8c6ae9', 'es',
   'Una genealogía (árbol genealógico) es una representación gráfica usada para:',
   array['Ilustrar la transmisión de características hereditarias a lo largo de las generaciones de una familia', 'Representar exclusivamente la estructura de una célula', 'Mostrar la composición química del ADN', 'Indicar solo la ubicación geográfica de una población'],
   'Las genealogías organizan visualmente la información sobre la herencia de características entre los miembros de una familia.'),
  ('78eeef95-e0f9-4f29-a4ac-10414156feed', 'en',
   'In a pedigree chart, squares and circles are usually used to represent, respectively:',
   array['Male and female individuals', 'Affected and unaffected individuals, unrelated to sex', 'Different generations, unrelated to sex', 'Dominant and recessive genes'],
   'By convention, squares represent men and circles represent women in pedigree charts.'),
  ('78eeef95-e0f9-4f29-a4ac-10414156feed', 'es',
   'En una genealogía, los cuadrados y los círculos suelen usarse para representar, respectivamente:',
   array['Individuos de sexo masculino y de sexo femenino', 'Individuos afectados y no afectados, sin relación con el sexo', 'Generaciones diferentes, sin relación con el sexo', 'Genes dominantes y recesivos'],
   'Por convención, los cuadrados representan a los hombres y los círculos a las mujeres en las genealogías.'),
  ('80d8ec10-9594-401e-93ad-b460018a6963', 'en',
   'Filled-in (shaded) symbols in a pedigree chart usually indicate individuals who are:',
   array['Affected by the characteristic or condition being studied', 'Male, exclusively', 'Deceased, regardless of the condition', 'Those who never had children'],
   'The shading convention marks the individuals who show the phenotype being studied (affected).'),
  ('80d8ec10-9594-401e-93ad-b460018a6963', 'es',
   'Los símbolos rellenos (coloreados) en una genealogía suelen indicar individuos:',
   array['Afectados por la característica o afección estudiada', 'De sexo masculino, exclusivamente', 'Fallecidos, independientemente de la afección', 'Que nunca tuvieron hijos'],
   'La convención de relleno indica a los individuos que manifiestan el fenotipo en estudio (afectados).'),
  ('06fb8274-ddcd-454f-816f-8f840427519c', 'en',
   'Analyzing a pedigree chart can help determine whether a characteristic is inherited in a way that is:',
   array['Dominant or recessive, autosomal or sex-linked', 'Exclusively environmental, with no genetic component', 'Impossible to determine, even with enough data', 'Identical for every characteristic, with no variation'],
   'By observing the patterns of transmission over several generations, it is possible to infer the likely type of inheritance.'),
  ('06fb8274-ddcd-454f-816f-8f840427519c', 'es',
   'El análisis de una genealogía puede ayudar a determinar si una característica se hereda de forma:',
   array['Dominante o recesiva, autosómica o ligada al sexo', 'Exclusivamente ambiental, sin ningún componente genético', 'Imposible de determinar, incluso con datos suficientes', 'Idéntica en todas las características, sin ninguna variación'],
   'Al observar los patrones de transmisión a lo largo de varias generaciones, es posible inferir el tipo probable de herencia.'),
  ('e07738b8-a157-4719-816d-509b8f98a015', 'en',
   'In a pedigree chart, an X-linked recessive characteristic tends to appear more often in:',
   array['Male individuals', 'Female individuals', 'Men and women equally, with no difference', 'Only female individuals'],
   'Men (hemizygous for the X) express recessive characteristics linked to this chromosome more easily.'),
  ('e07738b8-a157-4719-816d-509b8f98a015', 'es',
   'En una genealogía, una característica recesiva ligada al X tiende a aparecer con mayor frecuencia en:',
   array['Individuos de sexo masculino', 'Individuos de sexo femenino', 'Hombres y mujeres por igual, sin ninguna diferencia', 'Solo individuos de sexo femenino'],
   'Los hombres (hemicigotos para el X) expresan con más facilidad las características recesivas ligadas a ese cromosoma.'),
  ('e54e29fe-266e-41bf-8f4b-fb2ac19b08ed', 'en',
   'Mendel''s First Law, also called the Law of Segregation, states that:',
   array['Each characteristic is determined by a pair of alleles, which separate during gamete formation', 'Two different characteristics are always inherited together, with no separation', 'All offspring are always identical to their parents', 'There is no relationship between genes and hereditary characteristics'],
   'According to the First Law, the two alleles of a gene separate during gamete formation.'),
  ('e54e29fe-266e-41bf-8f4b-fb2ac19b08ed', 'es',
   'La Primera Ley de Mendel, también llamada Ley de la Segregación, afirma que:',
   array['Cada característica está determinada por un par de alelos, que se separan durante la formación de los gametos', 'Dos características diferentes se heredan siempre juntas, sin separación', 'Todos los descendientes son siempre idénticos a los padres', 'No existe ninguna relación entre los genes y las características hereditarias'],
   'Según la Primera Ley, los dos alelos de un gen se separan durante la formación de los gametos.'),
  ('b76b7c5c-8bc7-4c0f-9a1e-ed2de4578d8b', 'en',
   'In a cross between a homozygous dominant individual (AA) and a homozygous recessive one (aa), the entire F1 generation has the genotype:',
   array['Heterozygous (Aa)', 'Homozygous dominant (AA)', 'Homozygous recessive (aa)', 'A random mix of different genotypes'],
   'Since each parent contributes only one type of allele, the whole F1 generation will be heterozygous (Aa).'),
  ('b76b7c5c-8bc7-4c0f-9a1e-ed2de4578d8b', 'es',
   'En el cruce entre un individuo homocigoto dominante (AA) y uno homocigoto recesivo (aa), toda la generación F1 tiene genotipo:',
   array['Heterocigoto (Aa)', 'Homocigoto dominante (AA)', 'Homocigoto recesivo (aa)', 'Una mezcla aleatoria de diferentes genotipos'],
   'Como cada progenitor aporta un único tipo de alelo, toda la generación F1 será heterocigota (Aa).'),
  ('ff4c89c2-858f-4861-94ea-0f5d0b0afbfe', 'en',
   'In Mendel''s classic pea experiment, when plants with smooth seeds (dominant) were crossed with plants with wrinkled seeds (recessive), the F1 generation had:',
   array['100% plants with smooth seeds', '100% plants with wrinkled seeds', '50% smooth and 50% wrinkled', 'A mix of seeds with an intermediate shape'],
   'Since the allele for smooth seeds is dominant, the whole heterozygous F1 generation showed the dominant phenotype.'),
  ('ff4c89c2-858f-4861-94ea-0f5d0b0afbfe', 'es',
   'En el experimento clásico de Mendel con guisantes, al cruzar plantas de semillas lisas (dominante) con plantas de semillas rugosas (recesivo), la generación F1 presentó:',
   array['100% de plantas con semillas lisas', '100% de plantas con semillas rugosas', '50% lisas y 50% rugosas', 'Una mezcla de semillas de forma intermedia'],
   'Como el alelo para semilla lisa es dominante, toda la generación F1, heterocigota, presentó el fenotipo dominante.'),
  ('6b2b8500-1f90-454a-b7c3-ff69b35c822d', 'en',
   'When the individuals of the F1 generation (heterozygous, Aa x Aa) are self-fertilized, Mendel''s First Law predicts, in the F2 generation, a classic phenotypic ratio of:',
   array['3 dominant : 1 recessive', '1 dominant : 1 recessive', '100% dominant, with no recessive', '100% recessive, with no dominant'],
   'The 3:1 phenotypic ratio is the classic signature of Mendelian segregation in heterozygotes.'),
  ('6b2b8500-1f90-454a-b7c3-ff69b35c822d', 'es',
   'Al autofecundar a los individuos de la generación F1 (heterocigotos, Aa x Aa), la Primera Ley de Mendel predice, en la generación F2, una proporción fenotípica clásica de:',
   array['3 dominantes : 1 recesivo', '1 dominante : 1 recesivo', '100% dominantes, sin ningún recesivo', '100% recesivos, sin ningún dominante'],
   'La proporción fenotípica 3:1 es la firma clásica de la segregación mendeliana en heterocigotos.'),
  ('69d7bc18-5625-462e-9b69-f254966004a3', 'en',
   'Mendel''s First Law is also known as the "Law of Purity of Gametes" because:',
   array['Each gamete carries only one allele of each pair, without mixing the two', 'Gametes never contain any genetic material', 'All of an individual''s gametes are always identical to one another', 'Gametes are formed with no relation to the parental alleles'],
   '"Purity of gametes" reflects the fact that, in meiosis, the alleles separate and each gamete receives only one of them.'),
  ('69d7bc18-5625-462e-9b69-f254966004a3', 'es',
   'La Primera Ley de Mendel también se conoce como "Ley de la Pureza de los Gametos" porque:',
   array['Cada gameto lleva solo un alelo de cada par, sin mezclar los dos', 'Los gametos nunca contienen material genético', 'Todos los gametos de un individuo son siempre idénticos entre sí', 'Los gametos se forman sin ninguna relación con los alelos de los progenitores'],
   'La "pureza de los gametos" refleja que, en la meiosis, los alelos se separan y cada gameto recibe solo uno de ellos.'),
  ('bc05f6ee-ca0b-4178-942a-f0031d91b1c0', 'en',
   'Mendel''s Second Law, also called the Law of Independent Assortment, states that:',
   array['Genes located on different chromosomes are inherited independently of each other', 'All characteristics are always inherited together, with no independence', 'Only one characteristic can be studied at a time, without exception', 'There is no relationship between the inheritance of different characteristics'],
   'The Second Law shows that genes on different chromosomes are distributed independently during gamete formation.'),
  ('bc05f6ee-ca0b-4178-942a-f0031d91b1c0', 'es',
   'La Segunda Ley de Mendel, también llamada Ley de la Segregación Independiente, establece que:',
   array['Los genes ubicados en cromosomas diferentes se heredan de forma independiente entre sí', 'Todas las características se heredan siempre juntas, sin ninguna independencia', 'Solo puede estudiarse una característica a la vez, sin excepción', 'No existe ninguna relación entre la herencia de diferentes características'],
   'La Segunda Ley muestra que los genes ubicados en cromosomas diferentes se distribuyen de forma independiente al formarse los gametos.'),
  ('76e464c6-689f-4fa2-abac-541933e9d993', 'en',
   'In Mendel''s classic dihybrid cross (for example, seed color and texture), the expected phenotypic ratio in the F2 generation, when two double heterozygotes are crossed, is:',
   array['9:3:3:1', '3:1', '1:1:1:1', '9:9'],
   'The classic 9:3:3:1 ratio results from the independent combination of two characteristics, each following 3:1.'),
  ('76e464c6-689f-4fa2-abac-541933e9d993', 'es',
   'En el clásico cruce dihíbrido de Mendel (por ejemplo, color y textura de la semilla), la proporción fenotípica esperada en la generación F2, al cruzar dos dobles heterocigotos, es de:',
   array['9:3:3:1', '3:1', '1:1:1:1', '9:9'],
   'La proporción clásica 9:3:3:1 resulta de la combinación independiente de dos características, cada una siguiendo 3:1.'),
  ('a6c0543d-d327-4fd8-9841-bad8703b8929', 'en',
   'Mendel''s Second Law only applies correctly when the genes studied are located:',
   array['On different chromosomes (or far enough apart on the same chromosome)', 'Always on the same chromosome, close to each other', 'Exclusively on the sex chromosome', 'Outside the cell nucleus'],
   'Genes very close together on the same chromosome (linked genes) tend to be inherited together, escaping independent assortment.'),
  ('a6c0543d-d327-4fd8-9841-bad8703b8929', 'es',
   'La Segunda Ley de Mendel solo se aplica correctamente cuando los genes estudiados están ubicados:',
   array['En cromosomas diferentes (o lo bastante alejados en el mismo cromosoma)', 'Siempre en el mismo cromosoma, cerca uno del otro', 'Exclusivamente en el cromosoma sexual', 'Fuera del núcleo celular'],
   'Los genes muy próximos en el mismo cromosoma (ligados) tienden a heredarse juntos y escapan a la segregación independiente.'),
  ('7a68980b-32b3-4e45-b5b1-bcd9f1f28ba6', 'en',
   'The cellular basis of Mendel''s Second Law is related to:',
   array['The random, independent distribution of homologous chromosomes during meiosis', 'The mandatory fusion of all chromosomes into a single gamete', 'The complete absence of cell division in gamete formation', 'The simultaneous duplication of all the organism''s genes'],
   'During meiosis, the pairs of homologous chromosomes separate independently.'),
  ('7a68980b-32b3-4e45-b5b1-bcd9f1f28ba6', 'es',
   'La base celular de la Segunda Ley de Mendel está relacionada con:',
   array['La distribución aleatoria e independiente de los cromosomas homólogos durante la meiosis', 'La fusión obligatoria de todos los cromosomas en un único gameto', 'La ausencia total de división celular en la formación de los gametos', 'La duplicación simultánea de todos los genes del organismo'],
   'Durante la meiosis, los pares de cromosomas homólogos se separan de forma independiente.'),
  ('d9ba9511-cfce-4693-ae4c-291e207f6c5e', 'en',
   'Mendel''s Second Law broadens the understanding of genetic inheritance by showing that:',
   array['Combining different characteristics can create great genetic variability in the offspring', 'Only one characteristic can be passed on at a time, in isolation', 'Genetic variability is impossible among individuals of the same species', 'All characteristics are always inherited identically among siblings'],
   'By considering multiple characteristics at the same time, the Second Law explains the diversity of genetic combinations.'),
  ('d9ba9511-cfce-4693-ae4c-291e207f6c5e', 'es',
   'La Segunda Ley de Mendel amplía la comprensión de la herencia genética al mostrar que:',
   array['La combinación de diferentes características puede generar una gran variabilidad genética en los descendientes', 'Solo puede transmitirse una característica a la vez, de forma aislada', 'La variabilidad genética es imposible entre individuos de la misma especie', 'Todas las características se heredan siempre de forma idéntica entre hermanos'],
   'Al considerar varias características a la vez, la Segunda Ley explica la diversidad de combinaciones genéticas.'),
  ('e67449d0-8878-44b7-b819-d723b1b08b2f', 'en',
   'The microorganisms studied by microbiology include, among other groups:',
   array['Bacteria, viruses, fungi and protozoa', 'Only large animals', 'Exclusively plants', 'Only human beings'],
   'Microbiology studies microscopic organisms, including bacteria, viruses, fungi and protozoa.'),
  ('e67449d0-8878-44b7-b819-d723b1b08b2f', 'es',
   'Los microorganismos que estudia la microbiología incluyen, entre otros grupos:',
   array['Bacterias, virus, hongos y protozoos', 'Solo animales de gran tamaño', 'Exclusivamente plantas', 'Solo seres humanos'],
   'La microbiología estudia organismos microscópicos, incluidos bacterias, virus, hongos y protozoos.'),
  ('c1a42de9-9802-406b-8e0b-3064d0546b87', 'en',
   'Bacteria are organisms classified as:',
   array['Prokaryotes, with no membrane-bound nucleus', 'Eukaryotes, with a well-defined nucleus', 'Exclusively multicellular organisms', 'Nonliving beings, with no metabolic activity'],
   'Bacteria are prokaryotic organisms, with no nucleus enclosed by a membrane.'),
  ('c1a42de9-9802-406b-8e0b-3064d0546b87', 'es',
   'Las bacterias son organismos clasificados como:',
   array['Procariotas, sin núcleo delimitado por membrana', 'Eucariotas, con un núcleo bien definido', 'Organismos exclusivamente multicelulares', 'Seres no vivos, sin ninguna actividad metabólica'],
   'Las bacterias son organismos procariotas, sin núcleo delimitado por membrana.'),
  ('de317203-1137-4260-a0aa-9afbcecfcc5a', 'en',
   'Viruses are often considered unusual biological structures because:',
